# Generated from apps/rentals/templates for serverless deployment.
TEMPLATES = {'accounts/account_detail.html': '{% extends "base.html" %}\n'
                                 '{% block title %}Chi tiết tài khoản: {{ target_user.username }} — QL Phòng Cho '
                                 'Thuê{% endblock %}\n'
                                 '{% block page_title %}Chi tiết tài khoản: {{ target_user.username }}{% endblock %}\n'
                                 '{% block page_subtitle %}Thông tin định danh, phạm vi phân quyền, trạng thái bảo mật '
                                 'và nhật ký hoạt động{% endblock %}\n'
                                 '\n'
                                 '{% block content %}\n'
                                 '<div class="page-actions" style="flex-wrap:wrap;gap:10px;">\n'
                                 '  <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">\n'
                                 '    <a class="btn" href="{% url \'accounts\' %}">← Danh sách tài khoản</a>\n'
                                 '    {% if can_edit %}\n'
                                 '    <a class="btn primary" href="{% url \'account-update\' target_user.id %}">Chỉnh '
                                 'sửa tài khoản</a>\n'
                                 '    {% endif %}\n'
                                 '    {% if can_reset_pw %}\n'
                                 '    <a class="btn" href="{% url \'account-reset-password\' target_user.id %}">Đặt '
                                 'lại mật khẩu</a>\n'
                                 '    {% endif %}\n'
                                 '  </div>\n'
                                 '</div>\n'
                                 '\n'
                                 '<section class="two-columns" style="margin-bottom:20px;">\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Thông tin tài khoản</h2>\n'
                                 '      <span class="status-pill {% if target_user.is_active %}active{% else '
                                 '%}inactive{% endif %}">\n'
                                 '        <b></b>{{ target_user.is_active|yesno:"Đang hoạt động,Đã khóa" }}\n'
                                 '      </span>\n'
                                 '    </div>\n'
                                 '    <div class="detail-grid">\n'
                                 '      <div><span>Username</span><strong>{{ target_user.username }}</strong></div>\n'
                                 '      <div><span>Họ và tên</span><strong>{{ target_user.get_full_name|default:"—" '
                                 '}}</strong></div>\n'
                                 '      <div><span>Vai trò</span><strong><span class="badge">{{ '
                                 'target_user.get_role_display }}</span>{% if target_user.is_superuser %} <span '
                                 'class="badge" style="background:#fef3c7;color:#92400e;">Superuser</span>{% endif '
                                 '%}</strong></div>\n'
                                 '      <div><span>Email</span><strong>{{ target_user.email|default:"—" '
                                 '}}</strong></div>\n'
                                 '      <div><span>Số điện thoại</span><strong>{{ target_user.phone|default:"—" '
                                 '}}</strong></div>\n'
                                 '      <div><span>Ngày tạo tài khoản</span><strong>{{ '
                                 'target_user.date_joined|date:"d/m/Y H:i" }}</strong></div>\n'
                                 '      <div><span>Đăng nhập gần nhất</span><strong>{% if target_user.last_login %}{{ '
                                 'target_user.last_login|date:"d/m/Y H:i" }}{% else %}Chưa đăng nhập{% endif '
                                 '%}</strong></div>\n'
                                 '      <div><span>Đổi mật khẩu gần nhất</span><strong>{% if '
                                 'target_user.password_changed_at %}{{ target_user.password_changed_at|date:"d/m/Y '
                                 'H:i" }}{% else %}—{% endif %}</strong></div>\n'
                                 '      <div><span>Buộc đổi mật khẩu</span><strong>{% if '
                                 'target_user.must_change_password %}<span style="color:#c2410c;">Có (Ở lần đăng nhập '
                                 'kế tiếp)</span>{% else %}Không{% endif %}</strong></div>\n'
                                 '      {% if not target_user.is_active or target_user.locked_at or '
                                 'target_user.lock_reason %}\n'
                                 '      <div><span>Thời điểm khóa</span><strong>{% if target_user.locked_at %}{{ '
                                 'target_user.locked_at|date:"d/m/Y H:i" }}{% else %}—{% endif %}</strong></div>\n'
                                 '      <div><span>Người thực hiện khóa</span><strong>{% if target_user.locked_by %}{{ '
                                 'target_user.locked_by.username }}{% else %}—{% endif %}</strong></div>\n'
                                 '      <div><span>Lý do khóa / mở</span><strong>{{ '
                                 'target_user.lock_reason|default:"—" }}</strong></div>\n'
                                 '      {% endif %}\n'
                                 '    </div>\n'
                                 '  </article>\n'
                                 '\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Phạm vi quản lý & Liên kết</h2>\n'
                                 '    </div>\n'
                                 '    <div class="detail-grid" style="margin-bottom:18px;">\n'
                                 '      <div>\n'
                                 '        <span>Chủ nhà quản lý</span>\n'
                                 '        <strong>\n'
                                 '          {% if target_user.managed_owner %}\n'
                                 '            {{ '
                                 'target_user.managed_owner.get_full_name|default:target_user.managed_owner.username '
                                 '}} ({{ target_user.managed_owner.username }})\n'
                                 "          {% elif target_user.role == 'owner' %}\n"
                                 '            Chính chủ (Sở hữu tòa nhà)\n'
                                 '          {% else %}\n'
                                 '            —\n'
                                 '          {% endif %}\n'
                                 '        </strong>\n'
                                 '      </div>\n'
                                 '      <div>\n'
                                 '        <span>Tòa nhà được phân công</span>\n'
                                 '        <strong>\n'
                                 '          {% with assigned=target_user.assigned_buildings.all %}\n'
                                 '            {% if assigned %}\n'
                                 '              {% for b in assigned %}{{ b.name }}{% if not forloop.last %}, {% endif '
                                 '%}{% endfor %}\n'
                                 '            {% else %}\n'
                                 '              —\n'
                                 '            {% endif %}\n'
                                 '          {% endwith %}\n'
                                 '        </strong>\n'
                                 '      </div>\n'
                                 "      {% if target_user.role == 'owner' %}\n"
                                 '      <div>\n'
                                 '        <span>Tòa nhà thuộc sở hữu</span>\n'
                                 '        <strong>\n'
                                 '          {% with owned=target_user.buildings.all %}\n'
                                 '            {% if owned %}\n'
                                 '              {% for b in owned %}{{ b.name }}{% if not forloop.last %}, {% endif '
                                 '%}{% endfor %}\n'
                                 '            {% else %}\n'
                                 '              Chưa có tòa nhà nào\n'
                                 '            {% endif %}\n'
                                 '          {% endwith %}\n'
                                 '        </strong>\n'
                                 '      </div>\n'
                                 '      {% endif %}\n'
                                 '      <div>\n'
                                 '        <span>Hồ sơ khách thuê liên kết</span>\n'
                                 '        <strong>\n'
                                 '          {% if target_user.tenant_profile %}\n'
                                 '            <a href="{% url \'tenant-detail\' target_user.tenant_profile.id %}" '
                                 'style="color:var(--primary);text-decoration:none;">\n'
                                 '              {{ target_user.tenant_profile.full_name }} ({{ '
                                 'target_user.tenant_profile.phone }})\n'
                                 '            </a>\n'
                                 '          {% else %}\n'
                                 '            Chưa liên kết\n'
                                 '          {% endif %}\n'
                                 '        </strong>\n'
                                 '      </div>\n'
                                 '    </div>\n'
                                 '\n'
                                 '    <hr style="border:0;border-top:1px solid var(--line);margin:16px 0;">\n'
                                 '    <h2 style="font-size:16px;margin-bottom:10px;">{% if target_user.is_active '
                                 '%}Khóa tài khoản{% else %}Mở khóa tài khoản{% endif %}</h2>\n'
                                 '    {% if can_lock %}\n'
                                 '    <form method="post" action="{% url \'account-toggle-lock\' target_user.id %}" '
                                 'onsubmit="return confirm(\'Xác nhận {% if target_user.is_active %}KHÓA{% else %}MỞ '
                                 'KHÓA{% endif %} tài khoản {{ target_user.username }}?\');">\n'
                                 '      {% csrf_token %}\n'
                                 '      <p style="margin-bottom:12px;">\n'
                                 '        <label for="{{ lock_form.reason.id_for_label }}">{{ lock_form.reason.label '
                                 '}}</label>\n'
                                 '        {{ lock_form.reason }}\n'
                                 '      </p>\n'
                                 '      <button class="btn" type="submit" style="{% if target_user.is_active '
                                 '%}color:var(--red);border-color:var(--red);{% else '
                                 '%}color:var(--green);border-color:var(--green);{% endif %}">\n'
                                 '        {% if target_user.is_active %}Khóa tài khoản này{% else %}Mở khóa tài khoản '
                                 'này{% endif %}\n'
                                 '      </button>\n'
                                 '    </form>\n'
                                 '    {% else %}\n'
                                 '    <p class="muted" style="margin:0;">{{ lock_denied_reason|default:"Bạn không thể '
                                 'khóa hoặc mở khóa tài khoản này." }}</p>\n'
                                 '    {% endif %}\n'
                                 '  </article>\n'
                                 '</section>\n'
                                 '\n'
                                 '<section class="two-columns">\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Lịch sử đăng nhập ({{ login_histories|length }})</h2>\n'
                                 '      <a class="btn compact" href="{% url \'login-history\' %}?user={{ '
                                 'target_user.id }}">Xem tất cả</a>\n'
                                 '    </div>\n'
                                 '    <div class="table-wrap">\n'
                                 '      <table>\n'
                                 '        <thead>\n'
                                 '          <tr>\n'
                                 '            <th>Thời điểm</th>\n'
                                 '            <th>Sự kiện</th>\n'
                                 '            <th>IP</th>\n'
                                 '            <th>Lý do / Ghi chú</th>\n'
                                 '          </tr>\n'
                                 '        </thead>\n'
                                 '        <tbody>\n'
                                 '          {% for h in login_histories %}\n'
                                 '          <tr>\n'
                                 '            <td>{{ h.occurred_at|date:"d/m/Y H:i:s" }}</td>\n'
                                 '            <td>\n'
                                 "              {% if h.event_type == 'login_success' %}\n"
                                 '                <span class="badge" style="background:#e5f7f0;color:#087b59;">{{ '
                                 'h.get_event_type_display }}</span>\n'
                                 "              {% elif h.event_type == 'login_failed' %}\n"
                                 '                <span class="badge" style="background:#ffebed;color:#ca3944;">{{ '
                                 'h.get_event_type_display }}</span>\n'
                                 '              {% else %}\n'
                                 '                <span class="badge">{{ h.get_event_type_display }}</span>\n'
                                 '              {% endif %}\n'
                                 '            </td>\n'
                                 '            <td>{{ h.ip_address|default:"—" }}</td>\n'
                                 '            <td>{{ h.failure_reason|default:"—" }}</td>\n'
                                 '          </tr>\n'
                                 '          {% empty %}\n'
                                 '          <tr><td colspan="4">Chưa có lịch sử đăng nhập cho tài khoản '
                                 'này.</td></tr>\n'
                                 '          {% endfor %}\n'
                                 '        </tbody>\n'
                                 '      </table>\n'
                                 '    </div>\n'
                                 '  </article>\n'
                                 '\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Nhật ký tác động tài khoản ({{ audit_logs|length }})</h2>\n'
                                 '    </div>\n'
                                 '    <div class="table-wrap">\n'
                                 '      <table>\n'
                                 '        <thead>\n'
                                 '          <tr>\n'
                                 '            <th>Thời điểm</th>\n'
                                 '            <th>Người thực hiện</th>\n'
                                 '            <th>Hành động</th>\n'
                                 '            <th>Lý do / Chi tiết</th>\n'
                                 '          </tr>\n'
                                 '        </thead>\n'
                                 '        <tbody>\n'
                                 '          {% for log in audit_logs %}\n'
                                 '          <tr>\n'
                                 '            <td>{{ log.occurred_at|date:"d/m/Y H:i" }}</td>\n'
                                 '            <td>{% if log.actor %}{{ log.actor.username }}{% else %}Hệ thống{% endif '
                                 '%}</td>\n'
                                 '            <td><span class="badge">{{ log.get_action_display }}</span></td>\n'
                                 '            <td>{{ log.reason|default:"—" }}</td>\n'
                                 '          </tr>\n'
                                 '          {% empty %}\n'
                                 '          <tr><td colspan="4">Chưa có nhật ký tác động nào.</td></tr>\n'
                                 '          {% endfor %}\n'
                                 '        </tbody>\n'
                                 '      </table>\n'
                                 '    </div>\n'
                                 '  </article>\n'
                                 '</section>\n'
                                 '{% endblock %}\n'
                                 '\n',
 'accounts/account_form.html': '{% extends "base.html" %}\n'
                               '{% block title %}{{ title }} — QL Phòng Cho Thuê{% endblock %}\n'
                               '{% block page_title %}{{ title }}{% endblock %}\n'
                               '{% block page_subtitle %}{% if is_create %}Tạo tài khoản mới và phân công phạm vi quản '
                               'lý hoặc liên kết khách thuê{% else %}Cập nhật thông tin tài khoản và phân công phạm vi '
                               'hoạt động{% endif %}{% endblock %}\n'
                               '\n'
                               '{% block content %}\n'
                               '<div class="page-actions">\n'
                               '  <a class="btn" href="{% if is_create %}{% url \'accounts\' %}{% else %}{% url '
                               '\'account-detail\' target_user.id %}{% endif %}">← Quay lại</a>\n'
                               '</div>\n'
                               '\n'
                               '<section class="panel form-panel" style="max-width:860px;">\n'
                               '  <div class="panel-heading" style="margin-bottom:20px;border-bottom:1px solid '
                               'var(--line);padding-bottom:12px;">\n'
                               '    <h2>{{ title }}</h2>\n'
                               '  </div>\n'
                               '\n'
                               '  <form method="post" novalidate>\n'
                               '    {% csrf_token %}\n'
                               '    {% if form.non_field_errors %}\n'
                               '    <div class="alert error" style="margin-bottom:18px;padding:12px '
                               '16px;border-radius:8px;background:#ffebed;color:#ca3944;">\n'
                               '      {% for err in form.non_field_errors %}<div>{{ err }}</div>{% endfor %}\n'
                               '    </div>\n'
                               '    {% endif %}\n'
                               '\n'
                               '    <div class="two-columns" style="gap:18px;">\n'
                               '      <div>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.username.id_for_label }}">{{ form.username.label }} '
                               '*</label>\n'
                               '          {{ form.username }}\n'
                               '          {% if form.username.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.username.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.last_name.id_for_label }}">{{ form.last_name.label '
                               '}}</label>\n'
                               '          {{ form.last_name }}\n'
                               '          {% if form.last_name.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.last_name.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.first_name.id_for_label }}">{{ form.first_name.label '
                               '}}</label>\n'
                               '          {{ form.first_name }}\n'
                               '          {% if form.first_name.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.first_name.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '      </div>\n'
                               '      <div>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.email.id_for_label }}">{{ form.email.label }}</label>\n'
                               '          {{ form.email }}\n'
                               '          {% if form.email.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.email.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.phone.id_for_label }}">{{ form.phone.label }}</label>\n'
                               '          {{ form.phone }}\n'
                               '          {% if form.phone.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.phone.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.role.id_for_label }}">{{ form.role.label }} *</label>\n'
                               '          {{ form.role }}\n'
                               '          {% if form.role.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.role.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '      </div>\n'
                               '    </div>\n'
                               '\n'
                               '    {% if is_create %}\n'
                               '    <div class="two-columns" '
                               'style="gap:18px;margin-top:8px;padding-top:14px;border-top:1px solid var(--line);">\n'
                               '      <div>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.password1.id_for_label }}">{{ form.password1.label }} '
                               '*</label>\n'
                               '          {{ form.password1 }}\n'
                               '          {% if form.password1.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.password1.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '      </div>\n'
                               '      <div>\n'
                               '        <p style="margin-bottom:14px;">\n'
                               '          <label for="{{ form.password2.id_for_label }}">{{ form.password2.label }} '
                               '*</label>\n'
                               '          {{ form.password2 }}\n'
                               '          {% if form.password2.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.password2.errors.0 '
                               '}}</small>{% endif %}\n'
                               '        </p>\n'
                               '      </div>\n'
                               '    </div>\n'
                               '    {% endif %}\n'
                               '\n'
                               '    <div style="margin-top:12px;padding:12px '
                               '16px;background:#fff7ed;border-radius:8px;border:1px solid var(--line);">\n'
                               '      <label '
                               'style="display:inline-flex;align-items:center;gap:8px;cursor:pointer;font-weight:600;">\n'
                               '        {{ form.is_active }}\n'
                               '        <span>{{ form.is_active.label }}</span>\n'
                               '      </label>\n'
                               '      {% if form.is_active.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.is_active.errors.0 '
                               '}}</small>{% endif %}\n'
                               '    </div>\n'
                               '\n'
                               '    <!-- Phân công theo vai trò -->\n'
                               '    <div id="scope-owner-section" '
                               'style="margin-top:20px;padding-top:16px;border-top:1px solid var(--line);">\n'
                               '      {% if is_admin_actor %}\n'
                               '      <h3 style="margin:0 0 10px 0;font-size:16px;">Phân công tòa nhà sở hữu (Dành cho '
                               'vai trò Chủ nhà)</h3>\n'
                               '      <p class="muted" style="margin-top:0;font-size:13px;">Chọn các tòa nhà được gán '
                               'quyền sở hữu cho chủ nhà này (tùy chọn).</p>\n'
                               '      <div style="max-height:200px;overflow-y:auto;padding:10px;border:1px solid '
                               'var(--line);border-radius:8px;">\n'
                               '        {{ form.owned_buildings }}\n'
                               '      </div>\n'
                               '      {% if form.owned_buildings.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ '
                               'form.owned_buildings.errors.0 }}</small>{% endif %}\n'
                               '      {% else %}\n'
                               '      {{ form.owned_buildings }}\n'
                               '      {% endif %}\n'
                               '    </div>\n'
                               '\n'
                               '    <div id="scope-staff-section" '
                               'style="margin-top:20px;padding-top:16px;border-top:1px solid var(--line);">\n'
                               '      <h3 style="margin:0 0 10px 0;font-size:16px;">Phân công quản lý (Dành cho vai '
                               'trò Nhân viên)</h3>\n'
                               '      {% if is_admin_actor %}\n'
                               '      <p style="margin-bottom:14px;">\n'
                               '        <label for="{{ form.managed_owner.id_for_label }}">{{ form.managed_owner.label '
                               '}}</label>\n'
                               '        {{ form.managed_owner }}\n'
                               '        {% if form.managed_owner.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.managed_owner.errors.0 '
                               '}}</small>{% endif %}\n'
                               '      </p>\n'
                               '      {% else %}\n'
                               '      {{ form.managed_owner }}\n'
                               '      {% if form.managed_owner.errors %}<small '
                               'style="color:var(--red);display:block;margin-bottom:8px;">{{ '
                               'form.managed_owner.errors.0 }}</small>{% endif %}\n'
                               '      {% endif %}\n'
                               '      <p style="margin-bottom:8px;"><label>{{ form.assigned_buildings.label '
                               '}}</label></p>\n'
                               '      <div style="max-height:200px;overflow-y:auto;padding:10px;border:1px solid '
                               'var(--line);border-radius:8px;">\n'
                               '        {{ form.assigned_buildings }}\n'
                               '      </div>\n'
                               '      {% if form.assigned_buildings.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ '
                               'form.assigned_buildings.errors.0 }}</small>{% endif %}\n'
                               '    </div>\n'
                               '\n'
                               '    <div id="scope-tenant-section" '
                               'style="margin-top:20px;padding-top:16px;border-top:1px solid var(--line);">\n'
                               '      <h3 style="margin:0 0 10px 0;font-size:16px;">Liên kết hồ sơ khách thuê (Dành '
                               'cho vai trò Khách thuê)</h3>\n'
                               '      <p class="muted" style="margin-top:0;font-size:13px;">Chỉ hiển thị các hồ sơ '
                               'khách thuê thuộc phạm vi quản lý của bạn và chưa gắn với tài khoản khác. Khi liên kết, '
                               'họ tên, email và SĐT sẽ được đồng bộ.</p>\n'
                               '      <p style="margin-bottom:14px;">\n'
                               '        <label for="{{ form.linked_tenant.id_for_label }}">{{ form.linked_tenant.label '
                               '}}</label>\n'
                               '        {{ form.linked_tenant }}\n'
                               '        {% if form.linked_tenant.errors %}<small '
                               'style="color:var(--red);display:block;margin-top:4px;">{{ form.linked_tenant.errors.0 '
                               '}}</small>{% endif %}\n'
                               '      </p>\n'
                               '    </div>\n'
                               '\n'
                               '    <div class="actions" style="margin-top:24px;padding-top:16px;border-top:1px solid '
                               'var(--line);">\n'
                               '      <button class="btn primary" type="submit">{% if is_create %}Tạo tài khoản{% else '
                               '%}Lưu thay đổi{% endif %}</button>\n'
                               '      <a class="btn" href="{% if is_create %}{% url \'accounts\' %}{% else %}{% url '
                               '\'account-detail\' target_user.id %}{% endif %}">Hủy</a>\n'
                               '    </div>\n'
                               '  </form>\n'
                               '</section>\n'
                               '\n'
                               '<script>\n'
                               '(function(){\n'
                               '  const roleSelect = document.getElementById("id_role");\n'
                               '  const ownerSec = document.getElementById("scope-owner-section");\n'
                               '  const staffSec = document.getElementById("scope-staff-section");\n'
                               '  const tenantSec = document.getElementById("scope-tenant-section");\n'
                               '  const syncSections = () => {\n'
                               '    if (!roleSelect) return;\n'
                               '    const role = roleSelect.value;\n'
                               '    if (ownerSec) ownerSec.style.display = (role === "owner") ? "block" : "none";\n'
                               '    if (staffSec) staffSec.style.display = (role === "staff") ? "block" : "none";\n'
                               '    if (tenantSec) tenantSec.style.display = (role === "tenant") ? "block" : "none";\n'
                               '  };\n'
                               '  if (roleSelect) {\n'
                               '    roleSelect.addEventListener("change", syncSections);\n'
                               '    syncSections();\n'
                               '  }\n'
                               '})();\n'
                               '</script>\n'
                               '{% endblock %}\n'
                               '\n',
 'accounts/account_list.html': '{% extends "base.html" %}\n'
                               '{% block title %}Quản lý tài khoản — QL Phòng Cho Thuê{% endblock %}\n'
                               '{% block page_title %}Quản lý tài khoản{% endblock %}\n'
                               '{% block page_subtitle %}Quản lý tài khoản người dùng, phân công phạm vi, trạng thái '
                               'hoạt động và bảo mật{% endblock %}\n'
                               '\n'
                               '{% block content %}\n'
                               '<div class="page-actions room-toolbar" style="flex-wrap:wrap;gap:12px;">\n'
                               '  <form method="get" class="room-filters" style="flex-wrap:wrap;">\n'
                               '    <input name="q" value="{{ q }}" placeholder="Tìm username, họ tên, email, '
                               'SĐT...">\n'
                               '    <select name="role">\n'
                               '      <option value="">Tất cả vai trò</option>\n'
                               '      {% for val, label in role_choices %}\n'
                               '      <option value="{{ val }}" {% if role == val %}selected{% endif %}>{{ label '
                               '}}</option>\n'
                               '      {% endfor %}\n'
                               '    </select>\n'
                               '    <select name="status">\n'
                               '      <option value="">Tất cả trạng thái</option>\n'
                               '      <option value="active" {% if status == \'active\' %}selected{% endif %}>Đang '
                               'hoạt động</option>\n'
                               '      <option value="locked" {% if status == \'locked\' %}selected{% endif %}>Đã '
                               'khóa</option>\n'
                               '    </select>\n'
                               '    {% if owners %}\n'
                               '    <select name="owner">\n'
                               '      <option value="">Tất cả chủ nhà</option>\n'
                               '      {% for o in owners %}\n'
                               '      <option value="{{ o.id }}" {% if selected_owner == o.id|stringformat:"s" '
                               '%}selected{% endif %}>{{ o.get_full_name|default:o.username }}</option>\n'
                               '      {% endfor %}\n'
                               '    </select>\n'
                               '    {% endif %}\n'
                               '    {% if buildings %}\n'
                               '    <select name="building">\n'
                               '      <option value="">Tất cả tòa nhà</option>\n'
                               '      {% for b in buildings %}\n'
                               '      <option value="{{ b.id }}" {% if selected_building == b.id|stringformat:"s" '
                               '%}selected{% endif %}>{{ b.name }}</option>\n'
                               '      {% endfor %}\n'
                               '    </select>\n'
                               '    {% endif %}\n'
                               '    <select name="sort">\n'
                               '      <option value="newest" {% if sort == \'newest\' %}selected{% endif %}>Mới tạo '
                               'nhất</option>\n'
                               '      <option value="oldest" {% if sort == \'oldest\' %}selected{% endif %}>Cũ '
                               'nhất</option>\n'
                               '      <option value="name" {% if sort == \'name\' %}selected{% endif %}>Theo tên '
                               '(A-Z)</option>\n'
                               '      <option value="last_login" {% if sort == \'last_login\' %}selected{% endif '
                               '%}>Đăng nhập gần nhất</option>\n'
                               '    </select>\n'
                               '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                               '    {% if q or role or status or selected_owner or selected_building or sort != '
                               "'newest' %}\n"
                               '    <a class="btn" href="{% url \'accounts\' %}">Xóa lọc</a>\n'
                               '    {% endif %}\n'
                               '  </form>\n'
                               '  <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">\n'
                               '    <a class="btn" href="{% url \'login-history\' %}">Lịch sử đăng nhập</a>\n'
                               '    <a class="btn" href="{% url \'permission-matrix\' %}">Ma trận quyền</a>\n'
                               '    {% if can_create_account %}\n'
                               '    <a class="btn primary" href="{% url \'account-create\' %}">+ Thêm tài khoản</a>\n'
                               '    {% endif %}\n'
                               '  </div>\n'
                               '</div>\n'
                               '\n'
                               '<section class="panel">\n'
                               '  <div class="list-summary" style="flex-wrap:wrap;gap:12px;">\n'
                               '    <span>Danh sách tài khoản (Kết quả lọc: <strong>{{ paginator.count '
                               '}}</strong>)</span>\n'
                               '    <span style="display:flex;gap:14px;">\n'
                               '      <span>Tổng phạm vi: <strong>{{ total_accounts }}</strong></span>\n'
                               '      <span>Hoạt động: <strong style="color:#087b59;">{{ active_accounts '
                               '}}</strong></span>\n'
                               '      <span>Đã khóa: <strong style="color:#ca3944;">{{ locked_accounts '
                               '}}</strong></span>\n'
                               '    </span>\n'
                               '  </div>\n'
                               '  <div class="table-wrap">\n'
                               '    <table>\n'
                               '      <thead>\n'
                               '        <tr>\n'
                               '          <th class="row-number">STT</th>\n'
                               '          <th>Username</th>\n'
                               '          <th>Họ và tên</th>\n'
                               '          <th>Email</th>\n'
                               '          <th>Số điện thoại</th>\n'
                               '          <th>Vai trò</th>\n'
                               '          <th>Chủ nhà quản lý</th>\n'
                               '          <th>Tòa nhà phân công / sở hữu</th>\n'
                               '          <th>Hồ sơ khách thuê</th>\n'
                               '          <th>Trạng thái</th>\n'
                               '          <th>Đăng nhập gần nhất</th>\n'
                               '          <th>Ngày tạo</th>\n'
                               '          <th>Thao tác</th>\n'
                               '        </tr>\n'
                               '      </thead>\n'
                               '      <tbody>\n'
                               '        {% for x in objects %}\n'
                               '        <tr>\n'
                               '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                               '          <td>\n'
                               '            <a href="{% url \'account-detail\' x.id %}" '
                               'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ x.username '
                               '}}</a>\n'
                               '            {% if x.is_superuser %}<small class="badge" '
                               'style="margin-left:4px;background:#fef3c7;color:#92400e;">Superuser</small>{% endif '
                               '%}\n'
                               '            {% if x.must_change_password %}<small class="badge" '
                               'style="margin-left:4px;background:#fff7ed;color:#c2410c;">Chờ đổi MK</small>{% endif '
                               '%}\n'
                               '          </td>\n'
                               '          <td>{{ x.get_full_name|default:"—" }}</td>\n'
                               '          <td>{{ x.email|default:"—" }}</td>\n'
                               '          <td>{{ x.phone|default:"—" }}</td>\n'
                               '          <td>\n'
                               "            {% if x.role == 'admin' %}\n"
                               '              <span class="badge" style="background:#ede9fe;color:#5b21b6;">{{ '
                               'x.get_role_display }}</span>\n'
                               "            {% elif x.role == 'owner' %}\n"
                               '              <span class="badge" style="background:#e0f2fe;color:#0369a1;">{{ '
                               'x.get_role_display }}</span>\n'
                               "            {% elif x.role == 'staff' %}\n"
                               '              <span class="badge" style="background:#fef9c3;color:#854d0e;">{{ '
                               'x.get_role_display }}</span>\n'
                               '            {% else %}\n'
                               '              <span class="badge" style="background:#f1f5f9;color:#334155;">{{ '
                               'x.get_role_display }}</span>\n'
                               '            {% endif %}\n'
                               '          </td>\n'
                               '          <td>\n'
                               '            {% if x.managed_owner %}\n'
                               '              {{ x.managed_owner.get_full_name|default:x.managed_owner.username }}\n'
                               "            {% elif x.role == 'owner' %}\n"
                               '              <span class="muted">Chính chủ</span>\n'
                               '            {% elif x.tenant_profile and x.tenant_profile.owner %}\n'
                               '              {{ '
                               'x.tenant_profile.owner.get_full_name|default:x.tenant_profile.owner.username }}\n'
                               '            {% else %}\n'
                               '              —\n'
                               '            {% endif %}\n'
                               '          </td>\n'
                               '          <td>\n'
                               "            {% if x.role == 'staff' %}\n"
                               '              {% with b_list=x.assigned_buildings.all %}\n'
                               '                {% if b_list %}\n'
                               '                  {% for b in b_list %}<span class="badge" style="margin:1px;">{{ '
                               'b.name }}</span>{% endfor %}\n'
                               '                {% else %}\n'
                               '                  <span class="muted">Theo chủ nhà</span>\n'
                               '                {% endif %}\n'
                               '              {% endwith %}\n'
                               "            {% elif x.role == 'owner' %}\n"
                               '              {% with b_list=x.buildings.all %}\n'
                               '                {% if b_list %}\n'
                               '                  {% for b in b_list %}<span class="badge" style="margin:1px;">{{ '
                               'b.name }}</span>{% endfor %}\n'
                               '                {% else %}\n'
                               '                  <span class="muted">Chưa có tòa nhà</span>\n'
                               '                {% endif %}\n'
                               '              {% endwith %}\n'
                               '            {% else %}\n'
                               '              —\n'
                               '            {% endif %}\n'
                               '          </td>\n'
                               '          <td>\n'
                               '            {% if x.tenant_profile %}\n'
                               '              <a href="{% url \'tenant-detail\' x.tenant_profile.id %}" '
                               'style="color:var(--primary);text-decoration:none;font-weight:500;">{{ '
                               'x.tenant_profile.full_name }}</a>\n'
                               '            {% else %}\n'
                               '              <span class="muted">—</span>\n'
                               '            {% endif %}\n'
                               '          </td>\n'
                               '          <td>\n'
                               '            <span class="status-pill {% if x.is_active %}active{% else %}inactive{% '
                               'endif %}">\n'
                               '              <b></b>{{ x.is_active|yesno:"Đang hoạt động,Đã khóa" }}\n'
                               '            </span>\n'
                               '          </td>\n'
                               '          <td>{% if x.last_login %}{{ x.last_login|date:"d/m/Y H:i" }}{% else %}<span '
                               'class="muted">Chưa đăng nhập</span>{% endif %}</td>\n'
                               '          <td>{{ x.date_joined|date:"d/m/Y" }}</td>\n'
                               '          <td>\n'
                               '            <div style="display:flex;gap:5px;flex-wrap:wrap;align-items:center;">\n'
                               '              <a class="btn compact" href="{% url \'account-detail\' x.id %}">Xem</a>\n'
                               '              {% if x.can_edit %}\n'
                               '              <a class="btn compact" href="{% url \'account-update\' x.id %}">Sửa</a>\n'
                               '              {% endif %}\n'
                               '              {% if x.can_reset_pw %}\n'
                               '              <a class="btn compact" href="{% url \'account-reset-password\' x.id '
                               '%}">Đặt lại MK</a>\n'
                               '              {% endif %}\n'
                               '              {% if x.can_lock %}\n'
                               '              <form method="post" action="{% url \'account-toggle-lock\' x.id %}" '
                               'style="display:inline;" onsubmit="return confirm(\'Bạn có chắc chắn muốn {% if '
                               'x.is_active %}KHÓA{% else %}MỞ KHÓA{% endif %} tài khoản {{ x.username }}?\');">\n'
                               '                {% csrf_token %}\n'
                               '                <input type="hidden" name="next" value="{{ request.get_full_path }}">\n'
                               '                <input type="hidden" name="reason" value="{% if x.is_active %}Khóa từ '
                               'danh sách tài khoản{% else %}Mở khóa từ danh sách tài khoản{% endif %}">\n'
                               '                <button class="btn compact" type="submit" style="{% if x.is_active '
                               '%}color:var(--red);border-color:var(--red);{% else '
                               '%}color:var(--green);border-color:var(--green);{% endif %}">\n'
                               '                  {% if x.is_active %}Khóa{% else %}Mở{% endif %}\n'
                               '                </button>\n'
                               '              </form>\n'
                               '              {% endif %}\n'
                               '            </div>\n'
                               '          </td>\n'
                               '        </tr>\n'
                               '        {% empty %}\n'
                               '        <tr><td colspan="13" style="text-align:center;padding:28px;">Không tìm thấy '
                               'tài khoản nào phù hợp với bộ lọc hiện tại.</td></tr>\n'
                               '        {% endfor %}\n'
                               '      </tbody>\n'
                               '    </table>\n'
                               '  </div>\n'
                               '</section>\n'
                               '\n'
                               '{% if page_obj.has_other_pages %}\n'
                               '<nav class="pagination" aria-label="Phân trang tài khoản">\n'
                               '  {% if page_obj.has_previous %}\n'
                               '    <a href="?page={{ page_obj.previous_page_number }}{% if filter_query %}&{{ '
                               'filter_query }}{% endif %}">← Trước</a>\n'
                               '  {% else %}\n'
                               '    <span class="disabled">← Trước</span>\n'
                               '  {% endif %}\n'
                               '  {% for page_number in paginator.page_range %}\n'
                               '    {% if page_number == page_obj.number %}\n'
                               '      <span class="current">{{ page_number }}</span>\n'
                               "    {% elif page_number >= page_obj.number|add:'-2' and page_number <= "
                               "page_obj.number|add:'2' %}\n"
                               '      <a href="?page={{ page_number }}{% if filter_query %}&{{ filter_query }}{% endif '
                               '%}">{{ page_number }}</a>\n'
                               '    {% endif %}\n'
                               '  {% endfor %}\n'
                               '  {% if page_obj.has_next %}\n'
                               '    <a href="?page={{ page_obj.next_page_number }}{% if filter_query %}&{{ '
                               'filter_query }}{% endif %}">Sau →</a>\n'
                               '  {% else %}\n'
                               '    <span class="disabled">Sau →</span>\n'
                               '  {% endif %}\n'
                               '</nav>\n'
                               '{% endif %}\n'
                               '{% endblock %}\n'
                               '\n',
 'accounts/account_reset_password.html': '{% extends "base.html" %}\n'
                                         '{% block title %}{{ title }} — QL Phòng Cho Thuê{% endblock %}\n'
                                         '{% block page_title %}{{ title }}{% endblock %}\n'
                                         '{% block page_subtitle %}Đặt lại mật khẩu đăng nhập cho tài khoản người dùng '
                                         'trong phạm vi quản lý{% endblock %}\n'
                                         '\n'
                                         '{% block content %}\n'
                                         '<div class="page-actions">\n'
                                         '  <a class="btn" href="{% url \'account-detail\' target_user.id %}">← Quay '
                                         'lại chi tiết tài khoản</a>\n'
                                         '</div>\n'
                                         '\n'
                                         '<section class="panel form-panel" style="max-width:620px;">\n'
                                         '  <div class="panel-heading" style="margin-bottom:18px;border-bottom:1px '
                                         'solid var(--line);padding-bottom:12px;">\n'
                                         '    <h2>Đặt lại mật khẩu cho: {{ '
                                         'target_user.get_full_name|default:target_user.username }} ({{ '
                                         'target_user.username }})</h2>\n'
                                         '    <span class="badge">{{ target_user.get_role_display }}</span>\n'
                                         '  </div>\n'
                                         '\n'
                                         '  <form method="post" novalidate onsubmit="return confirm(\'Xác nhận đặt lại '
                                         'mật khẩu cho tài khoản {{ target_user.username }}? Các phiên đăng nhập cũ '
                                         'của tài khoản này sẽ bị hủy.\');">\n'
                                         '    {% csrf_token %}\n'
                                         '    {% if form.non_field_errors %}\n'
                                         '    <div class="alert error" style="margin-bottom:18px;padding:12px '
                                         '16px;border-radius:8px;background:#ffebed;color:#ca3944;">\n'
                                         '      {% for err in form.non_field_errors %}<div>{{ err }}</div>{% endfor '
                                         '%}\n'
                                         '    </div>\n'
                                         '    {% endif %}\n'
                                         '\n'
                                         '    <p style="margin-bottom:16px;">\n'
                                         '      <label for="{{ form.new_password1.id_for_label }}">{{ '
                                         'form.new_password1.label }} *</label>\n'
                                         '      {{ form.new_password1 }}\n'
                                         '      {% if form.new_password1.errors %}<small '
                                         'style="color:var(--red);display:block;margin-top:4px;">{{ '
                                         'form.new_password1.errors.0 }}</small>{% endif %}\n'
                                         '    </p>\n'
                                         '\n'
                                         '    <p style="margin-bottom:16px;">\n'
                                         '      <label for="{{ form.new_password2.id_for_label }}">{{ '
                                         'form.new_password2.label }} *</label>\n'
                                         '      {{ form.new_password2 }}\n'
                                         '      {% if form.new_password2.errors %}<small '
                                         'style="color:var(--red);display:block;margin-top:4px;">{{ '
                                         'form.new_password2.errors.0 }}</small>{% endif %}\n'
                                         '    </p>\n'
                                         '\n'
                                         '    <div style="margin-bottom:16px;padding:12px '
                                         '16px;background:#fff7ed;border-radius:8px;border:1px solid var(--line);">\n'
                                         '      <label '
                                         'style="display:inline-flex;align-items:center;gap:8px;cursor:pointer;font-weight:600;">\n'
                                         '        {{ form.must_change_password }}\n'
                                         '        <span>{{ form.must_change_password.label }}</span>\n'
                                         '      </label>\n'
                                         '    </div>\n'
                                         '\n'
                                         '    <p style="margin-bottom:18px;">\n'
                                         '      <label for="{{ form.reason.id_for_label }}">{{ form.reason.label '
                                         '}}</label>\n'
                                         '      {{ form.reason }}\n'
                                         '      {% if form.reason.errors %}<small '
                                         'style="color:var(--red);display:block;margin-top:4px;">{{ '
                                         'form.reason.errors.0 }}</small>{% endif %}\n'
                                         '    </p>\n'
                                         '\n'
                                         '    <div class="actions" style="padding-top:14px;border-top:1px solid '
                                         'var(--line);">\n'
                                         '      <button class="btn primary" type="submit">Xác nhận đặt lại mật '
                                         'khẩu</button>\n'
                                         '      <a class="btn" href="{% url \'account-detail\' target_user.id '
                                         '%}">Hủy</a>\n'
                                         '    </div>\n'
                                         '  </form>\n'
                                         '</section>\n'
                                         '{% endblock %}\n'
                                         '\n',
 'accounts/login_history.html': '{% extends "base.html" %}\n'
                                '{% block title %}Lịch sử đăng nhập — QL Phòng Cho Thuê{% endblock %}\n'
                                '{% block page_title %}Lịch sử đăng nhập{% endblock %}\n'
                                '{% block page_subtitle %}Theo dõi nhật ký đăng nhập thành công, đăng nhập thất bại và '
                                'đăng xuất{% endblock %}\n'
                                '\n'
                                '{% block content %}\n'
                                '<div class="page-actions room-toolbar" style="flex-wrap:wrap;gap:12px;">\n'
                                '  <form method="get" class="room-filters" style="flex-wrap:wrap;">\n'
                                '    <input name="q" value="{{ q }}" placeholder="Tìm username, IP, lý do...">\n'
                                '    <select name="event_type">\n'
                                '      <option value="">Tất cả sự kiện</option>\n'
                                '      {% for val, label in event_type_choices %}\n'
                                '      <option value="{{ val }}" {% if event_type == val %}selected{% endif %}>{{ '
                                'label }}</option>\n'
                                '      {% endfor %}\n'
                                '    </select>\n'
                                '    {% if accessible_users %}\n'
                                '    <select name="user">\n'
                                '      <option value="">Tất cả tài khoản</option>\n'
                                '      {% for u in accessible_users %}\n'
                                '      <option value="{{ u.id }}" {% if selected_user == u.id|stringformat:"s" '
                                '%}selected{% endif %}>{{ u.username }} ({{ u.get_role_display }})</option>\n'
                                '      {% endfor %}\n'
                                '    </select>\n'
                                '    {% endif %}\n'
                                '    <input type="date" name="date_from" value="{{ date_from }}" title="Từ ngày">\n'
                                '    <input type="date" name="date_to" value="{{ date_to }}" title="Đến ngày">\n'
                                '    <button class="btn" type="submit">Lọc lịch sử</button>\n'
                                '    {% if q or event_type or selected_user or date_from or date_to %}\n'
                                '    <a class="btn" href="{% url \'login-history\' %}">Xóa lọc</a>\n'
                                '    {% endif %}\n'
                                '  </form>\n'
                                "  {% if user|has_perm_code:'accounts.view_user' %}\n"
                                '  <a class="btn" href="{% url \'accounts\' %}">← Quản lý tài khoản</a>\n'
                                '  {% endif %}\n'
                                '</div>\n'
                                '\n'
                                '<section class="panel">\n'
                                '  <div class="list-summary">\n'
                                '    <span>Nhật ký phiên xác thực</span>\n'
                                '    <span>Tổng số bản ghi: <strong>{{ paginator.count }}</strong></span>\n'
                                '  </div>\n'
                                '  <div class="table-wrap">\n'
                                '    <table>\n'
                                '      <thead>\n'
                                '        <tr>\n'
                                '          <th class="row-number">STT</th>\n'
                                '          <th>Thời điểm</th>\n'
                                '          <th>Username thử đăng nhập</th>\n'
                                '          <th>Tài khoản hệ thống</th>\n'
                                '          <th>Loại sự kiện</th>\n'
                                '          <th>Địa chỉ IP</th>\n'
                                '          <th>Trình duyệt / Thiết bị</th>\n'
                                '          <th>Session</th>\n'
                                '          <th>Lý do thất bại</th>\n'
                                '        </tr>\n'
                                '      </thead>\n'
                                '      <tbody>\n'
                                '        {% for h in objects %}\n'
                                '        <tr>\n'
                                '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 '
                                '}}</td>\n'
                                '          <td>{{ h.occurred_at|date:"d/m/Y H:i:s" }}</td>\n'
                                '          <td><strong>{{ h.username_attempted }}</strong></td>\n'
                                '          <td>\n'
                                '            {% if h.user %}\n'
                                "              {% if user|has_perm_code:'accounts.view_user' %}\n"
                                '                <a href="{% url \'account-detail\' h.user.id %}" '
                                'style="color:var(--primary);text-decoration:none;font-weight:600;">{{ h.user.username '
                                '}}</a>\n'
                                '              {% else %}\n'
                                '                {{ h.user.username }}\n'
                                '              {% endif %}\n'
                                '              <small class="muted">({{ h.user.get_role_display }})</small>\n'
                                '            {% else %}\n'
                                '              <span class="muted">Không xác định</span>\n'
                                '            {% endif %}\n'
                                '          </td>\n'
                                '          <td>\n'
                                "            {% if h.event_type == 'login_success' %}\n"
                                '              <span class="badge" style="background:#e5f7f0;color:#087b59;">{{ '
                                'h.get_event_type_display }}</span>\n'
                                "            {% elif h.event_type == 'login_failed' %}\n"
                                '              <span class="badge" style="background:#ffebed;color:#ca3944;">{{ '
                                'h.get_event_type_display }}</span>\n'
                                '            {% else %}\n'
                                '              <span class="badge">{{ h.get_event_type_display }}</span>\n'
                                '            {% endif %}\n'
                                '          </td>\n'
                                '          <td>{{ h.ip_address|default:"—" }}</td>\n'
                                '          <td '
                                'style="max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" '
                                'title="{{ h.user_agent }}">{{ h.user_agent|default:"—" }}</td>\n'
                                '          <td><code>{{ h.session_key|slice:":10"|default:"—" }}</code></td>\n'
                                '          <td>{{ h.failure_reason|default:"—" }}</td>\n'
                                '        </tr>\n'
                                '        {% empty %}\n'
                                '        <tr><td colspan="9" style="text-align:center;padding:28px;">Chưa có bản ghi '
                                'lịch sử đăng nhập nào phù hợp.</td></tr>\n'
                                '        {% endfor %}\n'
                                '      </tbody>\n'
                                '    </table>\n'
                                '  </div>\n'
                                '</section>\n'
                                '\n'
                                '{% if page_obj.has_other_pages %}\n'
                                '<nav class="pagination" aria-label="Phân trang lịch sử đăng nhập">\n'
                                '  {% if page_obj.has_previous %}\n'
                                '    <a href="?page={{ page_obj.previous_page_number }}{% if filter_query %}&{{ '
                                'filter_query }}{% endif %}">← Trước</a>\n'
                                '  {% else %}\n'
                                '    <span class="disabled">← Trước</span>\n'
                                '  {% endif %}\n'
                                '  {% for page_number in paginator.page_range %}\n'
                                '    {% if page_number == page_obj.number %}\n'
                                '      <span class="current">{{ page_number }}</span>\n'
                                "    {% elif page_number >= page_obj.number|add:'-2' and page_number <= "
                                "page_obj.number|add:'2' %}\n"
                                '      <a href="?page={{ page_number }}{% if filter_query %}&{{ filter_query }}{% '
                                'endif %}">{{ page_number }}</a>\n'
                                '    {% endif %}\n'
                                '  {% endfor %}\n'
                                '  {% if page_obj.has_next %}\n'
                                '    <a href="?page={{ page_obj.next_page_number }}{% if filter_query %}&{{ '
                                'filter_query }}{% endif %}">Sau →</a>\n'
                                '  {% else %}\n'
                                '    <span class="disabled">Sau →</span>\n'
                                '  {% endif %}\n'
                                '</nav>\n'
                                '{% endif %}\n'
                                '{% endblock %}\n'
                                '\n',
 'accounts/permission_matrix.html': '{% extends "base.html" %}\n'
                                    '{% block title %}Ma trận phân quyền — QL Phòng Cho Thuê{% endblock %}\n'
                                    '{% block page_title %}Ma trận quyền truy cập{% endblock %}\n'
                                    '{% block page_subtitle %}Bảng đối chiếu quyền hạn và phạm vi dữ liệu giữa các vai '
                                    'trò trong hệ thống (đồng bộ trực tiếp từ cấu hình phân quyền backend){% endblock '
                                    '%}\n'
                                    '\n'
                                    '{% block content %}\n'
                                    '<div class="page-actions" '
                                    'style="justify-content:space-between;flex-wrap:wrap;gap:10px;">\n'
                                    '  <div style="display:flex;gap:8px;align-items:center;">\n'
                                    "    {% if user|has_perm_code:'accounts.view_user' %}\n"
                                    '    <a class="btn" href="{% url \'accounts\' %}">← Quản lý tài khoản</a>\n'
                                    '    {% endif %}\n'
                                    '    <a class="btn" href="{% url \'login-history\' %}">Lịch sử đăng nhập</a>\n'
                                    '  </div>\n'
                                    '  <span class="badge" style="background:#e0f2fe;color:#0369a1;">Chế độ chỉ đọc '
                                    '(Read-only) · Vai trò hiện tại của bạn: {{ user.get_role_display }}</span>\n'
                                    '</div>\n'
                                    '\n'
                                    '{% for row in matrix_rows %}\n'
                                    '<section class="panel" style="margin-bottom:18px;">\n'
                                    '  <div class="panel-heading" style="flex-wrap:wrap;gap:8px;">\n'
                                    '    <div>\n'
                                    '      <h2 style="margin:0;">{{ forloop.counter }}. {{ row.name }}</h2>\n'
                                    '      <small class="muted">{{ row.description }}</small>\n'
                                    '    </div>\n'
                                    '  </div>\n'
                                    '  <div class="table-wrap">\n'
                                    '    <table>\n'
                                    '      <thead>\n'
                                    '        <tr>\n'
                                    '          <th style="width:200px;">Vai trò</th>\n'
                                    '          <th style="width:90px;text-align:center;">Xem</th>\n'
                                    '          <th style="width:90px;text-align:center;">Tạo</th>\n'
                                    '          <th style="width:90px;text-align:center;">Sửa</th>\n'
                                    '          <th style="width:110px;text-align:center;">Khóa / Hủy</th>\n'
                                    '          <th>Phạm vi dữ liệu áp dụng</th>\n'
                                    '        </tr>\n'
                                    '      </thead>\n'
                                    '      <tbody>\n'
                                    '        {% for cell in row.role_cells %}\n'
                                    '        <tr>\n'
                                    '          <td><strong>{{ cell.role_label }}</strong></td>\n'
                                    '          <td style="text-align:center;">\n'
                                    '            {% if cell.view %}<span class="badge" '
                                    'style="background:#e5f7f0;color:#087b59;">Có</span>{% else %}<span '
                                    'class="muted">Không</span>{% endif %}\n'
                                    '          </td>\n'
                                    '          <td style="text-align:center;">\n'
                                    '            {% if cell.create %}<span class="badge" '
                                    'style="background:#e5f7f0;color:#087b59;">Có</span>{% else %}<span '
                                    'class="muted">Không</span>{% endif %}\n'
                                    '          </td>\n'
                                    '          <td style="text-align:center;">\n'
                                    '            {% if cell.change %}<span class="badge" '
                                    'style="background:#e5f7f0;color:#087b59;">Có</span>{% else %}<span '
                                    'class="muted">Không</span>{% endif %}\n'
                                    '          </td>\n'
                                    '          <td style="text-align:center;">\n'
                                    '            {% if cell.lock_or_cancel %}<span class="badge" '
                                    'style="background:#e5f7f0;color:#087b59;">Có</span>{% else %}<span '
                                    'class="muted">Không</span>{% endif %}\n'
                                    '          </td>\n'
                                    '          <td>{{ cell.scope }}</td>\n'
                                    '        </tr>\n'
                                    '        {% endfor %}\n'
                                    '      </tbody>\n'
                                    '    </table>\n'
                                    '  </div>\n'
                                    '</section>\n'
                                    '{% endfor %}\n'
                                    '{% endblock %}\n'
                                    '\n',
 'accounts/profile.html': '{% extends "base.html" %}\n'
                          '{% block title %}Hồ sơ cá nhân — QL Phòng Cho Thuê{% endblock %}\n'
                          '{% block page_title %}Hồ sơ cá nhân{% endblock %}\n'
                          '{% block page_subtitle %}Quản lý thông tin tài khoản và thông tin cá nhân của bạn{% '
                          'endblock %}\n'
                          '\n'
                          '{% block content %}\n'
                          '<div class="profile-layout" style="display: grid; grid-template-columns: 280px 1fr; gap: '
                          '24px; align-items: start;">\n'
                          '  <!-- Thẻ thông tin tóm tắt -->\n'
                          '  <section class="panel" style="text-align: center; padding: 28px 20px;">\n'
                          '    <div class="profile-avatar">{% if user.avatar %}<img src="{{ user.avatar.url }}" '
                          'alt="Ảnh đại diện của {{ user.get_full_name|default:user.username }}">{% else %}<span>{{ '
                          'user.username|first|upper }}</span>{% endif %}</div>\n'
                          '    <form method="post" enctype="multipart/form-data" class="profile-avatar-form">\n'
                          '      {% csrf_token %}<input type="hidden" name="profile_action" value="avatar">\n'
                          '      <label for="id_avatar" class="btn">Chọn ảnh đại diện</label>\n'
                          '      {{ avatar_form.avatar }}\n'
                          '      <span id="avatar-selected-name" class="profile-avatar-selected" '
                          'aria-live="polite"></span>\n'
                          '      {% if avatar_form.avatar.errors %}<small class="profile-avatar-error">{{ '
                          'avatar_form.avatar.errors.0 }}</small>{% endif %}\n'
                          '      <small>JPG, PNG hoặc WebP · tối đa 2 MB</small>\n'
                          '      <button class="btn primary" type="submit">Lưu ảnh</button>\n'
                          '    </form>\n'
                          '    <h2 style="margin: 0 0 6px 0; font-size: 20px;">{{ '
                          'user.get_full_name|default:user.username }}</h2>\n'
                          '    <span class="badge" style="margin-bottom: 16px; display: inline-block;">{{ '
                          'user.get_role_display }}</span>\n'
                          '\n'
                          '    <div style="text-align: left; border-top: 1px solid var(--line); padding-top: 16px; '
                          'margin-top: 16px; font-size: 13px; display: grid; gap: 10px;">\n'
                          '      <div>\n'
                          '        <span style="color: var(--muted); display: block;">Tên đăng nhập</span>\n'
                          '        <strong style="color: var(--ink);">{{ user.username }}</strong>\n'
                          '      </div>\n'
                          '      <div>\n'
                          '        <span style="color: var(--muted); display: block;">Ngày tham gia</span>\n'
                          '        <strong style="color: var(--ink);">{{ user.date_joined|date:"d/m/Y" }}</strong>\n'
                          '      </div>\n'
                          '      {% if tenant %}\n'
                          '      <div>\n'
                          '        <span style="color: var(--muted); display: block;">Trạng thái hồ sơ</span>\n'
                          '        <span class="badge" style="background: #e5f7f0; color: #087b59; font-size: '
                          '11px;">Đã kích hoạt</span>\n'
                          '      </div>\n'
                          '      {% endif %}\n'
                          '    </div>\n'
                          '\n'
                          '    <div style="margin-top: 24px; border-top: 1px solid var(--line); padding-top: 18px;">\n'
                          '      <a href="{% url \'password-change\' %}" class="btn full" style="display: inline-flex; '
                          'align-items: center; justify-content: center; gap: 8px;">\n'
                          '        <i data-lucide="key-round"></i>\n'
                          '        <span>Đổi mật khẩu</span>\n'
                          '      </a>\n'
                          '    </div>\n'
                          '  </section>\n'
                          '\n'
                          '  <!-- Form cập nhật thông tin -->\n'
                          '  <section class="panel form-panel" style="max-width: 100%;">\n'
                          '    <div class="panel-heading" style="margin-bottom: 20px; border-bottom: 1px solid '
                          'var(--line); padding-bottom: 12px;">\n'
                          '      <h2>{% if is_tenant %}Thông tin khách thuê{% else %}Cập nhật thông tin tài khoản{% '
                          'endif %}</h2>\n'
                          '    </div>\n'
                          '\n'
                          '    <form method="post" novalidate>\n'
                          '      {% csrf_token %}\n'
                          '      {% if form.errors %}\n'
                          '        <div class="alert error" style="margin-bottom: 20px;">\n'
                          '          Vui lòng kiểm tra lại các trường thông tin báo lỗi bên dưới.\n'
                          '        </div>\n'
                          '      {% endif %}\n'
                          '\n'
                          '      {% for field in form %}\n'
                          '        <p style="margin-bottom: 16px;">\n'
                          '          <label for="{{ field.id_for_label }}">{{ field.label }}:</label>\n'
                          '          <span>\n'
                          '            {{ field }}\n'
                          '            {% if field.errors %}\n'
                          '              <small style="color: var(--red); display: block; margin-top: 5px; '
                          'font-weight: 500;">{{ field.errors.0 }}</small>\n'
                          '            {% endif %}\n'
                          '            {% if field.help_text %}\n'
                          '              <small style="color: var(--muted); display: block; margin-top: 5px; '
                          'font-size: 12px;">{{ field.help_text }}</small>\n'
                          '            {% endif %}\n'
                          '          </span>\n'
                          '        </p>\n'
                          '      {% endfor %}\n'
                          '\n'
                          '      <div class="actions" style="margin-top: 28px; padding-top: 16px; border-top: 1px '
                          'solid var(--line);">\n'
                          '        <button class="btn primary" type="submit">Lưu thông tin</button>\n'
                          '        <a class="btn" href="{% if user.role == \'tenant\' %}{% url \'tenant-portal\' %}{% '
                          'else %}{% url \'dashboard\' %}{% endif %}">Quay lại</a>\n'
                          '      </div>\n'
                          '    </form>\n'
                          '  </section>\n'
                          '</div>\n'
                          '\n'
                          '<section class="panel" style="margin-top: 24px;">\n'
                          '  <div class="panel-heading">\n'
                          '    <h2>Lịch sử đăng nhập gần đây của bạn</h2>\n'
                          '    <a class="btn compact" href="{% url \'login-history\' %}">Xem toàn bộ lịch sử</a>\n'
                          '  </div>\n'
                          '  <div class="table-wrap">\n'
                          '    <table>\n'
                          '      <thead>\n'
                          '        <tr>\n'
                          '          <th>Thời điểm</th>\n'
                          '          <th>Sự kiện</th>\n'
                          '          <th>Địa chỉ IP</th>\n'
                          '          <th>Thiết bị / Trình duyệt</th>\n'
                          '          <th>Ghi chú</th>\n'
                          '        </tr>\n'
                          '      </thead>\n'
                          '      <tbody>\n'
                          '        {% for h in recent_login_history %}\n'
                          '        <tr>\n'
                          '          <td>{{ h.occurred_at|date:"d/m/Y H:i:s" }}</td>\n'
                          '          <td>\n'
                          "            {% if h.event_type == 'login_success' %}\n"
                          '              <span class="badge" style="background:#e5f7f0;color:#087b59;">{{ '
                          'h.get_event_type_display }}</span>\n'
                          "            {% elif h.event_type == 'login_failed' %}\n"
                          '              <span class="badge" style="background:#ffebed;color:#ca3944;">{{ '
                          'h.get_event_type_display }}</span>\n'
                          '            {% else %}\n'
                          '              <span class="badge">{{ h.get_event_type_display }}</span>\n'
                          '            {% endif %}\n'
                          '          </td>\n'
                          '          <td>{{ h.ip_address|default:"—" }}</td>\n'
                          '          <td '
                          'style="max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" '
                          'title="{{ h.user_agent }}">{{ h.user_agent|default:"—" }}</td>\n'
                          '          <td>{{ h.failure_reason|default:"—" }}</td>\n'
                          '        </tr>\n'
                          '        {% empty %}\n'
                          '        <tr><td colspan="5">Chưa có lịch sử đăng nhập nào được ghi nhận.</td></tr>\n'
                          '        {% endfor %}\n'
                          '      </tbody>\n'
                          '    </table>\n'
                          '  </div>\n'
                          '</section>\n'
                          '<script>\n'
                          "document.getElementById('id_avatar')?.addEventListener('change', function () {\n"
                          "  document.getElementById('avatar-selected-name').textContent = this.files?.[0]?.name || "
                          "'';\n"
                          '});\n'
                          '</script>\n'
                          '{% endblock %}\n'
                          '\n'
                          '\n',
 'base.html': '{% load static %}\n'
              '<!doctype html>\n'
              '<html lang="vi">\n'
              '<head>\n'
              '  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n'
              '  <title>{% block title %}Quản lý phòng cho thuê{% endblock %}</title>\n'
              '  <link rel="icon" type="image/png" href="{% static \'images/favicon.png\' %}">\n'
              '  <link rel="stylesheet" href="{% static \'css/loading.css\' %}">\n'
              '  <link rel="stylesheet" href="{% static \'css/app.css\' %}"><link rel="stylesheet" href="{% static '
              '\'css/pagination.css\' %}"><link rel="stylesheet" href="{% static \'css/room-map.css\' %}"><link '
              'rel="stylesheet" href="{% static \'css/room-map-compact.css\' %}"><link rel="stylesheet" href="{% '
              'static \'css/navigation.css\' %}"><link rel="stylesheet" href="{% static \'css/management.css\' '
              '%}"><link rel="stylesheet" href="{% static \'css/toast.css\' %}">\n'
              '  {% block extra_head %}{% endblock %}\n'
              "  {% if user.role != 'tenant' %}\n"
              '  <link rel="stylesheet" href="{% static \'css/admin-shell.css\' %}?v=admin-1">\n'
              '  <link rel="stylesheet" href="{% static \'css/admin-components.css\' %}?v=admin-1">\n'
              '  {% if request.resolver_match.url_name == \'dashboard\' %}<link rel="stylesheet" href="{% static '
              '\'css/admin-dashboard.css\' %}?v=admin-1">{% endif %}\n'
              '  {% endif %}\n'
              '</head>\n'
              '<body{% if user.role != \'tenant\' %} class="management-app"{% endif %}>\n'
              "  {% include 'includes/loading.html' %}\n"
              "  {% if user.role != 'tenant' %}<noscript><style>.management-app #site-loading { display: none; "
              '}</style></noscript>{% endif %}\n'
              '  {% if user.role != \'tenant\' %}<a class="admin-skip-link" href="#main-content">Bỏ qua '
              'menu</a><button class="admin-nav-backdrop" id="admin-nav-backdrop" type="button" aria-label="Đóng menu '
              'quản trị" tabindex="-1" hidden></button>{% endif %}\n'
              '  <aside class="sidebar" id="admin-sidebar" aria-label="Menu quản trị">\n'
              "    {% if user.role != 'tenant' %}\n"
              '    <div class="admin-sidebar-heading">\n'
              '      <a class="admin-brand" href="{% url \'dashboard\' %}"><i data-lucide="house"></i><span>QL Phòng '
              'Cho Thuê<small>Không gian quản lý</small></span></a>\n'
              '      <button class="admin-icon-button admin-menu-close" id="admin-menu-close" type="button" '
              'aria-label="Đóng menu"><i data-lucide="x"></i></button>\n'
              '    </div>\n'
              '    {% endif %}\n'
              '    <nav aria-label="Điều hướng chính">\n'
              "      {% if user.role == 'tenant' %}\n"
              '      <a class="{% if request.resolver_match.url_name == \'tenant-portal\' %}active{% endif %}" '
              'href="{% url \'tenant-portal\' %}"><i data-lucide="layout-dashboard"></i>Trang của tôi</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'tenant-rooms\' %}active{% endif %}" href="{% '
              'url \'tenant-rooms\' %}"><i data-lucide="bed-double"></i>Phòng của tôi</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'tenant-contracts\' %}active{% endif %}" '
              'href="{% url \'tenant-contracts\' %}"><i data-lucide="file-text"></i>Hợp đồng</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'tenant-invoices\' or '
              'request.resolver_match.url_name == \'tenant-invoice-detail\' %}active{% endif %}" href="{% url '
              '\'tenant-invoices\' %}"><i data-lucide="receipt-text"></i>Hóa đơn</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'tenant-payments\' %}active{% endif %}" '
              'href="{% url \'tenant-payments\' %}"><i data-lucide="wallet-cards"></i>Thanh toán</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'tenant-incidents\' or '
              'request.resolver_match.url_name == \'tenant-incident-create\' %}active{% endif %}" href="{% url '
              '\'tenant-incidents\' %}"><i data-lucide="triangle-alert"></i>Yêu cầu hỗ trợ</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'tenant-notifications\' %}active{% endif %}" '
              'href="{% url \'tenant-notifications\' %}"><i data-lucide="bell"></i>Thông báo</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'user-profile\' %}active{% endif %}" href="{% '
              'url \'user-profile\' %}"><i data-lucide="user"></i>Hồ sơ cá nhân</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'login-history\' %}active{% endif %}" '
              'href="{% url \'login-history\' %}"><i data-lucide="history"></i>Lịch sử đăng nhập</a>\n'
              '      <a class="{% if request.resolver_match.url_name == \'password-change\' %}active{% endif %}" '
              'href="{% url \'password-change\' %}"><i data-lucide="key-round"></i>Đổi mật khẩu</a>\n'
              '      {% else %}\n'
              '      <section class="nav-group is-open"><button class="nav-group-toggle" type="button"><i '
              'data-lucide="map"></i><span>Sơ đồ phòng</span><i data-lucide="chevron-down"></i></button><div '
              'class="nav-group-links"><a class="{% if request.resolver_match.url_name == \'room-map\' %}active{% '
              'endif %}" href="{% url \'room-map\' %}">Xem sơ đồ</a></div></section>\n'
              '      <section class="nav-group is-open"><button class="nav-group-toggle" type="button"><i '
              'data-lucide="building-2"></i><span>Quản lý cơ bản</span><i data-lucide="chevron-down"></i></button><div '
              'class="nav-group-links"><a class="{% if request.resolver_match.url_name == \'buildings\' or '
              "request.resolver_match.url_name == 'building-create' or request.resolver_match.url_name == "
              '\'building-update\' %}active{% endif %}" href="{% url \'buildings\' %}">Tòa nhà</a><a class="{% if '
              "request.resolver_match.url_name == 'rooms' or request.resolver_match.url_name == 'room-create' or "
              'request.resolver_match.url_name == \'room-update\' %}active{% endif %}" href="{% url \'rooms\' '
              '%}">Phòng</a><a class="{% if request.resolver_match.url_name == \'tenants\' or '
              "request.resolver_match.url_name == 'tenant-create' or request.resolver_match.url_name == "
              '\'tenant-detail\' or request.resolver_match.url_name == \'tenant-update\' %}active{% endif %}" href="{% '
              'url \'tenants\' %}">Khách thuê</a></div></section>\n'
              '      <a class="nav-single {% if request.resolver_match.url_name == \'dashboard\' %}active{% endif %}" '
              'href="{% url \'dashboard\' %}"><i data-lucide="chart-no-axes-column-increasing"></i>Thống kê</a>\n'
              '      {% if user|has_perm_code:\'accounts.view_user\' %}<section class="nav-group is-open"><button '
              'class="nav-group-toggle" type="button"><i data-lucide="shield"></i><span>Quản trị</span><i '
              'data-lucide="chevron-down"></i></button><div class="nav-group-links"><a class="{% if '
              "request.resolver_match.url_name == 'accounts' or request.resolver_match.url_name == 'account-create' or "
              "request.resolver_match.url_name == 'account-detail' or request.resolver_match.url_name == "
              "'account-update' or request.resolver_match.url_name == 'account-reset-password' %}active{% endif "
              '%}" href="{% url \'accounts\' %}">Quản lý tài khoản</a></div></section>{% endif %}\n'
              '      <section class="nav-group is-open"><button class="nav-group-toggle" type="button"><i '
              'data-lucide="badge-dollar-sign"></i><span>Tài chính</span><i '
              'data-lucide="chevron-down"></i></button><div class="nav-group-links"><a class="{% if '
              "request.resolver_match.url_name == 'contracts' or request.resolver_match.url_name == 'contract-create' "
              "or request.resolver_match.url_name == 'contract-detail' or request.resolver_match.url_name == "
              '\'contract-update\' %}active{% endif %}" href="{% url \'contracts\' %}">Hợp đồng</a><a class="{% if '
              "request.resolver_match.url_name == 'invoices' or request.resolver_match.url_name == 'invoice-create' or "
              "request.resolver_match.url_name == 'invoice-bulk-create' or request.resolver_match.url_name == "
              '\'invoice-detail\' or request.resolver_match.url_name == \'invoice-update\' %}active{% endif %}" '
              'href="{% url \'invoices\' %}">Hóa đơn</a><a class="{% if request.resolver_match.url_name == '
              '\'payments\' or request.resolver_match.url_name == \'payment-create\' %}active{% endif %}" href="{% url '
              '\'payments\' %}">Thanh toán</a></div></section>\n'
              '      <div class="nav-extra"><a class="{% if request.resolver_match.url_name == \'indoor-map-list\' or '
              'request.resolver_match.url_name == \'indoor-map\' %}active{% endif %}" href="{% url \'indoor-map-list\' '
              '%}"><i data-lucide="route"></i>Bản đồ trong nhà</a>{% if user.role == \'owner\' or user.role == '
              '\'admin\' or user.is_superuser %}<a class="{% if request.resolver_match.url_name == \'rooms\' or '
              "request.resolver_match.url_name == 'room-create' or request.resolver_match.url_name == 'room-update' "
              '%}active{% endif %}" href="{% url \'rooms\' %}"><i data-lucide="badge-dollar-sign"></i>Gợi ý giá '
              'thuê</a>{% endif %}<a class="{% if request.resolver_match.url_name == \'services\' or '
              "request.resolver_match.url_name == 'service-create' or request.resolver_match.url_name == "
              '\'service-update\' %}active{% endif %}" href="{% url \'services\' %}"><i data-lucide="wrench"></i>Dịch '
              'vụ</a><a class="{% if request.resolver_match.url_name == \'meters\' or request.resolver_match.url_name '
              '== \'meter-create\' or request.resolver_match.url_name == \'meter-update\' %}active{% endif %}" '
              'href="{% url \'meters\' %}"><i data-lucide="zap"></i>Điện nước</a><a class="{% if '
              'request.resolver_match.app_name == \'fire_detection\' %}active{% endif %}" href="{% url '
              '\'fire_detection:monitor\' %}"><i data-lucide="flame"></i>Giám sát cháy</a><a class="{% if '
              "request.resolver_match.url_name == 'incidents' or request.resolver_match.url_name == 'incident-detail' "
              '%}active{% endif %}" href="{% url \'incidents\' %}"><i data-lucide="triangle-alert"></i>Sự cố</a><a '
              'class="{% if request.resolver_match.url_name == \'notifications\' or request.resolver_match.url_name == '
              '\'notification-create\' %}active{% endif %}" href="{% url \'notifications\' %}"><i '
              'data-lucide="bell"></i>Thông báo</a>{% if user|has_perm_code:\'accounts.view_permission_matrix\' %}<a '
              'class="{% if request.resolver_match.url_name == \'permission-matrix\' %}active{% endif %}" href="{% url '
              '\'permission-matrix\' %}"><i data-lucide="shield-check"></i>Ma trận quyền</a>{% endif %}{% if '
              'user|has_perm_code:\'accounts.view_login_history\' %}<a href="{% url \'login-history\' %}"><i '
              'data-lucide="history"></i>Lịch sử đăng nhập</a>{% endif %}<a href="{% url \'user-profile\' %}"><i '
              'data-lucide="user"></i>Hồ sơ cá nhân</a><a href="{% url \'password-change\' %}"><i '
              'data-lucide="key-round"></i>Đổi mật khẩu</a></div>\n'
              '      {% endif %}\n'
              '    </nav>\n'
              '    {% if user.role != \'tenant\' %}<a class="admin-public-link" href="{% url \'public-home\' %}"><i '
              'data-lucide="arrow-up-right"></i>Xem trang cho thuê</a>{% endif %}\n'
              '    <small class="sidebar-version">Version 1.0.0</small>\n'
              '  </aside>\n'
              '  <main class="content" id="main-content" tabindex="-1">\n'
              '    <header class="topbar">\n'
              '      {% if user.role != \'tenant\' %}<button class="admin-icon-button admin-menu-toggle" '
              'id="admin-menu-toggle" type="button" aria-label="Mở menu quản trị" aria-controls="admin-sidebar" '
              'aria-expanded="false"><i data-lucide="menu"></i></button>{% endif %}\n'
              '      <div class="page-heading">\n'
              '        <h1>{% block page_title %}Quản lý phòng cho thuê{% endblock %}</h1>\n'
              '        <p>{% block page_subtitle %}{% endblock %}</p>\n'
              '      </div>\n'
              '      <div class="userbox">\n'
              '        <div class="topbar-alerts">\n'
              '          {% unread_notifications_count as bell_unread_count %}\n'
              '          <a class="notification-bell" href="{% if user.role == \'tenant\' %}{% url '
              '\'tenant-notifications\' %}{% else %}{% url \'notifications\' %}{% endif %}" title="Thông báo ({{ '
              'bell_unread_count }} chưa đọc)" aria-label="Thông báo, {{ bell_unread_count }} chưa đọc">\n'
              '            <i data-lucide="bell"></i>\n'
              '            {% if bell_unread_count > 0 %}<b>{{ bell_unread_count }}</b>{% endif %}\n'
              '          </a>\n'
              '          {% unread_chat_count as chat_unread_count %}\n'
              '          <a class="notification-bell {% if request.resolver_match.url_name == \'chat-list\' or '
              'request.resolver_match.url_name == \'chat-detail\' %}active{% endif %}" href="{% url \'chat-list\' %}" '
              'title="Trò chuyện ({{ chat_unread_count }} chưa đọc)" aria-label="Trò chuyện, {{ chat_unread_count }} '
              'tin nhắn chưa đọc">\n'
              '            <i data-lucide="messages-square"></i>\n'
              '            {% if chat_unread_count > 0 %}<b>{{ chat_unread_count }}</b>{% endif %}\n'
              '          </a>\n'
              '        </div>\n'
              '        <!-- USER PROFILE POPOVER (MATCHING USER SCREENSHOT) -->\n'
              '        <div class="user-popover-wrapper">\n'
              '          <button type="button" class="user-popover-trigger" id="userPopoverTrigger" '
              'aria-expanded="false" aria-haspopup="true" title="Tài khoản: {{ '
              'user.get_full_name|default:user.username }}">\n'
              '            <span class="user-avatar-circle">\n'
              '              {% if user.avatar %}<img src="{{ user.avatar.url }}" alt="Ảnh đại diện" '
              'class="user-avatar-img">{% else %}<span class="user-avatar-initial">{{ user.username|first|upper '
              '}}</span>{% endif %}\n'
              '            </span>\n'
              '            <span class="user-trigger-text">\n'
              '              <strong>{{ user.get_full_name|default:user.username }}</strong>\n'
              '              <small>{{ user.get_role_display }}</small>\n'
              '            </span>\n'
              '            <i data-lucide="chevron-down" class="user-trigger-chevron"></i>\n'
              '          </button>\n'
              '\n'
              '          <!-- FLOATING DROPDOWN CARD -->\n'
              '          <div class="user-popover-card" id="userPopoverCard" role="menu">\n'
              '            <div class="user-popover-arrow"></div>\n'
              '\n'
              '            <!-- Big Centered Avatar & Name -->\n'
              '            <div class="user-popover-profile">\n'
              '              <div class="user-popover-avatar-lg">\n'
              '                {% if user.avatar %}<img src="{{ user.avatar.url }}" alt="Ảnh đại diện" '
              'class="avatar-lg-img">{% else %}<span class="avatar-lg-initial">{{ user.username|first|upper '
              '}}</span>{% endif %}\n'
              '              </div>\n'
              '              <h3 class="user-popover-name">{{ user.get_full_name|default:user.username }}</h3>\n'
              '              <p class="user-popover-email">{{ user.email|default:user.username }}</p>\n'
              '            </div>\n'
              '\n'
              '            <!-- Organization / Role Card Pill -->\n'
              '            <div class="user-popover-org-pill">\n'
              '              <i data-lucide="building-2"></i>\n'
              '              <span>{{ user.get_role_display }} &bull; QL Phòng</span>\n'
              '              <i data-lucide="chevron-right" class="org-pill-arrow"></i>\n'
              '            </div>\n'
              '\n'
              '            <!-- Menu Actions List -->\n'
              '            <div class="user-popover-links">\n'
              '              <a href="{% url \'password-change\' %}" class="user-popover-link" role="menuitem">\n'
              '                <i data-lucide="key-round"></i>\n'
              '                <span>Đổi mật khẩu</span>\n'
              '              </a>\n'
              '              <a href="{% url \'user-profile\' %}" class="user-popover-link" role="menuitem">\n'
              '                <i data-lucide="user-cog"></i>\n'
              '                <span>Thiết lập tài khoản</span>\n'
              '              </a>\n'
              "              {% if user.role == 'tenant' or user|has_perm_code:'accounts.view_login_history' %}\n"
              '              <a href="{% url \'login-history\' %}" class="user-popover-link" role="menuitem">\n'
              '                <i data-lucide="shield-check"></i>\n'
              '                <span>Lịch sử đăng nhập</span>\n'
              '              </a>\n'
              '              {% endif %}\n'
              '              <div class="user-popover-link static-lang">\n'
              '                <i data-lucide="languages"></i>\n'
              '                <span>Ngôn ngữ: Việt Nam</span>\n'
              '                <i data-lucide="chevron-down" class="lang-chevron"></i>\n'
              '              </div>\n'
              '            </div>\n'
              '\n'
              '            <!-- Divider & Logout Button -->\n'
              '            <div class="user-popover-divider"></div>\n'
              '            <form method="post" action="{% url \'logout\' %}" class="user-popover-logout-form">\n'
              '              {% csrf_token %}\n'
              '              <button type="submit" class="user-popover-logout-btn" role="menuitem">\n'
              '                <i data-lucide="log-out"></i>\n'
              '                <span>Đăng xuất</span>\n'
              '              </button>\n'
              '            </form>\n'
              '          </div>\n'
              '        </div>\n'
              '      </div>\n'
              '    </header>\n'
              "    {% with route=request.resolver_match.url_name %}{% if route != 'dashboard' and route != "
              '\'tenant-portal\' %}<nav class="breadcrumbs" aria-label="Điều hướng trang"><a href="{% if user.role == '
              '\'tenant\' %}{% url \'tenant-portal\' %}{% else %}{% url \'dashboard\' %}{% endif %}"><i '
              'data-lucide="house"></i>Trang chủ</a><i data-lucide="chevron-right"></i>\n'
              "      {% if route == 'buildings' or route == 'building-create' or route == 'building-update' %}{% if "
              'route != \'buildings\' %}<a class="{% if request.resolver_match.url_name == \'buildings\' or '
              "request.resolver_match.url_name == 'building-create' or request.resolver_match.url_name == "
              '\'building-update\' %}active{% endif %}" href="{% url \'buildings\' %}">Tòa nhà</a><i '
              'data-lucide="chevron-right"></i><span>{% if route == \'building-create\' %}Thêm tòa nhà{% else %}Chỉnh '
              'sửa tòa nhà{% endif %}</span>{% else %}<span>Tòa nhà</span>{% endif %}\n'
              "      {% elif route == 'rooms' or route == 'room-create' or route == 'room-update' or route == "
              '\'tenant-rooms\' %}{% if route == \'room-create\' %}<a class="{% if request.resolver_match.url_name == '
              "'rooms' or request.resolver_match.url_name == 'room-create' or request.resolver_match.url_name == "
              '\'room-update\' %}active{% endif %}" href="{% url \'rooms\' %}">Phòng</a><i '
              'data-lucide="chevron-right"></i><span>Thêm phòng</span>{% elif route == \'room-update\' %}<a class="{% '
              "if request.resolver_match.url_name == 'rooms' or request.resolver_match.url_name == 'room-create' or "
              'request.resolver_match.url_name == \'room-update\' %}active{% endif %}" href="{% url \'rooms\' '
              '%}">Phòng</a><i data-lucide="chevron-right"></i><span>Chỉnh sửa phòng</span>{% else '
              '%}<span>Phòng</span>{% endif %}\n'
              "      {% elif route == 'room-map' %}<span>Sơ đồ phòng</span>\n"
              "      {% elif route == 'tenants' or route == 'tenant-create' or route == 'tenant-detail' or route == "
              '\'tenant-update\' %}{% if route == \'tenant-create\' %}<a class="{% if request.resolver_match.url_name '
              "== 'tenants' or request.resolver_match.url_name == 'tenant-create' or request.resolver_match.url_name "
              '== \'tenant-detail\' or request.resolver_match.url_name == \'tenant-update\' %}active{% endif %}" '
              'href="{% url \'tenants\' %}">Khách thuê</a><i data-lucide="chevron-right"></i><span>Thêm khách '
              'thuê</span>{% elif route == \'tenant-detail\' %}<a class="{% if request.resolver_match.url_name == '
              "'tenants' or request.resolver_match.url_name == 'tenant-create' or request.resolver_match.url_name == "
              '\'tenant-detail\' or request.resolver_match.url_name == \'tenant-update\' %}active{% endif %}" href="{% '
              'url \'tenants\' %}">Khách thuê</a><i data-lucide="chevron-right"></i><span>Chi tiết khách thuê</span>{% '
              'elif route == \'tenant-update\' %}<a class="{% if request.resolver_match.url_name == \'tenants\' or '
              "request.resolver_match.url_name == 'tenant-create' or request.resolver_match.url_name == "
              '\'tenant-detail\' or request.resolver_match.url_name == \'tenant-update\' %}active{% endif %}" href="{% '
              'url \'tenants\' %}">Khách thuê</a><i data-lucide="chevron-right"></i><span>Chỉnh sửa khách '
              'thuê</span>{% else %}<span>Khách thuê</span>{% endif %}\n'
              "      {% elif route == 'contracts' or route == 'contract-create' or route == 'contract-detail' or route "
              "== 'contract-update' or route == 'tenant-contracts' %}{% if route == 'contract-create' %}<a "
              'class="{% if request.resolver_match.url_name == \'contracts\' or request.resolver_match.url_name == '
              "'contract-create' or request.resolver_match.url_name == 'contract-detail' or "
              'request.resolver_match.url_name == \'contract-update\' %}active{% endif %}" href="{% url \'contracts\' '
              '%}">Hợp đồng</a><i data-lucide="chevron-right"></i><span>Thêm hợp đồng</span>{% elif route == '
              '\'contract-detail\' %}<a class="{% if request.resolver_match.url_name == \'contracts\' or '
              "request.resolver_match.url_name == 'contract-create' or request.resolver_match.url_name == "
              '\'contract-detail\' or request.resolver_match.url_name == \'contract-update\' %}active{% endif %}" '
              'href="{% url \'contracts\' %}">Hợp đồng</a><i data-lucide="chevron-right"></i><span>Chi tiết hợp '
              'đồng</span>{% elif route == \'contract-update\' %}<a class="{% if request.resolver_match.url_name == '
              "'contracts' or request.resolver_match.url_name == 'contract-create' or request.resolver_match.url_name "
              '== \'contract-detail\' or request.resolver_match.url_name == \'contract-update\' %}active{% endif %}" '
              'href="{% url \'contracts\' %}">Hợp đồng</a><i data-lucide="chevron-right"></i><span>Chỉnh sửa hợp '
              'đồng</span>{% else %}<span>Hợp đồng</span>{% endif %}\n'
              "      {% elif route == 'services' or route == 'service-create' or route == 'service-update' %}{% if "
              'route != \'services\' %}<a class="{% if request.resolver_match.url_name == \'services\' or '
              "request.resolver_match.url_name == 'service-create' or request.resolver_match.url_name == "
              '\'service-update\' %}active{% endif %}" href="{% url \'services\' %}">Dịch vụ</a><i '
              'data-lucide="chevron-right"></i><span>{% if route == \'service-create\' %}Thêm dịch vụ{% else %}Chỉnh '
              'sửa dịch vụ{% endif %}</span>{% else %}<span>Dịch vụ</span>{% endif %}\n'
              "      {% elif route == 'meters' or route == 'meter-create' or route == 'meter-update' %}{% if route != "
              '\'meters\' %}<a class="{% if request.resolver_match.url_name == \'meters\' or '
              "request.resolver_match.url_name == 'meter-create' or request.resolver_match.url_name == 'meter-update' "
              '%}active{% endif %}" href="{% url \'meters\' %}">Điện nước</a><i '
              'data-lucide="chevron-right"></i><span>{% if route == \'meter-create\' %}Thêm chỉ số{% else %}Cập nhật '
              'chỉ số{% endif %}</span>{% else %}<span>Điện nước</span>{% endif %}\n'
              "      {% elif route == 'invoices' or route == 'invoice-create' or route == 'invoice-bulk-create' or "
              "route == 'invoice-detail' or route == 'invoice-update' or route == 'tenant-invoices' or route == "
              "'tenant-invoice-detail' %}{% if route == 'invoice-create' or route == 'invoice-bulk-create' or route == "
              '\'invoice-detail\' or route == \'invoice-update\' %}<a class="{% if request.resolver_match.url_name == '
              "'invoices' or request.resolver_match.url_name == 'invoice-create' or request.resolver_match.url_name == "
              "'invoice-bulk-create' or request.resolver_match.url_name == 'invoice-detail' or "
              'request.resolver_match.url_name == \'invoice-update\' %}active{% endif %}" href="{% url \'invoices\' '
              '%}">Hóa đơn</a><i data-lucide="chevron-right"></i><span>{% if route == \'invoice-detail\' %}Chi tiết '
              "hóa đơn{% elif route == 'invoice-update' %}Chỉnh sửa hóa đơn{% else %}Tạo hóa đơn{% endif %}</span>{% "
              'else %}<span>Hóa đơn</span>{% endif %}\n'
              "      {% elif route == 'payments' or route == 'payment-create' or route == 'tenant-payments' %}{% if "
              'route == \'payment-create\' %}<a class="{% if request.resolver_match.url_name == \'payments\' or '
              'request.resolver_match.url_name == \'payment-create\' %}active{% endif %}" href="{% url \'payments\' '
              '%}">Thanh toán</a><i data-lucide="chevron-right"></i><span>Ghi nhận thanh toán</span>{% else '
              '%}<span>Thanh toán</span>{% endif %}\n'
              "      {% elif request.resolver_match.app_name == 'fire_detection' %}<span>Giám sát cháy AI</span>\n"
              "      {% elif route == 'incidents' or route == 'incident-detail' or route == 'tenant-incidents' or "
              'route == \'tenant-incident-create\' %}{% if route == \'incident-detail\' %}<a class="{% if '
              "request.resolver_match.url_name == 'incidents' or request.resolver_match.url_name == 'incident-detail' "
              '%}active{% endif %}" href="{% url \'incidents\' %}">Sự cố</a><i '
              'data-lucide="chevron-right"></i><span>Chi tiết sự cố</span>{% else %}<span>Sự cố</span>{% endif %}\n'
              "      {% elif route == 'notifications' or route == 'notification-create' or route == "
              '\'tenant-notifications\' %}{% if route == \'notification-create\' %}<a class="{% if '
              "request.resolver_match.url_name == 'notifications' or request.resolver_match.url_name == "
              '\'notification-create\' %}active{% endif %}" href="{% url \'notifications\' %}">Thông báo</a><i '
              'data-lucide="chevron-right"></i><span>Gửi thông báo</span>{% else %}<span>Thông báo</span>{% endif %}\n'
              "      {% elif route == 'accounts' or route == 'account-create' or route == 'account-detail' or route == "
              "'account-update' or route == 'account-reset-password' %}{% if route == 'accounts' %}<span>Quản lý tài "
              'khoản</span>{% else %}<a class="{% if request.resolver_match.url_name == \'accounts\' or '
              "request.resolver_match.url_name == 'account-create' or request.resolver_match.url_name == "
              "'account-detail' or request.resolver_match.url_name == 'account-update' or "
              'request.resolver_match.url_name == \'account-reset-password\' %}active{% endif %}" href="{% url '
              '\'accounts\' %}">Quản lý tài khoản</a><i data-lucide="chevron-right"></i><span>{% if route == '
              "'account-create' %}Thêm tài khoản{% elif route == 'account-detail' %}Chi tiết tài khoản{% elif route == "
              "'account-update' %}Chỉnh sửa tài khoản{% elif route == 'account-reset-password' %}Đặt lại mật khẩu{% "
              'endif %}</span>{% endif %}\n'
              "      {% elif route == 'login-history' %}<span>Lịch sử đăng nhập</span>\n"
              "      {% elif route == 'permission-matrix' %}<span>Ma trận quyền</span>\n"
              "      {% elif route == 'chat-list' or route == 'chat-detail' %}<span>Trò chuyện</span>\n"
              "      {% elif route == 'user-profile' %}<span>Hồ sơ cá nhân</span>\n"
              "      {% elif route == 'password-change' %}<span>Đổi mật khẩu</span>{% endif %}\n"
              '    </nav>{% endif %}{% endwith %}\n'
              '    {% if messages %}<div class="toast-stack" aria-live="polite">{% for message in messages %}<div '
              'class="toast {{ message.tags }}"><i data-lucide="circle-check"></i><span>{{ message }}</span><button '
              'type="button" aria-label="Đóng"><i data-lucide="x"></i></button></div>{% endfor %}</div>{% endif %}{% '
              'block content %}{% endblock %}\n'
              '  </main>\n'
              '  <script src="{% static \'lucide.min.js\' %}"></script>\n'
              '  <script>\n'
              '    lucide.createIcons({attrs:{"stroke-width":2}});\n'
              '    '
              'document.querySelectorAll(".toast").forEach(toast=>{toast.querySelector("button").addEventListener("click",()=>toast.remove());setTimeout(()=>{toast.classList.add("hiding");setTimeout(()=>toast.remove(),250)},4000)});\n'
              '    const popTrigger = document.getElementById("userPopoverTrigger");\n'
              '    const popCard = document.getElementById("userPopoverCard");\n'
              '    if (popTrigger && popCard) {\n'
              '      popTrigger.addEventListener("click", (e) => {\n'
              '        e.stopPropagation();\n'
              '        const isExpanded = popTrigger.getAttribute("aria-expanded") === "true";\n'
              '        popTrigger.setAttribute("aria-expanded", !isExpanded);\n'
              '        popCard.classList.toggle("show");\n'
              '      });\n'
              '      document.addEventListener("click", (e) => {\n'
              '        if (!popCard.contains(e.target) && !popTrigger.contains(e.target)) {\n'
              '          popCard.classList.remove("show");\n'
              '          popTrigger.setAttribute("aria-expanded", "false");\n'
              '        }\n'
              '      });\n'
              '      document.addEventListener("keydown", (e) => {\n'
              '        if (e.key === "Escape" && popCard.classList.contains("show")) {\n'
              '          popTrigger.focus();\n'
              '          popCard.classList.remove("show");\n'
              '          popTrigger.setAttribute("aria-expanded", "false");\n'
              '        }\n'
              '      });\n'
              '    }\n'
              '    document.querySelectorAll(".nav-group-toggle").forEach((toggle) => {\n'
              '      const group = toggle.closest(".nav-group");\n'
              '      toggle.setAttribute("aria-expanded", String(group.classList.contains("is-open")));\n'
              '      toggle.addEventListener("click", () => {\n'
              '        const isOpen = group.classList.toggle("is-open");\n'
              '        toggle.setAttribute("aria-expanded", String(isOpen));\n'
              '      });\n'
              '    });\n'
              '  </script>\n'
              '  <script src="{% static \'js/loading.js\' %}"></script>\n'
              '  {% if user.role != \'tenant\' %}<script src="{% static \'js/admin-shell.js\' '
              '%}?v=admin-1"></script>{% endif %}\n'
              '</body></html>\n',
 'chat/call_dialog.html': '<dialog id="chat-call-dialog" class="call-dialog" aria-labelledby="call-name">\n'
                          '  <div class="call-stage">\n'
                          '    <video id="call-remote" autoplay playsinline></video>\n'
                          '    <video id="call-local" autoplay playsinline muted></video>\n'
                          '    <div class="call-person"><span class="call-avatar" id="call-avatar">A</span><h2 '
                          'id="call-name"></h2><p id="call-status" role="status"></p></div>\n'
                          '    <span id="call-duration" class="call-duration" hidden>00:00</span>\n'
                          '    <button type="button" id="call-play-audio" class="btn" hidden>Bấm để nghe âm '
                          'thanh</button>\n'
                          '  </div>\n'
                          '  <div id="call-incoming-controls" class="call-controls" hidden>\n'
                          '    <button type="button" id="call-reject" class="call-control danger"><i '
                          'data-lucide="phone-off"></i><span>Từ chối</span></button>\n'
                          '    <button type="button" id="call-answer" class="call-control accept"><i '
                          'data-lucide="phone"></i><span>Trả lời</span></button>\n'
                          '  </div>\n'
                          '  <div id="call-active-controls" class="call-controls">\n'
                          '    <button type="button" id="call-mic" class="call-control" aria-pressed="false"><i '
                          'data-lucide="mic"></i><span>Tắt mic</span></button>\n'
                          '    <button type="button" id="call-camera" class="call-control" aria-pressed="false"><i '
                          'data-lucide="video"></i><span>Tắt camera</span></button>\n'
                          '    <button type="button" id="call-hangup" class="call-control danger"><i '
                          'data-lucide="phone-off"></i><span>Kết thúc</span></button>\n'
                          '  </div>\n'
                          '  <button type="button" id="call-close" class="call-close" aria-label="Đóng" hidden><i '
                          'data-lucide="x"></i></button>\n'
                          '</dialog>\n',
 'chat/detail.html': '{% extends "chat/layout.html" %}\n'
                     '{% load static %}\n'
                     '{% block chat_workspace %}\n'
                     '<header class="chat-head">\n'
                     '  <a href="{% url \'chat-list\' %}" class="chat-icon-button mobile-back" aria-label="Danh sách '
                     'trò chuyện"><i data-lucide="arrow-left"></i></a>\n'
                     '  <span class="conversation-avatar{% if peer_presence.online %} is-online{% endif %}">{% if '
                     'user.role == \'tenant\' %}<i data-lucide="building-2"></i>{% else %}{{ '
                     'conversation.tenant.full_name|first|upper }}{% endif %}</span>\n'
                     '  <div class="chat-recipient"><h2>{% if user.role == \'tenant\' %}Ban quản lý{% else %}{{ '
                     'conversation.tenant.full_name }}{% endif %}</h2><span id="peer-presence" class="peer-presence{% '
                     'if peer_presence.online %} online{% endif %}">{{ peer_presence.label }}</span></div>\n'
                     '  <span id="connection-state" class="connection-state network-status" aria-label="Kết nối của '
                     'bạn">{% if conversation.is_closed %}Đã đóng cuộc trò chuyện{% else %}Đang kết nối…{% endif '
                     '%}</span>\n'
                     '  {% if not conversation.is_closed and call_peer and call_peer.is_active %}\n'
                     '  <div class="chat-call-actions" data-peer-id="{{ call_peer.id }}" data-peer-name="{{ '
                     'call_peer.get_full_name|default:call_peer.username }}" data-conversation-id="{{ conversation.id '
                     '}}">\n'
                     '    <button type="button" class="chat-icon-button" data-start-call="audio" aria-label="Gọi '
                     'thoại" title="Gọi thoại"><i data-lucide="phone"></i></button>\n'
                     '    <button type="button" class="chat-icon-button" data-start-call="video" aria-label="Gọi '
                     'video" title="Gọi video"><i data-lucide="video"></i></button>\n'
                     '  </div>\n'
                     '  {% endif %}\n'
                     '</header>\n'
                     '<div id="chat-messages" class="chat-messages" data-closed="{{ '
                     'conversation.is_closed|yesno:\'true,false\' }}" data-chat-base="{% url \'chat-detail\' '
                     'conversation.id %}" data-updates-url="{% url \'chat-updates\' conversation.id %}" '
                     'data-user-id="{{ user.id }}" data-conversation-id="{{ conversation.id }}" role="log" '
                     'aria-label="Nội dung tin nhắn" aria-live="polite">\n'
                     '  {% for message in chat_messages %}<article class="chat-message{% if message.sender_id == '
                     'user.id %} mine{% endif %}" data-message-id="{{ message.id }}"><div class="chat-bubble">{% if '
                     'message.images.all %}<div class="chat-image-grid">{% for image in message.images.all %}<a '
                     'class="chat-image-link" href="{% url \'chat-image\' conversation.id message.id image.id %}" '
                     'title="Xem ảnh lớn"><img src="{% url \'chat-image\' conversation.id message.id image.id %}" '
                     'alt="{{ image.original_name|default:\'Hình ảnh\' }}" loading="lazy"></a>{% endfor %}</div>{% '
                     'endif %}{% if message.content %}<div class="chat-text">{{ message.content }}</div>{% endif '
                     '%}</div><div class="chat-info">{{ message.sender.get_full_name|default:message.sender.username '
                     '}} · {{ message.created_at|date:"H:i d/m/Y" }}{% if message.sender_id == user.id %} · {% if '
                     'message.read_by.count > 1 %}Đã xem{% else %}Đã gửi{% endif %}{% endif %}</div></article>{% empty '
                     '%}<div id="empty-chat" class="empty-thread"><span class="conversation-avatar"><i '
                     'data-lucide="message-circle"></i></span><h3>Bắt đầu bằng một lời chào</h3><p>Gửi tin nhắn đầu '
                     'tiên để bắt đầu cuộc trò chuyện.</p></div>{% endfor %}\n'
                     '</div>\n'
                     '{% if not conversation.is_closed %}\n'
                     '<div class="chat-compose-area"><div id="chat-attachment-preview" class="attachment-preview" '
                     'hidden aria-label="Ảnh chuẩn bị gửi"></div><form id="chat-form" enctype="multipart/form-data" '
                     'class="chat-compose" method="post" action="{% url \'chat-send\' conversation.id %}">{% '
                     'csrf_token %}<button type="button" id="chat-image-toggle" class="chat-icon-button" title="Gửi '
                     'ảnh" aria-label="Chọn ảnh để gửi"><i data-lucide="image-plus"></i></button><input type="file" '
                     'id="chat-image-input" name="images" accept="image/jpeg,image/png,image/webp" multiple '
                     'hidden><button type="button" id="emoji-toggle" class="chat-icon-button" aria-label="Chọn biểu '
                     'tượng cảm xúc" title="Chọn emoji" aria-expanded="false"><i data-lucide="smile"></i></button><div '
                     'class="compose-field"><textarea id="chat-input" name="message" maxlength="4000" rows="1" '
                     'aria-label="Tin nhắn" placeholder="Nhập tin nhắn…"></textarea><span>Enter để gửi · Shift + Enter '
                     'để xuống dòng</span></div><button class="send-message" type="submit" title="Gửi tin nhắn" '
                     'aria-label="Gửi tin nhắn"><i data-lucide="send"></i></button></form></div>\n'
                     '{% else %}<div class="closed-thread"><i data-lucide="lock-keyhole"></i> Cuộc trò chuyện đã đóng. '
                     'Bạn vẫn có thể xem lại tin nhắn.</div>{% endif %}\n'
                     '<p id="chat-error" role="alert" hidden style="margin:0;padding:8px '
                     '20px;color:#c83242;background:#fff1f2"></p>\n'
                     '<dialog id="chat-image-viewer" class="chat-image-viewer" aria-label="Xem ảnh">\n'
                     '  <div class="image-viewer-toolbar">\n'
                     '    <span id="image-viewer-name"></span>\n'
                     '    <div><button type="button" id="image-zoom-out" aria-label="Thu nhỏ"><i '
                     'data-lucide="zoom-out"></i></button><button type="button" id="image-zoom-reset" aria-label="Kích '
                     'thước ban đầu">100%</button><button type="button" id="image-zoom-in" aria-label="Phóng to"><i '
                     'data-lucide="zoom-in"></i></button><button type="button" id="image-viewer-close" '
                     'aria-label="Đóng"><i data-lucide="x"></i></button></div>\n'
                     '  </div>\n'
                     '  <div id="image-viewer-stage" class="image-viewer-stage"><img id="image-viewer-image" alt="Ảnh '
                     'trong cuộc trò chuyện"></div>\n'
                     '</dialog>\n'
                     '<script src="{% static \'js/chat.js\' %}?v=7"></script>\n'
                     '<script src="{% static \'js/chat-emoji.js\' %}?v=2"></script>\n'
                     '<script src="{% static \'js/chat-image-viewer.js\' %}?v=1"></script>\n'
                     '{% endblock %}\n',
 'chat/layout.html': '{% extends "base.html" %}\n'
                     '{% load static %}\n'
                     '{% block title %}Trò chuyện — Nhà Trọ An Tâm{% endblock %}\n'
                     '{% block page_title %}Trò chuyện{% endblock %}\n'
                     '{% block page_subtitle %}Kết nối khách thuê và ban quản lý{% endblock %}\n'
                     '{% block content %}\n'
                     '<link rel="stylesheet" href="{% static \'css/chat.css\' %}?v=7">\n'
                     '<div class="messenger{% if conversation %} has-conversation{% endif %}" data-inbox-url="{% url '
                     '\'chat-inbox-updates\' %}" data-chat-base="{% url \'chat-list\' %}" data-active-id="{{ '
                     'conversation.id|default:\'\' }}">\n'
                     '  <aside class="chat-sidebar">\n'
                     '    <header class="inbox-heading"><div><h2>Tin nhắn</h2><span>Cuộc trò chuyện của '
                     'bạn</span></div><button class="chat-icon-button" type="button" data-new-chat title="Soạn tin '
                     'nhắn mới" aria-label="Soạn tin nhắn mới"><i data-lucide="square-pen"></i></button></header>\n'
                     '    <label class="inbox-search"><i data-lucide="search"></i><input id="conversation-search" '
                     'type="search" placeholder="Tìm cuộc trò chuyện" aria-label="Tìm cuộc trò chuyện"></label>\n'
                     '    <div class="inbox-label">Tất cả tin nhắn <span>{{ conversations|length }}</span></div>\n'
                     '    <nav class="conversation-list" aria-label="Danh sách cuộc trò chuyện">\n'
                     '      {% for item in conversations %}\n'
                     '      <a class="conversation-card{% if item.id == conversation.id %} selected{% endif %}" '
                     'href="{% url \'chat-detail\' item.id %}" data-search="{{ item.tenant.full_name }} {{ '
                     'item.subject }}">\n'
                     '        <span class="conversation-avatar">{% if user.role == \'tenant\' %}<i '
                     'data-lucide="building-2"></i>{% else %}{{ item.tenant.full_name|first|upper }}{% endif '
                     '%}</span>\n'
                     '        <div class="conversation-main"><div class="conversation-title"><strong>{% if user.role '
                     "== 'tenant' %}Ban quản lý{% else %}{{ item.tenant.full_name }}{% endif %}</strong><time>{{ "
                     'item.last_message_at|date:"H:i" }}</time></div><p>{% if item.latest_message %}{{ '
                     'item.latest_message.content|default:"📷 Hình ảnh"|truncatechars:65 }}{% else %}Bắt đầu gửi lời '
                     'chào{% endif %}</p></div>\n'
                     '        {% if item.unread_count %}<span class="unread-dot">{{ item.unread_count }}</span>{% '
                     'endif %}\n'
                     '      </a>\n'
                     '      {% empty %}<div class="inbox-empty"><i data-lucide="messages-square"></i><strong>Chưa có '
                     'cuộc trò chuyện</strong><p>Bấm nút soạn tin để bắt đầu kết nối.</p></div>{% endfor %}\n'
                     '      <p id="search-empty" class="inbox-empty" hidden>Không tìm thấy cuộc trò chuyện.</p>\n'
                     '    </nav>\n'
                     '    <div class="inbox-footer"><i data-lucide="message-circle"></i> Trao đổi thuận tiện, kết nối '
                     'dễ dàng</div>\n'
                     '  </aside>\n'
                     '  <section class="chat-workspace">{% block chat_workspace %}{% endblock %}</section>\n'
                     '</div>\n'
                     '<dialog id="new-chat-dialog" class="new-chat-dialog">\n'
                     '  <header><div><h2>Cuộc trò chuyện mới</h2><p>Chọn người nhận và bắt đầu trao '
                     'đổi.</p></div><button type="button" class="chat-icon-button" id="close-new-chat" '
                     'aria-label="Đóng"><i data-lucide="x"></i></button></header>\n'
                     '  <form method="post" action="{% url \'chat-start\' %}">{% csrf_token %}\n'
                     '    {% if user.role != \'tenant\' %}<label for="new-chat-tenant">Khách thuê</label><select '
                     'id="new-chat-tenant" name="tenant_id" required><option value="">Chọn khách thuê</option>{% for '
                     'tenant in available_tenants %}<option value="{{ tenant.id }}">{{ tenant.full_name }}{% if '
                     'tenant.phone %} — {{ tenant.phone }}{% endif %}</option>{% endfor %}</select>{% else %}<div '
                     'class="new-chat-recipient"><i data-lucide="building-2"></i> Ban quản lý Nhà Trọ An Tâm</div>{% '
                     'endif %}\n'
                     '    <label for="new-chat-subject">Chủ đề <small>(không bắt buộc)</small></label><input '
                     'id="new-chat-subject" name="subject" maxlength="200" placeholder="Ví dụ: Trao đổi về hợp đồng">\n'
                     '    <button type="submit" class="btn primary"><i data-lucide="send"></i> Bắt đầu trò '
                     'chuyện</button>\n'
                     '  </form>\n'
                     '</dialog>\n'
                     '{% include "chat/call_dialog.html" %}\n'
                     '{{ webrtc_ice_servers|json_script:"chat-ice-servers" }}\n'
                     '<script src="{% static \'js/chat-inbox.js\' %}?v=4"></script>\n'
                     '<script src="{% static \'js/chat-call.js\' %}?v=1"></script>\n'
                     '<script>\n'
                     '(()=>{const '
                     "dialog=document.getElementById('new-chat-dialog');document.querySelectorAll('[data-new-chat]').forEach(button=>button.addEventListener('click',()=>dialog.showModal()));document.getElementById('close-new-chat').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const "
                     "r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.getElementById('conversation-search').addEventListener('input',e=>{const "
                     "query=e.target.value.toLocaleLowerCase('vi').trim();let "
                     "visible=0;document.querySelectorAll('.conversation-card').forEach(card=>{card.hidden=!card.dataset.search.toLocaleLowerCase('vi').includes(query);if(!card.hidden)visible++});document.getElementById('search-empty').hidden=!query||visible>0})})();\n"
                     '</script>\n'
                     '{% endblock %}\n',
 'chat/list.html': '{% extends "chat/layout.html" %}\n'
                   '{% block chat_workspace %}\n'
                   '<div class="chat-welcome"><div class="welcome-art"><i data-lucide="messages-square"></i><span><i '
                   'data-lucide="heart-handshake"></i></span></div><span class="welcome-eyebrow">KẾT NỐI MỖI '
                   'NGÀY</span><h2>Cuộc trò chuyện của bạn</h2><p>Chọn một cuộc trò chuyện bên trái hoặc bắt đầu tin '
                   "nhắn mới để trao đổi với {% if user.role == 'tenant' %}ban quản lý{% else %}khách thuê{% endif "
                   '%}.</p><button type="button" class="btn primary" data-new-chat><i data-lucide="square-pen"></i> '
                   'Tin nhắn mới</button><div class="welcome-note"><i data-lucide="message-circle"></i> Hỏi đáp về '
                   'phòng ở, hợp đồng và dịch vụ</div></div>\n'
                   '{% endblock %}\n',
 'includes/loading.html': '{% load static %}\n'
                          '<div id="site-loading" class="site-loading" role="status" aria-live="polite" '
                          'aria-label="Đang tải trang">\n'
                          '  <div class="site-loading__content">\n'
                          '    <img src="{% static \'images/loading-dog.png\' %}" alt="" class="site-loading__dog" '
                          'width="240" height="160">\n'
                          '    <span class="site-loading__label">Đang tải<span class="site-loading__dots" '
                          'aria-hidden="true">...</span></span>\n'
                          '  </div>\n'
                          '</div>\n',
 'includes/public_footer.html': '<footer id="lien-he" class="public-footer">\n'
                                '  <div class="footer-inner">\n'
                                '    <div class="footer-columns">\n'
                                '      <div class="footer-brand">\n'
                                '        <a class="footer-wordmark" href="{% url \'public-home\' %}"><i '
                                'data-lucide="house" aria-hidden="true"></i><strong>QL Phòng Cho Thuê</strong></a>\n'
                                '        <p>Tìm phòng theo tòa nhà, mức giá và tiện ích. Lưu những lựa chọn phù hợp và '
                                'theo dõi thông tin trong suốt quá trình thuê.</p>\n'
                                '        <a class="footer-explore" href="{% url \'public-rooms\' %}">Tìm phòng phù hợp '
                                '<i data-lucide="arrow-right" aria-hidden="true"></i></a>\n'
                                '      </div>\n'
                                '\n'
                                '      <nav class="footer-links" aria-labelledby="footer-discover-title">\n'
                                '        <h2 id="footer-discover-title">Khám phá</h2>\n'
                                '        <ul>\n'
                                '          <li><a href="{% url \'public-home\' %}">Trang chủ</a></li>\n'
                                '          <li><a href="{% url \'public-rooms\' %}">Phòng đang cho thuê</a></li>\n'
                                '          <li><a href="{% url \'public-rooms\' %}?favorites=1">Phòng yêu '
                                'thích</a></li>\n'
                                '          <li><a href="{% url \'public-about\' %}">Về chúng tôi</a></li>\n'
                                '        </ul>\n'
                                '      </nav>\n'
                                '\n'
                                '      <nav class="footer-links" aria-labelledby="footer-support-title">\n'
                                '        <h2 id="footer-support-title">Hỗ trợ bạn</h2>\n'
                                '        <ul>\n'
                                '          <li><a href="{% url \'public-about\' %}#about-start">Hướng dẫn tìm '
                                'phòng</a></li>\n'
                                '          <li><a href="{% url \'public-contact\' %}#contact-faq">Câu hỏi thường '
                                'gặp</a></li>\n'
                                '          <li><a href="{% url \'public-contact\' %}">Liên hệ hỗ trợ</a></li>\n'
                                '          <li><a href="{% if user.is_authenticated %}{% if user.role == \'tenant\' '
                                "%}{% url 'tenant-portal' %}{% else %}{% url 'dashboard' %}{% endif %}{% else %}{% url "
                                '\'login\' %}{% endif %}">Tài khoản của bạn</a></li>\n'
                                '        </ul>\n'
                                '      </nav>\n'
                                '\n'
                                '      <section class="footer-contact" aria-labelledby="footer-contact-title">\n'
                                '        <h2 id="footer-contact-title">Kết nối với chúng tôi</h2>\n'
                                '        <address>\n'
                                '          <div class="footer-contact-row"><i data-lucide="phone" '
                                'aria-hidden="true"></i><div><small>Điện thoại hỗ trợ</small><a class="footer-phone" '
                                'href="tel:0902966704">0902 966 704</a></div></div>\n'
                                '          <div class="footer-contact-row"><i data-lucide="mail" '
                                'aria-hidden="true"></i><div><small>Email</small><a class="footer-email" '
                                'href="mailto:1150080030@sv.hcmunre.edu.vn">1150080030@sv.hcmunre.edu.vn</a></div></div>\n'
                                '        </address>\n'
                                '        <p>Khi hỏi về phòng, hãy gửi kèm mã phòng và tên tòa nhà để dễ trao đổi.</p>\n'
                                '      </section>\n'
                                '    </div>\n'
                                '\n'
                                '    <div class="footer-bottom">\n'
                                '      <p>© {% now "Y" %} QL Phòng Cho Thuê. Bảo lưu mọi quyền.</p>\n'
                                '      <a class="footer-top" href="#dau-trang">Lên đầu trang <i data-lucide="arrow-up" '
                                'aria-hidden="true"></i></a>\n'
                                '    </div>\n'
                                '  </div>\n'
                                '</footer>\n',
 'public/about.html': '{% extends "public/discovery_base.html" %}\n'
                      '{% load static %}\n'
                      '{% block title %}Về chúng tôi{% endblock %}\n'
                      '{% block extra_css %}{{ block.super }}<link rel="stylesheet" href="{% static '
                      '\'css/public-information.css\' %}?v=info-2">{% endblock %}\n'
                      '{% block content %}\n'
                      '<div class="information-page">\n'
                      '  <nav class="info-breadcrumb" aria-label="Đường dẫn"><a href="{% url \'public-home\' %}">Trang '
                      'chủ</a><i data-lucide="chevron-right" aria-hidden="true"></i><span aria-current="page">Về chúng '
                      'tôi</span></nav>\n'
                      '  <section class="info-hero" aria-labelledby="about-title">\n'
                      '    <div>\n'
                      '      <p class="info-kicker">Về QL Phòng Cho Thuê</p>\n'
                      '      <h1 id="about-title">Tìm phòng dễ hơn.<br>Quản lý rõ ràng hơn.</h1>\n'
                      '      <p class="info-lead">Một nơi để tìm hiểu phòng trọ trước khi lựa chọn, và theo dõi các '
                      'thông tin cần thiết trong suốt quá trình thuê.</p>\n'
                      '      <p>QL Phòng Cho Thuê kết nối việc tìm phòng với quản lý tòa nhà, khách thuê, hợp đồng và '
                      'hóa đơn. Chúng tôi tập trung đưa thông tin phòng về cùng một chỗ, để người thuê dễ cân nhắc và '
                      'người quản lý thuận tiện cập nhật.</p>\n'
                      '      <div class="info-actions"><a class="btn primary" href="{% url \'public-rooms\' %}">Khám '
                      'phá các phòng <i data-lucide="arrow-right" aria-hidden="true"></i></a><a class="info-text-link" '
                      'href="{% url \'public-contact\' %}">Liên hệ hỗ trợ</a></div>\n'
                      '    </div>\n'
                      '    <aside class="info-overview" aria-label="Hệ thống dành cho ai">\n'
                      '      <div class="info-overview-heading"><i data-lucide="house" '
                      'aria-hidden="true"></i><span>Cùng một nơi, nhiều nhu cầu</span></div>\n'
                      '      <div><span class="info-step-number">01</span><div><h2>Đang tìm chỗ ở</h2><p>Xem phòng, '
                      'đối chiếu mức giá và lưu những lựa chọn phù hợp.</p></div></div>\n'
                      '      <div><span class="info-step-number">02</span><div><h2>Đã trở thành khách thuê</h2><p>Tra '
                      'cứu thông tin thuê và theo dõi hóa đơn qua tài khoản được liên kết.</p></div></div>\n'
                      '      <div><span class="info-step-number">03</span><div><h2>Đang quản lý phòng trọ</h2><p>Theo '
                      'dõi tình trạng phòng và các công việc cho thuê trên cùng hệ thống.</p></div></div>\n'
                      '    </aside>\n'
                      '  </section>\n'
                      '\n'
                      '  <section class="info-section info-feature-section" aria-labelledby="about-features">\n'
                      '    <div><p class="info-kicker">Trước khi chọn phòng</p><h2 id="about-features">Có thông '
                      'tin,<br>dễ cân nhắc hơn</h2><p>Mỗi người có một ưu tiên về chỗ ở. Bắt đầu từ khu vực, ngân sách '
                      'và những tiện ích bạn cần.</p></div>\n'
                      '    <div class="info-feature-list">\n'
                      '      <article><i data-lucide="sliders-horizontal" aria-hidden="true"></i><div><h3>Tìm theo nhu '
                      'cầu của bạn</h3><p>Lọc phòng theo khu vực, tòa nhà, khoảng giá và tiện ích; sắp xếp giá để đối '
                      'chiếu các lựa chọn.</p></div></article>\n'
                      '      <article><i data-lucide="images" aria-hidden="true"></i><div><h3>Xem kỹ từng căn '
                      'phòng</h3><p>Đọc địa chỉ, giá thuê, diện tích, số người ở và tiện ích. Ảnh, video được hiển thị '
                      'khi phòng đã có tư liệu cập nhật.</p></div></article>\n'
                      '      <article><i data-lucide="heart" aria-hidden="true"></i><div><h3>Lưu lại để xem '
                      'sau</h3><p>Đánh dấu phòng yêu thích để quay lại tham khảo. Danh sách được lưu trên trình duyệt '
                      'và thiết bị bạn đang sử dụng.</p></div></article>\n'
                      '    </div>\n'
                      '  </section>\n'
                      '\n'
                      '  <section class="info-section" aria-labelledby="about-rental">\n'
                      '    <div class="info-section-heading"><p class="info-kicker">Trong quá trình thuê</p><h2 '
                      'id="about-rental">Những thông tin cần thiết, ở cùng một nơi</h2></div>\n'
                      '    <div class="info-audience-grid">\n'
                      '      <article class="info-panel"><i data-lucide="key-round" aria-hidden="true"></i><h3>Dành '
                      'cho người thuê</h3><p>Khi được cấp và liên kết tài khoản, bạn có thể xem phòng đang thuê, hợp '
                      'đồng, hóa đơn, lịch sử thanh toán và các thông báo liên quan.</p><p>Nếu có vấn đề trong quá '
                      'trình sử dụng phòng, bạn có thể gửi phản ánh qua chức năng báo sự cố trong tài khoản người '
                      'thuê.</p></article>\n'
                      '      <article class="info-panel"><i data-lucide="building-2" aria-hidden="true"></i><h3>Dành '
                      'cho người quản lý</h3><p>Tập trung thông tin tòa nhà, phòng, khách thuê và hợp đồng; theo dõi '
                      'chỉ số điện nước, hóa đơn và thanh toán theo quyền được phân công.</p><p>Hệ thống hỗ trợ cập '
                      'nhật thông tin phòng và tiếp nhận sự cố để việc quản lý có căn cứ theo dõi.</p></article>\n'
                      '    </div>\n'
                      '  </section>\n'
                      '\n'
                      '  <section class="info-section" aria-labelledby="about-start">\n'
                      '    <div class="info-section-heading"><p class="info-kicker">Bắt đầu từ nhu cầu của bạn</p><h2 '
                      'id="about-start">Từ tìm kiếm đến xem phòng</h2></div>\n'
                      '    <ol class="info-steps">\n'
                      '      <li><span class="info-step-number">01</span><h3>Chọn khu vực và mức giá</h3><p>Dùng bộ '
                      'lọc để thu hẹp danh sách phòng theo nhu cầu sinh hoạt và ngân sách của bạn.</p></li>\n'
                      '      <li><span class="info-step-number">02</span><h3>Xem và lưu phòng phù hợp</h3><p>Đọc thông '
                      'tin, xem tư liệu của từng phòng và lưu những phòng bạn muốn tìm hiểu thêm.</p></li>\n'
                      '      <li><span class="info-step-number">03</span><h3>Liên hệ để trao đổi</h3><p>Gửi mã phòng, '
                      'tên tòa nhà và thời gian bạn muốn xem để trao đổi về tình trạng phòng và các chi phí cụ '
                      'thể.</p></li>\n'
                      '    </ol>\n'
                      '  </section>\n'
                      '\n'
                      '  <section class="info-callout"><div><h2>Phòng phù hợp bắt đầu từ nhu cầu của bạn</h2><p>Xem '
                      'danh sách phòng đang cho thuê hoặc liên hệ để trao đổi thêm.</p></div><a class="btn primary" '
                      'href="{% url \'public-rooms\' %}">Tìm phòng <i data-lucide="arrow-right" '
                      'aria-hidden="true"></i></a></section>\n'
                      '</div>\n'
                      '{% endblock %}\n',
 'public/base.html': '{% load static %}\n'
                     '<!doctype html>\n'
                     '<html lang="vi">\n'
                     '<head>\n'
                     '  <meta charset="utf-8">\n'
                     '  <meta name="viewport" content="width=device-width, initial-scale=1">\n'
                     '  <title>{% block title %}Phòng cho thuê{% endblock %} — QL Phòng Cho Thuê</title>\n'
                     '  <link rel="icon" type="image/png" href="{% static \'images/favicon.png\' %}">\n'
                     '  <link rel="stylesheet" href="{% static \'css/loading.css\' %}">\n'
                     '  <link rel="stylesheet" href="{% static \'css/app.css\' %}">\n'
                     '  <link rel="stylesheet" href="{% static \'css/public-home.css\' %}?v=home-2">\n'
                     '  <link rel="stylesheet" href="{% static \'css/lucide.css\' %}">\n'
                     '  <link rel="stylesheet" href="{% static \'css/room-detail.css\' %}">\n'
                     '  <link rel="stylesheet" href="{% static \'css/pagination.css\' %}">\n'
                     '  {% block extra_css %}{% endblock %}\n'
                     '  <link rel="stylesheet" href="{% static \'css/public-footer.css\' %}?v=footer-1">\n'
                     '  <noscript><style>.site-loading{display:none!important}</style></noscript>\n'
                     '</head>\n'
                     '<body id="dau-trang" class="public-page{% block body_class %}{% endblock %}">\n'
                     "  {% include 'includes/loading.html' %}\n"
                     '  <header class="public-header">\n'
                     '    {% block header_identity %}{% endblock %}\n'
                     '    {% block header_menu %}{% endblock %}\n'
                     '    <nav id="public-nav" aria-label="Điều hướng chính">\n'
                     '      <a class="{% if request.resolver_match.url_name == \'public-home\' %}active{% endif %}" {% '
                     'if request.resolver_match.url_name == \'public-home\' %}aria-current="page"{% endif %} href="{% '
                     'url \'public-home\' %}"><i data-lucide="house"></i> Trang chủ</a>\n'
                     '      <a class="{% if request.resolver_match.url_name == \'public-rooms\' %}active{% endif %}" '
                     '{% if request.resolver_match.url_name == \'public-rooms\' %}aria-current="page"{% endif %} '
                     'href="{% url \'public-rooms\' %}"><i data-lucide="search"></i> Tìm phòng</a>\n'
                     '      <a class="{% if request.resolver_match.url_name == \'public-about\' %}active{% endif %}" '
                     '{% if request.resolver_match.url_name == \'public-about\' %}aria-current="page"{% endif %} '
                     'href="{% url \'public-about\' %}"><i data-lucide="building-2"></i> Về chúng tôi</a>\n'
                     '      <a class="{% if request.resolver_match.url_name == \'public-contact\' %}active{% endif %}" '
                     '{% if request.resolver_match.url_name == \'public-contact\' %}aria-current="page"{% endif %} '
                     'href="{% url \'public-contact\' %}"><i data-lucide="phone"></i> Liên hệ</a>\n'
                     '    </nav>\n'
                     '    <div class="header-actions">\n'
                     '      <a class="favorite-link" href="{% url \'public-rooms\' %}?favorites=1" title="Xem phòng đã '
                     'lưu" aria-label="Xem phòng yêu thích">\n'
                     '        <i data-lucide="heart"></i> <span class="favorite-label">Yêu thích</span> <span '
                     'id="favorite-count">0</span>\n'
                     '      </a>\n'
                     '      {% if user.is_authenticated %}\n'
                     '        <a class="btn primary login-cta" href="{% if user.role == \'tenant\' %}{% url '
                     '\'tenant-portal\' %}{% else %}{% url \'dashboard\' %}{% endif %}">\n'
                     '          <i data-lucide="circle-user-round"></i> Vào hệ thống\n'
                     '        </a>\n'
                     '      {% else %}\n'
                     '        <a class="btn primary login-cta" href="{% url \'login\' %}">\n'
                     '          <i data-lucide="circle-user-round"></i> Đăng nhập\n'
                     '        </a>\n'
                     '      {% endif %}\n'
                     '    </div>\n'
                     '  </header>\n'
                     '  <main>{% block content %}{% endblock %}</main>\n'
                     "  {% include 'includes/public_footer.html' %}\n"
                     '  <script src="{% static \'lucide.min.js\' %}"></script>\n'
                     '  <script>lucide.createIcons({attrs:{"stroke-width":2}});</script>\n'
                     '  <script src="{% static \'js/favorites.js\' %}"></script>\n'
                     '  <script src="{% static \'js/loading.js\' %}"></script>\n'
                     '  {% block extra_js %}{% endblock %}\n'
                     '</body>\n'
                     '</html>\n',
 'public/contact.html': '{% extends "public/discovery_base.html" %}\n'
                        '{% load static %}\n'
                        '{% block title %}Liên hệ{% endblock %}\n'
                        '{% block extra_css %}{{ block.super }}<link rel="stylesheet" href="{% static '
                        '\'css/public-information.css\' %}?v=info-2"><link rel="stylesheet" href="{% static '
                        '\'css/contact-locations.css\' %}?v=locations-1">{% endblock %}\n'
                        '{% block content %}\n'
                        '<div class="information-page">\n'
                        '  <nav class="info-breadcrumb" aria-label="Đường dẫn"><a href="{% url \'public-home\' '
                        '%}">Trang chủ</a><i data-lucide="chevron-right" aria-hidden="true"></i><span '
                        'aria-current="page">Liên hệ</span></nav>\n'
                        '  <section class="info-hero info-contact-hero" aria-labelledby="contact-title">\n'
                        '    <div><p class="info-kicker">Liên hệ với chúng tôi</p><h1 id="contact-title">Bạn cần tìm '
                        'phòng<br>hay hỗ trợ sử dụng?</h1><p class="info-lead">Trao đổi về phòng bạn quan tâm, nhu cầu '
                        'thuê hoặc vấn đề gặp phải khi sử dụng QL Phòng Cho Thuê qua các kênh bên dưới.</p></div>\n'
                        '    <aside class="info-contact-note"><i data-lucide="message-square" '
                        'aria-hidden="true"></i><h2>Để dễ hỗ trợ bạn</h2><p>Khi hỏi về một phòng cụ thể, hãy gửi kèm '
                        '<strong>mã phòng và tên tòa nhà</strong>. Nếu muốn xem phòng, bạn có thể đề xuất ngày và thời '
                        'gian thuận tiện.</p></aside>\n'
                        '  </section>\n'
                        '\n'
                        '  <section class="info-contact-methods" aria-label="Các cách liên hệ">\n'
                        '    <article class="info-contact-card"><div class="info-method-heading"><i '
                        'data-lucide="phone" aria-hidden="true"></i><h2>Gọi điện trực tiếp</h2></div><a '
                        'class="info-contact-address" href="tel:0902966704">0902 966 704</a><p>Trao đổi về phòng đang '
                        'cho thuê, thông tin tòa nhà và việc hẹn xem phòng.</p><a class="btn primary" '
                        'href="tel:0902966704"><i data-lucide="phone" aria-hidden="true"></i> Gọi 0902 966 '
                        '704</a></article>\n'
                        '    <article class="info-contact-card"><div class="info-method-heading"><i data-lucide="mail" '
                        'aria-hidden="true"></i><h2>Gửi email</h2></div><a class="info-contact-address '
                        'info-email-address" '
                        'href="mailto:1150080030@sv.hcmunre.edu.vn">1150080030@sv.hcmunre.edu.vn</a><p>Gửi nội dung '
                        'cần hỗ trợ, câu hỏi chi tiết hoặc hình ảnh mô tả vấn đề bạn đang gặp.</p><a '
                        'class="info-secondary-button" href="mailto:1150080030@sv.hcmunre.edu.vn"><i '
                        'data-lucide="mail" aria-hidden="true"></i> Mở ứng dụng email</a></article>\n'
                        '  </section>\n'
                        '\n'
                        '  <section id="contact-locations" class="info-section contact-locations" '
                        'aria-labelledby="contact-locations-title">\n'
                        '    <div class="info-section-heading"><p class="info-kicker">Địa chỉ các tòa nhà</p><h2 '
                        'id="contact-locations-title">Tìm đường đến nơi bạn muốn ở</h2><p>Chọn tòa nhà để xem vị trí '
                        'trên bản đồ. Bạn có thể mở chỉ đường và liên hệ trước để hẹn xem phòng.</p></div>\n'
                        '    {% if selected_building %}\n'
                        '    <div class="contact-locations-layout" data-contact-locations>\n'
                        '      <nav class="contact-location-list" aria-label="Chọn tòa nhà trên bản đồ">\n'
                        '        {% for building in contact_buildings %}\n'
                        '        <a class="contact-location-choice" href="{% url \'public-contact\' %}?building={{ '
                        'building.id }}#contact-locations" {% if building.id == selected_building.id '
                        '%}aria-current="location"{% endif %} data-building-id="{{ building.id }}" '
                        'data-building-name="{{ building.name }}" data-building-address="{{ building.address }}" '
                        'data-map-embed-url="{{ building.map_embed_url }}" data-map-url="{{ building.map_url }}" '
                        'data-directions-url="{{ building.directions_url }}" data-rooms-url="{{ building.rooms_url '
                        '}}">\n'
                        '          <span class="contact-location-number" aria-hidden="true">{{ '
                        'forloop.counter|stringformat:"02d" }}</span>\n'
                        '          <span class="contact-location-copy"><strong>{{ building.name }}</strong><span>{{ '
                        'building.address }}</span></span>\n'
                        '          <i data-lucide="chevron-right" aria-hidden="true"></i>\n'
                        '        </a>\n'
                        '        {% endfor %}\n'
                        '      </nav>\n'
                        '      <div id="contact-map-panel" class="contact-map-panel" tabindex="-1" role="region" '
                        'aria-label="Bản đồ tòa nhà">\n'
                        '        <div class="contact-map-heading" aria-live="polite" aria-atomic="true"><h3 '
                        'id="contact-map-name">{{ selected_building.name }}</h3><p id="contact-map-address">{{ '
                        'selected_building.address }}</p></div>\n'
                        '        <iframe id="contact-map" src="{{ selected_building.map_embed_url }}" title="Bản đồ '
                        'tham khảo {{ selected_building.name }} — {{ selected_building.address }}" loading="lazy" '
                        'referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>\n'
                        '        <p class="contact-map-note"><i data-lucide="info" aria-hidden="true"></i>Bản đồ khu '
                        'vực mang tính tham khảo. Vui lòng liên hệ để xác nhận vị trí và lối vào trước khi đến.</p>\n'
                        '        <div class="contact-map-actions">\n'
                        '          <a id="contact-directions" class="btn primary" href="{{ '
                        'selected_building.directions_url }}" target="_blank" rel="noopener noreferrer"><i '
                        'data-lucide="navigation" aria-hidden="true"></i> Chỉ đường</a>\n'
                        '          <a id="contact-building-rooms" class="info-text-link" href="{{ '
                        'selected_building.rooms_url }}">Xem phòng <i data-lucide="arrow-right" '
                        'aria-hidden="true"></i></a>\n'
                        '          <a id="contact-open-map" class="contact-open-map" href="{{ '
                        'selected_building.map_url }}" target="_blank" rel="noopener noreferrer">Mở Google Maps <i '
                        'data-lucide="external-link" aria-hidden="true"></i></a>\n'
                        '        </div>\n'
                        '      </div>\n'
                        '    </div>\n'
                        '    {% else %}\n'
                        '    <p class="contact-locations-empty">Địa chỉ tòa nhà đang được cập nhật. Bạn có thể gọi '
                        'điện hoặc gửi email để trao đổi về vị trí phòng cần tìm.</p>\n'
                        '    {% endif %}\n'
                        '  </section>\n'
                        '\n'
                        '  <section class="info-section" aria-labelledby="contact-prepare">\n'
                        '    <div class="info-section-heading"><p class="info-kicker">Chuẩn bị trước khi liên '
                        'hệ</p><h2 id="contact-prepare">Bạn muốn trao đổi về việc gì?</h2></div>\n'
                        '    <div class="info-help-grid">\n'
                        '      <article><i data-lucide="search" aria-hidden="true"></i><h3>Tìm hoặc xem '
                        'phòng</h3><p>Cho biết khu vực, khoảng giá, số người ở và thời điểm dự kiến chuyển vào. Nếu đã '
                        'chọn được phòng, gửi thêm mã phòng và tên tòa nhà.</p><a class="info-text-link" href="{% url '
                        '\'public-rooms\' %}">Xem các phòng đang cho thuê <i data-lucide="arrow-right" '
                        'aria-hidden="true"></i></a></article>\n'
                        '      <article><i data-lucide="key-round" aria-hidden="true"></i><h3>Đang thuê '
                        'phòng</h3><p>Nêu phòng đang thuê và nội dung cần hỗ trợ. Với sự cố trong phòng, mô tả hiện '
                        'tượng và thời điểm xảy ra để người quản lý có thông tin xử lý.</p><a class="info-text-link" '
                        'href="{% if user.is_authenticated %}{% if user.role == \'tenant\' %}{% url \'tenant-portal\' '
                        '%}{% else %}{% url \'dashboard\' %}{% endif %}{% else %}{% url \'login\' %}{% endif %}">Vào '
                        'tài khoản của bạn <i data-lucide="arrow-right" aria-hidden="true"></i></a></article>\n'
                        '      <article><i data-lucide="monitor" aria-hidden="true"></i><h3>Hỗ trợ website</h3><p>Gửi '
                        'tên trang hoặc chức năng gặp lỗi, các bước đã thực hiện và ảnh chụp màn hình nếu có. Cho biết '
                        'bạn đang dùng điện thoại hay máy tính.</p><a class="info-text-link" '
                        'href="mailto:1150080030@sv.hcmunre.edu.vn">Gửi nội dung cần hỗ trợ <i '
                        'data-lucide="arrow-right" aria-hidden="true"></i></a></article>\n'
                        '    </div>\n'
                        '  </section>\n'
                        '\n'
                        '  <section class="info-section info-faq-section" aria-labelledby="contact-faq">\n'
                        '    <div><p class="info-kicker">Thông tin thường cần</p><h2 id="contact-faq">Câu hỏi thường '
                        'gặp</h2><p>Bạn có thể gọi điện hoặc gửi email nếu cần trao đổi thêm về trường hợp của '
                        'mình.</p></div>\n'
                        '    <div class="info-faq">\n'
                        '      <details><summary>Tôi muốn hẹn xem phòng thì làm thế nào?<i data-lucide="plus" '
                        'aria-hidden="true"></i></summary><p>Gọi điện hoặc gửi email kèm mã phòng, tên tòa nhà và thời '
                        'gian bạn muốn đến xem. Thời gian hẹn cần được trao đổi và xác nhận trực tiếp qua kênh liên '
                        'hệ.</p></details>\n'
                        '      <details><summary>Giá hiển thị đã bao gồm điện, nước và dịch vụ chưa?<i '
                        'data-lucide="plus" aria-hidden="true"></i></summary><p>Giá trên thẻ phòng là giá thuê theo '
                        'tháng. Điện, nước và các dịch vụ có thể được tính riêng theo từng phòng hoặc hợp đồng. Khi '
                        'liên hệ, hãy hỏi cụ thể các khoản phí và tiền đặt cọc để cân nhắc đầy đủ.</p></details>\n'
                        '      <details><summary>Chưa tìm được phòng phù hợp thì có thể liên hệ không?<i '
                        'data-lucide="plus" aria-hidden="true"></i></summary><p>Bạn có thể gửi khu vực mong muốn, mức '
                        'giá dự kiến, số người ở và các tiện ích cần có để trao đổi về những phòng đang được đăng trên '
                        'hệ thống.</p></details>\n'
                        '      <details><summary>Tôi xem hợp đồng và hóa đơn của mình ở đâu?<i data-lucide="plus" '
                        'aria-hidden="true"></i></summary><p>Đăng nhập bằng tài khoản người thuê đã được cấp và liên '
                        'kết với thông tin thuê của bạn. Tại khu vực người thuê, chọn mục hợp đồng hoặc hóa đơn. Nếu '
                        'chưa có tài khoản hoặc chưa thấy thông tin, hãy liên hệ người quản lý.</p></details>\n'
                        '    </div>\n'
                        '  </section>\n'
                        '  <section class="info-callout"><div><h2>Bạn vẫn đang cân nhắc chỗ ở?</h2><p>Quay lại danh '
                        'sách để xem thông tin và lưu các phòng bạn quan tâm.</p></div><a class="btn primary" href="{% '
                        'url \'public-rooms\' %}">Tiếp tục tìm phòng <i data-lucide="arrow-right" '
                        'aria-hidden="true"></i></a></section>\n'
                        '</div>\n'
                        '{% endblock %}\n'
                        '{% block extra_js %}{{ block.super }}<script src="{% static \'js/contact-locations.js\' '
                        '%}?v=locations-1" defer></script>{% endblock %}\n',
 'public/discovery_base.html': '{% extends "public/base.html" %}\n'
                               '{% load static %}\n'
                               '{% block extra_css %}<link rel="stylesheet" href="{% static \'css/home-discovery.css\' '
                               '%}?v=home-4">{% endblock %}\n'
                               '{% block body_class %} home-discovery{% endblock %}\n'
                               '{% block header_identity %}<a class="home-wordmark" href="{% url \'public-home\' %}" '
                               'aria-label="QL Phòng Cho Thuê — Trang chủ"><i data-lucide="house"></i><span>QL Phòng '
                               'Cho Thuê</span></a>{% endblock %}\n'
                               '{% block header_menu %}<button id="public-menu-toggle" class="home-menu-toggle" '
                               'type="button" aria-controls="public-nav" aria-expanded="true" hidden><i '
                               'data-lucide="menu"></i><span>Menu</span></button>{% endblock %}\n'
                               '{% block extra_js %}<script src="{% static \'js/public-navigation.js\' %}?v=info-1" '
                               'defer></script>{% endblock %}\n',
 'public/home.html': '{% extends "public/discovery_base.html" %}\n'
                     '{% load static %}\n'
                     '{% block title %}Tìm phòng trọ phù hợp{% endblock %}\n'
                     '{% block content %}\n'
                     '<section class="guest-hero">\n'
                     '  <div class="guest-hero-inner">\n'
                     '    <div class="guest-hero-copy">\n'
                     '      <p class="home-intro">{{ building_count }} tòa nhà <span aria-hidden="true">/</span> {{ '
                     'available_count }} phòng đang cho thuê</p>\n'
                     '      <h1>Tìm phòng trọ<br>phù hợp với bạn</h1>\n'
                     '      <p>Xem phòng theo tòa nhà, khoảng giá và tiện ích.<br class="desktop-break"> Lưu lại những '
                     'lựa chọn bạn muốn cân nhắc.</p>\n'
                     '      <div class="hero-assurance"><i data-lucide="shield-check"></i><span>Không chỉ là phòng '
                     'trọ<small>Mà là nơi để vững bước</small></span></div>\n'
                     '    </div>\n'
                     '    {% if hero_room %}\n'
                     '    <a class="home-room-preview" href="{% url \'public-room-detail\' hero_room.id %}" '
                     'aria-label="Xem phòng nổi bật {{ hero_room.number }} tại {{ hero_room.building.name }}">\n'
                     '      <div class="home-preview-image"><span class="home-featured-badge"><i data-lucide="flame" '
                     'aria-hidden="true"></i> HOT</span><img src="{{ hero_room.cover_image_url }}" alt="Ảnh phòng {{ '
                     'hero_room.number }} tại {{ hero_room.building.name }}" width="720" height="440" '
                     'fetchpriority="high"></div>\n'
                     '      <div class="home-preview-caption"><span class="home-room-number">{{ hero_room.number '
                     '}}</span><span><strong>{{ hero_room.building.name }}</strong><small>{{ '
                     'hero_room.monthly_rent|vnd }} đ/tháng</small></span><i data-lucide="arrow-up-right"></i></div>\n'
                     '    </a>\n'
                     '    {% else %}\n'
                     '    <div class="home-room-summary">\n'
                     '      <i data-lucide="building-2"></i><h2>Các phòng đang cho thuê</h2>\n'
                     '      <p>{{ available_count }} phòng tại {{ building_count }} tòa nhà</p>\n'
                     '      {% for room in featured_rooms|slice:\':3\' %}<a href="{% url \'public-room-detail\' '
                     'room.id %}"><span>Phòng {{ room.number }}<small>{{ room.building.name }}</small></span><span>{{ '
                     'room.monthly_rent|vnd }} đ/tháng <i data-lucide="arrow-up-right"></i></span></a>{% empty '
                     '%}<p>Thông tin phòng sẽ xuất hiện tại đây khi có phòng trống.</p>{% endfor %}\n'
                     '    </div>\n'
                     '    {% endif %}\n'
                     '    <form class="guest-search" action="{% url \'public-rooms\' %}" role="search" aria-label="Tìm '
                     'phòng trọ">\n'
                     '      <label class="home-search-field"><span>Khu vực</span><span class="home-field-input"><i '
                     'data-lucide="map-pin"></i><input name="q" aria-label="Khu vực, quận huyện, địa chỉ" '
                     'placeholder="Quận, huyện, địa chỉ"></span></label>\n'
                     '      <label class="home-search-field"><span>Tòa nhà</span><span class="home-field-input"><i '
                     'data-lucide="building-2"></i><select name="building" aria-label="Chọn tòa nhà"><option '
                     'value="">Tất cả tòa nhà</option>{% for building in buildings %}<option value="{{ building.name '
                     '}}">{{ building.name }}</option>{% endfor %}</select></span></label>\n'
                     '      <div class="home-search-field price-range"><span>Giá thuê / tháng</span><div '
                     'class="home-field-input"><input name="min_price" type="number" min="0" step="1" '
                     'inputmode="numeric" aria-label="Giá thuê từ" placeholder="Giá từ"><span '
                     'aria-hidden="true">–</span><input name="max_price" type="number" min="0" step="1" '
                     'inputmode="numeric" aria-label="Giá thuê đến" placeholder="Giá đến"></div></div>\n'
                     '      <label class="home-search-field"><span>Loại phòng</span><span class="home-field-input"><i '
                     'data-lucide="bed-double"></i><select aria-label="Loại phòng"><option>Loại '
                     'phòng</option><option>Phòng trọ</option><option>Căn hộ mini</option></select></span></label>\n'
                     '      <button class="btn primary" type="submit"><i data-lucide="search"></i> Tìm phòng</button>\n'
                     '    </form>\n'
                     '  </div>\n'
                     '</section>\n'
                     '<section class="benefit-strip" aria-label="Tìm phòng thuận tiện">\n'
                     '  <div><i data-lucide="house"></i><span><strong>Nhiều tòa nhà</strong><small>và vị trí thuận '
                     'tiện</small></span></div>\n'
                     '  <div><i data-lucide="shield-check"></i><span><strong>Thông tin rõ ràng</strong><small>hình ảnh '
                     'thực tế</small></span></div>\n'
                     '  <div><i data-lucide="heart"></i><span><strong>Dễ dàng so sánh</strong><small>và lưu phòng yêu '
                     'thích</small></span></div>\n'
                     '  <div><i data-lucide="headphones"></i><span><strong>Hỗ trợ nhanh chóng</strong><small>tận tình, '
                     'chuyên nghiệp</small></span></div>\n'
                     '</section>\n'
                     '<section id="gioi-thieu" class="property-browser">\n'
                     '  <aside class="filter-panel" aria-label="Bộ lọc tìm kiếm">\n'
                     '    <div class="home-filter-heading"><h2>Bộ lọc tìm kiếm</h2><button id="home-filter-toggle" '
                     'type="button" aria-controls="home-filter-fields" aria-expanded="true" hidden><i '
                     'data-lucide="sliders-horizontal"></i><span>Bộ lọc tìm kiếm</span><i '
                     'data-lucide="chevron-down"></i></button></div>\n'
                     '    <form id="home-filters" action="{% url \'public-rooms\' %}">\n'
                     '      <div id="home-filter-fields">\n'
                     '        <label for="home-district" class="home-filter-label">Khu vực</label>\n'
                     '        <select id="home-district" name="district"><option value="">Tất cả quận / '
                     'huyện</option><option value="Quận 3">Quận 3</option><option value="Quận 4">Quận '
                     '4</option><option value="Bình Thạnh">Bình Thạnh</option><option value="Thủ Đức">Thủ '
                     'Đức</option><option value="Gò Vấp">Gò Vấp</option></select>\n'
                     '        <fieldset><legend>Tòa nhà</legend>\n'
                     '          {% for group in building_groups %}<label class="check-row"><input type="checkbox" '
                     'name="building" value="{{ group.building.name }}"><span>{{ group.building.name }}</span><small '
                     'aria-label="{{ group.available_count }} phòng trống">{{ group.available_count '
                     '}}</small></label>{% endfor %}\n'
                     '        </fieldset>\n'
                     '        <label for="price-filter" class="home-filter-label">Khoảng giá</label>\n'
                     '        <input id="price-filter" name="max_price" class="range-control" type="range" '
                     'min="1000000" max="10000000" step="500000" value="10000000">\n'
                     '        <div class="range-label"><span>0 đ</span><output id="price-filter-value" '
                     'for="price-filter">10.000.000 đ</output></div>\n'
                     '        <fieldset><legend>Tiện ích</legend>\n'
                     '          <label class="check-row"><input type="checkbox" name="amenity" value="Máy '
                     'lạnh"><span>Có máy lạnh</span></label>\n'
                     '          <label class="check-row"><input type="checkbox" name="amenity" value="Bãi xe"><span>Có '
                     'bãi xe</span></label>\n'
                     '          <label class="check-row"><input type="checkbox" name="amenity" '
                     'value="Wi-Fi"><span>WiFi miễn phí</span></label>\n'
                     '        </fieldset>\n'
                     '        <button class="btn primary mobile-filter-submit" type="submit"><i '
                     'data-lucide="list-filter"></i> Áp dụng bộ lọc</button>\n'
                     '      </div>\n'
                     '    </form>\n'
                     '  </aside>\n'
                     '  <div class="building-results">\n'
                     '    <div class="results-heading"><div><h2>Danh sách tòa nhà</h2><p>Chọn tòa nhà để xem các phòng '
                     'bên trong</p></div><label for="home-sort">Sắp xếp <select id="home-sort" name="sort" '
                     'form="home-filters"><option value="">Theo số phòng</option><option value="price_asc">Giá thấp '
                     'nhất</option><option value="price_desc">Giá cao nhất</option></select></label></div>\n'
                     '    {% for group in building_groups %}\n'
                     '    <article class="building-block">\n'
                     '      <header>\n'
                     '        <div class="home-building-marker" aria-hidden="true">{% if forloop.counter < 10 %}0{% '
                     'endif %}{{ forloop.counter }}</div>\n'
                     '        <div class="building-info"><h3>{{ group.building.name }} {% if forloop.first %}<span>Tòa '
                     'nhà nổi bật</span>{% endif %}</h3><p><i data-lucide="map-pin"></i> {{ group.building.address '
                     '}}</p><div><span><i data-lucide="building-2"></i> {{ group.floor_count }} tầng</span><span><i '
                     'data-lucide="bed-double"></i> {{ group.available_count }} phòng trống</span><span><i '
                     'data-lucide="map-pin"></i> Gần chợ, trường học, trung tâm</span></div></div>\n'
                     '        <a class="view-building" href="{% url \'public-rooms\' %}?q={{ '
                     'group.building.name|urlencode }}">Xem tất cả {{ group.available_count }} phòng <i '
                     'data-lucide="arrow-right"></i></a>\n'
                     '      </header>\n'
                     '      <div class="room-carousel" data-room-carousel>\n'
                     '        <div class="compact-room-grid" id="building-rooms-{{ group.building.id }}" tabindex="0" '
                     'role="region" aria-label="Các phòng của {{ group.building.name }}">\n'
                     '          {% for room in group.rooms %}{% include "public/room_card.html" with home_card=True '
                     '%}{% endfor %}\n'
                     '        </div>\n'
                     '        <div class="room-carousel-controls" hidden>\n'
                     '          <div class="room-carousel-buttons">\n'
                     '            <button type="button" data-room-prev aria-controls="building-rooms-{{ '
                     'group.building.id }}" aria-label="Xem phòng phía trước của {{ group.building.name }}"><i '
                     'data-lucide="chevron-left"></i></button>\n'
                     '            <button type="button" data-room-next aria-controls="building-rooms-{{ '
                     'group.building.id }}" aria-label="Xem phòng tiếp theo của {{ group.building.name }}"><i '
                     'data-lucide="chevron-right"></i></button>\n'
                     '          </div>\n'
                     '        </div>\n'
                     '      </div>\n'
                     '    </article>\n'
                     '    {% empty %}<div class="empty-state"><i data-lucide="house"></i><h3>Chưa có phòng '
                     'trống</h3><p>Thông tin phòng sẽ được cập nhật tại đây.</p><a href="{% url \'public-contact\' '
                     '%}">Liên hệ hỗ trợ <i data-lucide="arrow-right"></i></a></div>{% endfor %}\n'
                     '  </div>\n'
                     '</section>\n'
                     '<script src="{% static \'js/room-carousel.js\' %}" defer></script>\n'
                     '<script src="{% static \'js/home-discovery.js\' %}?v=home-2" defer></script>\n'
                     '{% endblock %}\n',
 'public/room_card.html': '<article class="room-card" data-room-id="{{ room.id }}">\n'
                          '  <div class="room-visual">\n'
                          '    <a class="room-photo-link" href="{% url \'public-room-detail\' room.id %}" '
                          'aria-label="Xem phòng {{ room.number }}">\n'
                          '      {% if room.cover_image_url %}<img class="room-cover" src="{{ room.cover_image_url }}" '
                          'alt="Ảnh phòng {{ room.number }}" loading="lazy">{% elif home_card %}<span '
                          'class="home-photo-placeholder"><i data-lucide="image"></i><span>Ảnh đang cập '
                          'nhật</span></span>{% endif %}\n'
                          '    </a>\n'
                          '    <button type="button" class="favorite-icon" data-favorite-room="{{ room.id }}" '
                          'aria-label="Thêm phòng {{ room.number }} vào yêu thích" title="Lưu phòng yêu thích"><i '
                          'data-lucide="heart"></i></button>\n'
                          '  </div>\n'
                          '  <div class="room-body">\n'
                          '    <h3><a href="{% url \'public-room-detail\' room.id %}">Phòng {{ room.number '
                          '}}</a></h3>\n'
                          '    <div class="room-price"><strong>{{ room.monthly_rent|vnd }} đ/tháng</strong></div>\n'
                          '    <div class="room-meta"><span><i data-lucide="scan"></i> {% if room.area %}{{ room.area '
                          '}}m²{% else %}--{% endif %}</span><span><i data-lucide="bed-double"></i> {{ '
                          'room.max_occupants }} người</span></div>\n'
                          '    <span class="availability">Còn trống</span>\n'
                          '  </div>\n'
                          '</article>\n',
 'public/room_detail.html': '{% extends "public/base.html" %}\n'
                            '{% block title %}Phòng {{ room.number }} - {{ room.building.name }}{% endblock %}\n'
                            '{% block content %}\n'
                            '<section class="public-section room-detail">\n'
                            '  <nav class="detail-breadcrumb" aria-label="Đường dẫn"><a href="{% url \'public-home\' '
                            '%}">Trang chủ</a><i data-lucide="chevron-right"></i><a href="{% url \'public-rooms\' '
                            '%}">Tìm phòng</a><i data-lucide="chevron-right"></i><span>{{ room.building.name '
                            '}}</span><i data-lucide="chevron-right"></i><strong>Phòng {{ room.number '
                            '}}</strong></nav>\n'
                            '  <a class="back-link" href="{% url \'public-rooms\' %}">← Quay lại danh sách</a>\n'
                            '  <div class="room-detail-grid">\n'
                            '    <div class="room-gallery">\n'
                            '      <div class="detail-visual">{% if room.cover_image_url %}<img id="room-main-image" '
                            'src="{{ room.cover_image_url }}" alt="Ảnh phòng {{ room.number }}">{% if '
                            'room_images|length > 1 %}<button type="button" class="gallery-arrow previous" '
                            'data-gallery-direction="-1" aria-label="Ảnh trước"><i '
                            'data-lucide="chevron-left"></i></button><button type="button" class="gallery-arrow next" '
                            'data-gallery-direction="1" aria-label="Ảnh tiếp theo"><i '
                            'data-lucide="chevron-right"></i></button>{% endif %}{% else %}<span>🛏️</span>{% endif '
                            '%}</div>\n'
                            '      {% if room_images %}<div class="room-gallery-thumbs" aria-label="Ảnh phòng">{% for '
                            'media in room_images %}<button type="button" class="room-gallery-thumb{% if forloop.first '
                            '%} active{% endif %}" data-image-url="{{ media.url }}" data-image-index="{{ '
                            'forloop.counter0 }}" aria-label="Xem ảnh {{ forloop.counter }}"><img src="{{ media.url '
                            '}}" alt="Ảnh {{ forloop.counter }} của phòng {{ room.number }}" '
                            'loading="lazy"></button>{% endfor %}</div>{% endif %}\n'
                            '      {% if room_videos %}<h2>Video phòng</h2><div class="room-gallery-videos">{% for '
                            'media in room_videos %}<video src="{{ media.url }}" controls preload="metadata" '
                            'aria-label="Video phòng {{ room.number }} số {{ forloop.counter }}"></video>{% endfor '
                            '%}</div>{% endif %}\n'
                            '    </div>\n'
                            '    <article class="detail-card">\n'
                            '      <span class="availability">Còn trống</span>\n'
                            '      <p class="room-location">{{ room.building.name }} · Tầng {{ room.floor }}</p>\n'
                            '      <h1>Phòng {{ room.number }}</h1>\n'
                            '      <p class="detail-address">{{ room.building.address }}</p>\n'
                            '      <div class="price-large">{{ room.monthly_rent|vnd }} đ <span>/ tháng</span></div>\n'
                            '      <div class="detail-grid"><div><span>Diện tích</span><strong>{{ '
                            'room.area|default:"Chưa cập nhật" }}{% if room.area %} m²{% endif '
                            '%}</strong></div><div><span>Số người tối đa</span><strong>{{ room.max_occupants }} '
                            'người</strong></div><div><span>Tiền cọc</span><strong>{{ room.deposit_amount|vnd }} '
                            'đ</strong></div><div><span>Trạng thái</span><strong>{{ room.get_status_display '
                            '}}</strong></div></div>\n'
                            '      <h2>Tiện nghi</h2><div class="amenity-list">{% for item in amenities %}<span><i '
                            'data-lucide="{{ item.icon }}"></i>{{ item.name }}</span>{% empty %}<span><i '
                            'data-lucide="circle-ellipsis"></i>Đang cập nhật</span>{% endfor %}</div>\n'
                            '      {% if room.description %}<h2>Mô tả</h2><p>{{ room.description|linebreaksbr }}</p>{% '
                            'endif %}\n'
                            '      <div class="contact-card"><span class="contact-avatar">{{ '
                            'contact.get_full_name|default:contact.username|first|upper }}</span><div '
                            'class="contact-info"><small>Người liên hệ</small><strong>{{ '
                            'contact.get_full_name|default:contact.username }}</strong><span>{{ '
                            'contact.get_role_display }}</span></div><div class="contact-actions"><a class="btn" '
                            'href="mailto:1150080030@sv.hcmunre.edu.vn"><i data-lucide="mail"></i> '
                            '1150080030@sv.hcmunre.edu.vn</a><a class="btn primary" href="tel:0902966704"><i '
                            'data-lucide="phone"></i> Gọi 0902966704</a></div></div>\n'
                            '    </article>\n'
                            '  </div>\n'
                            '  {% if related_rooms %}<section class="related-rooms"><div '
                            'class="related-heading"><div><span class="eyebrow">CÓ THỂ BẠN QUAN TÂM</span><h2>Phòng '
                            'tương tự</h2><p>Các phòng còn trống có vị trí và mức giá gần với lựa chọn của '
                            'bạn.</p></div><a href="{% url \'public-rooms\' %}">Xem tất cả <i '
                            'data-lucide="arrow-right"></i></a></div><div class="room-grid related-room-grid">{% for '
                            'room in related_rooms %}{% include "public/room_card.html" %}{% endfor '
                            '%}</div></section>{% endif %}\n'
                            '</section>\n'
                            '<script>document.addEventListener("DOMContentLoaded",()=>{const '
                            'main=document.getElementById("room-main-image"),visual=main?.closest(".detail-visual"),thumbs=[...document.querySelectorAll(".room-gallery-thumb")];if(!main||!visual)return;let '
                            'current=Math.max(0,thumbs.findIndex(item=>item.classList.contains("active")));function '
                            'show(index){if(!thumbs.length)return;current=(index+thumbs.length)%thumbs.length;main.src=thumbs[current].dataset.imageUrl;thumbs.forEach((item,i)=>item.classList.toggle("active",i===current));visual.classList.remove("zoomed")}thumbs.forEach((button,index)=>button.addEventListener("click",()=>show(index)));document.querySelectorAll("[data-gallery-direction]").forEach(button=>button.addEventListener("click",()=>show(current+Number(button.dataset.galleryDirection))));visual.addEventListener("mouseenter",event=>{if(!event.target.closest(".gallery-arrow"))visual.classList.add("zoomed")});visual.addEventListener("mousemove",event=>{if(event.target.closest(".gallery-arrow")){visual.classList.remove("zoomed");return}const '
                            'box=visual.getBoundingClientRect(),x=(event.clientX-box.left)/box.width*100,y=(event.clientY-box.top)/box.height*100;main.style.transformOrigin=`${x}% '
                            '${y}%`;visual.classList.add("zoomed")});visual.addEventListener("mouseleave",()=>{visual.classList.remove("zoomed");main.style.transformOrigin="center"})});</script>\n'
                            '{% endblock %}\n',
 'public/room_list.html': '{% extends "public/base.html" %}\n'
                          '{% block title %}Danh sách phòng cho thuê{% endblock %}\n'
                          '{% block content %}<section class="public-section"><div class="section-heading"><div><span '
                          'class="eyebrow">PHÒNG CHO THUÊ</span><h1>Tìm phòng phù hợp</h1></div><a href="{% url '
                          '\'public-home\' %}#gioi-thieu">← Quay lại bộ lọc</a></div>\n'
                          '<form class="public-filter" method="get">\n'
                          '  <input name="q" value="{{ q }}" placeholder="Khu vực, tòa nhà, số phòng">\n'
                          '  <select name="building"><option value="">Tất cả tòa nhà</option>{% for building in '
                          'buildings %}<option value="{{ building.name }}" {% if building.name in selected_buildings '
                          '%}selected{% endif %}>{{ building.name }}</option>{% endfor %}</select>\n'
                          '  <input name="min_price" type="number" min="0" value="{{ min_price }}" placeholder="Giá '
                          'từ">\n'
                          '  <input name="max_price" type="number" min="0" value="{{ max_price }}" placeholder="Giá '
                          'đến">\n'
                          '  <select name="sort"><option value="">Mặc định</option><option value="price_asc" {% if '
                          "sort == 'price_asc' %}selected{% endif %}>Giá thấp đến cao</option><option "
                          'value="price_desc" {% if sort == \'price_desc\' %}selected{% endif %}>Giá cao đến '
                          'thấp</option></select>\n'
                          '  <button class="btn primary">Áp dụng</button>\n'
                          '</form>\n'
                          '{% if district or selected_buildings or selected_amenities or min_price or max_price %}<div '
                          'class="active-filters"><strong>Đang lọc:</strong>{% if district %}<span>{{ district '
                          '}}</span>{% endif %}{% for name in selected_buildings %}<span>{{ name }}</span>{% endfor '
                          '%}{% for name in selected_amenities %}<span>{{ name }}</span>{% endfor %}{% if max_price '
                          '%}<span>Tối đa {{ max_price }} đ</span>{% endif %}<a href="{% url \'public-rooms\' %}">Xóa '
                          'bộ lọc</a></div>{% endif %}\n'
                          '<p class="result-count">Tìm thấy <strong>{{ page_obj.paginator.count }}</strong> phòng còn '
                          'trống{% if page_obj.paginator.count %} · Đang xem {{ page_obj.start_index }}–{{ '
                          'page_obj.end_index }}{% endif %}</p><div class="room-grid">{% for room in rooms %}{% '
                          'include \'public/room_card.html\' %}{% empty %}<div class="empty-state">Không tìm thấy '
                          'phòng phù hợp. Hãy thử thay đổi điều kiện tìm kiếm.</div>{% endfor %}</div>\n'
                          '{% if page_obj.has_other_pages %}<nav class="pagination" aria-label="Phân trang phòng cho '
                          'thuê">\n'
                          '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}{% if '
                          'page_query %}&amp;{{ page_query }}{% endif %}" aria-label="Trang trước">← Trước</a>{% else '
                          '%}<span class="disabled">← Trước</span>{% endif %}\n'
                          '  {% for page_number in page_obj.paginator.page_range %}{% if page_number == '
                          'page_obj.number %}<span class="current" aria-current="page">{{ page_number }}</span>{% elif '
                          "page_number >= page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                          'href="?page={{ page_number }}{% if page_query %}&amp;{{ page_query }}{% endif %}">{{ '
                          'page_number }}</a>{% endif %}{% endfor %}\n'
                          '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}{% if page_query '
                          '%}&amp;{{ page_query }}{% endif %}" aria-label="Trang sau">Sau →</a>{% else %}<span '
                          'class="disabled">Sau →</span>{% endif %}\n'
                          '</nav>{% endif %}\n'
                          '</section>{% endblock %}\n',
 'registration/login.html': '{% load static %}\n'
                            '<!doctype html>\n'
                            '<html lang="vi">\n'
                            '<head>\n'
                            '  <meta charset="utf-8">\n'
                            '  <meta name="viewport" content="width=device-width, initial-scale=1">\n'
                            '  <title>Đăng nhập | Nhà Trọ An Tâm</title>\n'
                            '  <link rel="icon" type="image/png" href="{% static \'images/favicon.png\' %}">\n'
                            '  <link rel="stylesheet" href="{% static \'css/loading.css\' %}">\n'
                            '  <link rel="stylesheet" href="{% static \'css/app.css\' %}">\n'
                            '  <link rel="stylesheet" href="{% static \'css/login.css\' %}">\n'
                            '  <link rel="stylesheet" href="{% static \'css/lucide.css\' %}">\n'
                            '</head>\n'
                            '<body class="auth-page">\n'
                            "  {% include 'includes/loading.html' %}\n"
                            '  <main class="auth-shell">\n'
                            '    <section class="auth-visual" style="--login-image:url(\'{% static '
                            '\'images/anhlogin.png\' %}\')">\n'
                            '      <a class="auth-brand auth-brand-light" href="{% url \'public-home\' %}"><span><img '
                            'src="{% static \'images/anhlogo.png\' %}" alt="Logo Nhà Trọ An '
                            'Tâm"></span><div><strong>Nhà Trọ An Tâm</strong><small>An cư để vững '
                            'bước</small></div></a>\n'
                            '      <div class="visual-copy"><span class="visual-badge"><i '
                            'data-lucide="shield-check"></i> Không gian sống đáng tin cậy</span><h1>Một nơi ở '
                            'tốt<br>cho hành trình tốt hơn.</h1></div>\n'
                            '      <div class="visual-stats"><span><strong>120+</strong><small>Phòng cho '
                            'thuê</small></span><span><strong>98%</strong><small>Khách hàng hài '
                            'lòng</small></span></div>\n'
                            '    </section>\n'
                            '    <section class="auth-panel">\n'
                            '      <a class="back-home" href="{% url \'public-home\' %}">Về trang chủ</a>\n'
                            '      <div class="auth-form-wrap">\n'
                            '        <a class="auth-brand auth-brand-mobile" href="{% url \'public-home\' '
                            '%}"><span><img src="{% static \'images/anhlogo.png\' %}" alt="Logo Nhà Trọ An '
                            'Tâm"></span><div><strong>Nhà Trọ An Tâm</strong><small>An cư để vững '
                            'bước</small></div></a>\n'
                            '        <div class="auth-heading"><span>CHÀO MỪNG TRỞ LẠI</span><h2>Đăng nhập tài '
                            'khoản</h2></div>\n'
                            '        {% if form.errors %}<div class="auth-error"><i '
                            'data-lucide="circle-alert"></i><span>Tên đăng nhập hoặc mật khẩu không '
                            'đúng.</span></div>{% endif %}\n'
                            '        <form method="post" class="auth-form">\n'
                            '          {% csrf_token %}\n'
                            '          {% if next %}<input type="hidden" name="next" value="{{ next }}">{% endif %}\n'
                            '          <label for="id_username">Tên đăng nhập</label>\n'
                            '          <div class="input-wrap"><i data-lucide="user"></i>{{ form.username }}</div>\n'
                            '          <div class="password-label"><label for="id_password">Mật khẩu</label><a '
                            'href="#">Quên mật khẩu?</a></div>\n'
                            '          <div class="input-wrap"><i data-lucide="lock-keyhole"></i>{{ form.password '
                            '}}<button id="toggle-password" type="button" aria-label="Hiện mật khẩu"><i '
                            'data-lucide="eye"></i></button></div>\n'
                            '          <label class="remember-row"><input type="checkbox" name="remember"><span>Ghi '
                            'nhớ đăng nhập</span></label>\n'
                            '          <button class="auth-submit" type="submit">Đăng nhập</button>\n'
                            '        </form>\n'
                            '        <p class="auth-help"><i data-lucide="headphones"></i> Cần hỗ trợ? <a '
                            'href="mailto:1150080030@sv.hcmunre.edu.vn">Liên hệ quản trị viên</a></p>\n'
                            '      </div>\n'
                            '      <p class="auth-copyright">© 2026 Nhà Trọ An Tâm. Mọi quyền được bảo lưu.</p>\n'
                            '    </section>\n'
                            '  </main>\n'
                            '  <script src="{% static \'lucide.min.js\' %}"></script>\n'
                            '  '
                            '<script>lucide.createIcons({attrs:{"stroke-width":2}});document.getElementById("toggle-password").addEventListener("click",function(){const '
                            'input=document.getElementById("id_password");input.type=input.type==="password"?"text":"password";this.innerHTML=input.type==="password"?\'<i '
                            'data-lucide="eye"></i>\':\'<i '
                            'data-lucide="eye-off"></i>\';lucide.createIcons({attrs:{"stroke-width":2}})});</script>\n'
                            '  <script src="{% static \'js/loading.js\' %}"></script>\n'
                            '</body>\n'
                            '</html>\n',
 'registration/password_change.html': '{% extends "base.html" %}\n'
                                      '{% block title %}Đổi mật khẩu — QL Phòng Cho Thuê{% endblock %}\n'
                                      '{% block page_title %}Đổi mật khẩu{% endblock %}\n'
                                      '{% block page_subtitle %}Cập nhật mật khẩu để tăng cường an toàn tài khoản{% '
                                      'endblock %}\n'
                                      '\n'
                                      '{% block content %}\n'
                                      '<section class="panel form-panel" style="max-width: 650px;">\n'
                                      '  <div class="panel-heading" style="margin-bottom: 20px;">\n'
                                      '    <h2>Thay đổi mật khẩu đăng nhập</h2>\n'
                                      '  </div>\n'
                                      '\n'
                                      '  <form method="post" novalidate>\n'
                                      '    {% csrf_token %}\n'
                                      '    {% if form.errors %}\n'
                                      '      <div class="alert error" style="margin-bottom: 20px;">\n'
                                      '        Vui lòng kiểm tra lại thông tin mật khẩu bên dưới.\n'
                                      '      </div>\n'
                                      '    {% endif %}\n'
                                      '\n'
                                      '    {% for field in form %}\n'
                                      '      <p style="margin-bottom: 16px;">\n'
                                      '        <label for="{{ field.id_for_label }}">{{ field.label }}:</label>\n'
                                      '        <span>\n'
                                      '          {{ field }}\n'
                                      '          {% if field.errors %}\n'
                                      '            <small style="color: var(--red); display: block; margin-top: 5px; '
                                      'font-weight: 500;">{{ field.errors.0 }}</small>\n'
                                      '          {% endif %}\n'
                                      '          {% if field.help_text %}\n'
                                      '            <small style="color: var(--muted); display: block; margin-top: 5px; '
                                      'font-size: 12px; line-height: 1.4;">{{ field.help_text }}</small>\n'
                                      '          {% endif %}\n'
                                      '        </span>\n'
                                      '      </p>\n'
                                      '    {% endfor %}\n'
                                      '\n'
                                      '    <div class="actions" style="margin-top: 25px;">\n'
                                      '      <button class="btn primary" type="submit">Xác nhận đổi mật khẩu</button>\n'
                                      '      <a class="btn" href="{% if user.role == \'tenant\' %}{% url '
                                      '\'tenant-portal\' %}{% else %}{% url \'dashboard\' %}{% endif %}">Hủy bỏ</a>\n'
                                      '    </div>\n'
                                      '  </form>\n'
                                      '</section>\n'
                                      '{% endblock %}\n'
                                      '\n',
 'rentals/_list_header.html': '<div class="page-actions"><form method="get" class="search"><input name="q" value="{{ q '
                              '}}" placeholder="Tìm kiếm..."><button class="btn" type="submit">Tìm</button></form>{% '
                              'if create_url %}<a class="btn primary" href="{% url create_url %}">Thêm mới</a>{% endif '
                              '%}</div>\n',
 'rentals/building_list.html': '{% extends "base.html" %}\n'
                               '{% block page_title %}Tòa nhà{% endblock %}\n'
                               '{% block page_subtitle %}Quản lý danh sách tòa nhà trong hệ thống{% endblock %}\n'
                               '{% block content %}\n'
                               '<section class="building-overview">\n'
                               '  <article class="overview-card total"><span><i '
                               'data-lucide="building-2"></i></span><strong>{{ building_total }}</strong><small>Tổng '
                               'số tòa nhà</small></article>\n'
                               '  <article class="overview-card active"><span><i '
                               'data-lucide="circle-check"></i></span><strong>{{ building_active '
                               '}}</strong><small>Đang hoạt động</small></article>\n'
                               '  <article class="overview-card paused"><span><i '
                               'data-lucide="pause"></i></span><strong>0</strong><small>Tạm ngừng</small></article>\n'
                               '  <article class="overview-card inactive"><span><i '
                               'data-lucide="circle-x"></i></span><strong>{{ building_inactive }}</strong><small>Ngừng '
                               'hoạt động</small></article>\n'
                               '  <div class="building-quote"><i data-lucide="building"></i><p>“Quản lý tòa '
                               'nhà<br>hiệu quả hơn mỗi ngày”</p></div>\n'
                               '</section>\n'
                               '<section class="building-panel building-card-panel">\n'
                               '  <header class="card-list-heading"><div><h2>Danh sách tòa nhà</h2><p>{{ '
                               'paginator.count }} tòa nhà được tìm thấy</p></div><a class="btn primary add-building" '
                               'href="{% url \'building-create\' %}"><i data-lucide="plus"></i>Thêm tòa '
                               'nhà</a></header>\n'
                               '  <form method="get" class="card-filter-bar">\n'
                               '    <label class="building-search"><i data-lucide="search"></i><input name="q" '
                               'value="{{ q }}" placeholder="Tìm kiếm theo tên, địa chỉ..."></label>\n'
                               '    <label class="select-field"><span>Trạng thái</span><select name="status" '
                               'onchange="this.form.submit()"><option value="">Tất cả</option><option value="active" '
                               "{% if status == 'active' %}selected{% endif %}>Hoạt động</option><option "
                               'value="inactive" {% if status == \'inactive\' %}selected{% endif %}>Ngừng hoạt '
                               'động</option></select></label>\n'
                               '    <label class="select-field"><span>Sắp xếp</span><select name="sort" '
                               'onchange="this.form.submit()"><option value="newest" {% if sort == \'newest\' '
                               '%}selected{% endif %}>Mới nhất</option><option value="name" {% if sort == \'name\' '
                               '%}selected{% endif %}>Tên A–Z</option></select></label>\n'
                               '    <button class="btn filter-button" type="submit">Tìm kiếm</button>\n'
                               '    <div class="view-switch"><span class="active"><i '
                               'data-lucide="layout-grid"></i></span><span><i data-lucide="list"></i></span></div>\n'
                               '  </form>\n'
                               '  <div class="building-card-grid">\n'
                               '    {% for x in objects %}<article class="property-card">\n'
                               '      <header><span class="select-box"></span><div><h3>{{ x.name }}</h3><p><i '
                               'data-lucide="map-pin"></i>{{ x.address|truncatechars:50 }}</p></div><div '
                               'class="card-actions"><a href="{% url \'public-rooms\' %}?building={{ x.name|urlencode '
                               '}}" title="Xem phòng"><i data-lucide="eye"></i></a><a href="{% url \'building-update\' '
                               'x.id %}" title="Chỉnh sửa"><i data-lucide="pencil"></i></a></div></header>\n'
                               '      <div class="room-counts"><span><strong>{{ x.total_rooms }}</strong><small>Tổng '
                               'phòng</small></span><span class="available"><strong>{{ x.available_rooms '
                               '}}</strong><small>Trống</small></span><span class="occupied"><strong>{{ '
                               'x.occupied_rooms }}</strong><small>Đang thuê</small></span></div>\n'
                               '      <div class="occupancy"><div><span>Lấp đầy</span><strong>{{ x.occupancy_percent '
                               '}}%</strong></div><progress max="100" value="{{ x.occupancy_percent '
                               '}}"></progress></div>\n'
                               '      <div class="amenity-tags">{% for name in x.amenity_tags %}<span>{{ name '
                               '}}</span>{% empty %}<span>Đang cập nhật tiện ích</span>{% endfor %}{% if '
                               'x.amenity_extra %}<span>+{{ x.amenity_extra }}</span>{% endif %}</div>\n'
                               '      <footer><span>Tạo lúc {{ x.created_at|date:"d/m/Y" }}</span>{% if x.is_active '
                               '%}<span class="status-dot active">Hoạt động</span>{% else %}<span class="status-dot '
                               'inactive">Ngừng hoạt động</span>{% endif %}</footer>\n'
                               '    </article>{% empty %}<div class="empty-state">Không tìm thấy tòa nhà phù '
                               'hợp.</div>{% endfor %}\n'
                               '  </div>\n'
                               '  <footer class="building-footer"><span>Hiển thị {{ page_obj.start_index }}–{{ '
                               'page_obj.end_index }} của {{ paginator.count }} tòa nhà</span>{% if '
                               'page_obj.has_other_pages %}<nav class="pagination">{% if page_obj.has_previous %}<a '
                               'href="?page={{ page_obj.previous_page_number }}&q={{ q|urlencode }}&status={{ status '
                               '}}&sort={{ sort }}">←</a>{% endif %}<span class="current">{{ page_obj.number '
                               '}}</span>{% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                               'q|urlencode }}&status={{ status }}&sort={{ sort }}">→</a>{% endif %}</nav>{% endif '
                               '%}</footer>\n'
                               '</section>\n'
                               '{% endblock %}\n',
 'rentals/contract_detail.html': '{% extends "base.html" %}\n'
                                 '{% block page_title %}Hợp đồng {{ contract.code }}{% endblock %}\n'
                                 '{% block content %}\n'
                                 '<div class="page-actions" style="flex-wrap:wrap;gap:10px;">\n'
                                 '  <div style="display:flex;gap:8px;align-items:center;">\n'
                                 '    <a class="btn" href="{% url \'contracts\' %}">← Danh sách hợp đồng</a>\n'
                                 "    {% if contract.status == 'draft' %}\n"
                                 '    <a class="btn primary" href="{% url \'contract-update\' contract.id %}">Chỉnh '
                                 'sửa hợp đồng nháp</a>\n'
                                 '    {% endif %}\n'
                                 "    {% if contract.status == 'active' %}\n"
                                 '    <a class="btn primary" href="{% url \'invoice-create\' %}?contract={{ '
                                 'contract.id }}">+ Lập hóa đơn kỳ mới</a>\n'
                                 '    {% endif %}\n'
                                 '  </div>\n'
                                 '  <div style="display:flex;gap:8px;flex-wrap:wrap;">\n'
                                 "    {% if contract.status == 'draft' %}\n"
                                 '    <form method="post" action="{% url \'contract-activate\' contract.id %}" '
                                 'onsubmit="return confirm(\'Xác nhận kích hoạt hợp đồng {{ contract.code }}? Phòng sẽ '
                                 'chuyển sang trạng thái Đang thuê.\');">\n'
                                 '      {% csrf_token %}\n'
                                 '      <button class="btn primary" type="submit">Kích hoạt hợp đồng</button>\n'
                                 '    </form>\n'
                                 '    {% endif %}\n'
                                 "    {% if contract.status == 'active' %}\n"
                                 '    <form method="post" action="{% url \'contract-terminate\' contract.id %}" '
                                 'onsubmit="return confirm(\'Xác nhận chấm dứt/thanh lý hợp đồng {{ contract.code '
                                 '}}?\');">\n'
                                 '      {% csrf_token %}\n'
                                 '      <button class="btn" type="submit" '
                                 'style="color:var(--orange);border-color:var(--orange);">Chấm dứt / Thanh '
                                 'lý</button>\n'
                                 '    </form>\n'
                                 '    {% endif %}\n'
                                 "    {% if contract.status == 'draft' or contract.status == 'active' %}\n"
                                 '    <form method="post" action="{% url \'contract-cancel\' contract.id %}" '
                                 'onsubmit="return confirm(\'Bạn có chắc chắn muốn hủy hợp đồng {{ contract.code '
                                 '}}?\');">\n'
                                 '      {% csrf_token %}\n'
                                 '      <button class="btn" type="submit" '
                                 'style="color:var(--red);border-color:var(--red);">Hủy hợp đồng</button>\n'
                                 '    </form>\n'
                                 '    {% endif %}\n'
                                 '  </div>\n'
                                 '</div>\n'
                                 '\n'
                                 '<section class="two-columns" style="margin-bottom:20px;">\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Thông tin hợp đồng</h2>\n'
                                 '      <span class="badge">{{ contract.get_status_display }}</span>\n'
                                 '    </div>\n'
                                 '    <div class="detail-grid">\n'
                                 '      <div><span>Mã hợp đồng</span><strong>{{ contract.code }}</strong></div>\n'
                                 '      <div><span>Phòng</span><strong>{{ contract.room.number }} ({{ '
                                 'contract.room.building.name }})</strong></div>\n'
                                 '      <div><span>Khách đại diện</span><strong><a href="{% url \'tenant-detail\' '
                                 'contract.representative.id %}" style="color:var(--primary);text-decoration:none;">{{ '
                                 'contract.representative.full_name }}</a></strong></div>\n'
                                 '      <div><span>Số điện thoại</span><strong>{{ contract.representative.phone '
                                 '}}</strong></div>\n'
                                 '      <div><span>Ngày bắt đầu</span><strong>{{ contract.start_date|date:"d/m/Y" '
                                 '}}</strong></div>\n'
                                 '      <div><span>Ngày kết thúc</span><strong>{{ contract.end_date|date:"d/m/Y" '
                                 '}}</strong></div>\n'
                                 '      <div><span>Giá thuê hằng tháng</span><strong>{{ contract.monthly_rent|vnd }} '
                                 'đ</strong></div>\n'
                                 '      <div><span>Tiền đặt cọc</span><strong>{{ contract.deposit_amount|vnd }} '
                                 'đ</strong></div>\n'
                                 '      <div><span>Ngày lập HĐơn / Hạn trả</span><strong>Ngày {{ contract.billing_day '
                                 '}} / Ngày {{ contract.due_day }}</strong></div>\n'
                                 '      <div><span>Trạng thái phòng</span><strong>{{ contract.room.get_status_display '
                                 '}}</strong></div>\n'
                                 '    </div>\n'
                                 '    {% if contract.notes %}\n'
                                 '    <hr style="border:0;border-top:1px solid var(--line);margin:16px 0;">\n'
                                 '    <div>\n'
                                 '      <span class="muted">Ghi chú hợp đồng:</span>\n'
                                 '      <p style="margin:6px 0 0;white-space:pre-line;">{{ contract.notes }}</p>\n'
                                 '    </div>\n'
                                 '    {% endif %}\n'
                                 '  </article>\n'
                                 '\n'
                                 '  <article class="panel">\n'
                                 '    <h2>Gia hạn hợp đồng</h2>\n'
                                 "    {% if contract.status == 'active' or contract.status == 'expired' %}\n"
                                 '    <p class="muted" style="margin-top:0;">Gia hạn thời gian thuê cho hợp đồng '
                                 '<strong>{{ contract.code }}</strong> (hiện kết thúc ngày {{ '
                                 'contract.end_date|date:"d/m/Y" }}).</p>\n'
                                 '    <form method="post" action="{% url \'contract-renew\' contract.id %}" '
                                 'onsubmit="return confirm(\'Xác nhận gia hạn hợp đồng {{ contract.code }}?\');">\n'
                                 '      {% csrf_token %}\n'
                                 '      {{ renew_form.as_p }}\n'
                                 '      <div class="actions">\n'
                                 '        <button class="btn primary" type="submit">Xác nhận gia hạn</button>\n'
                                 '      </div>\n'
                                 '    </form>\n'
                                 '    {% else %}\n'
                                 '    <p class="muted">Chỉ hợp đồng đang hiệu lực hoặc hết hạn mới có thể gia '
                                 'hạn.</p>\n'
                                 '    {% endif %}\n'
                                 '  </article>\n'
                                 '</section>\n'
                                 '\n'
                                 '<section class="two-columns" style="margin-bottom:20px;">\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Người ở cùng ({{ members|length }})</h2>\n'
                                 '    </div>\n'
                                 '    <div class="table-wrap">\n'
                                 '      <table>\n'
                                 '        <thead>\n'
                                 '          <tr>\n'
                                 '            <th>Họ tên</th>\n'
                                 '            <th>Điện thoại</th>\n'
                                 '            <th>CCCD</th>\n'
                                 '            <th>Ngày vào ở</th>\n'
                                 '            <th>Ngày rời đi</th>\n'
                                 '            <th>Thao tác</th>\n'
                                 '          </tr>\n'
                                 '        </thead>\n'
                                 '        <tbody>\n'
                                 '          {% for m in members %}\n'
                                 '          <tr>\n'
                                 '            <td><a href="{% url \'tenant-detail\' m.tenant.id %}" '
                                 'style="color:var(--primary);text-decoration:none;font-weight:600;">{{ '
                                 'm.tenant.full_name }}</a></td>\n'
                                 '            <td>{{ m.tenant.phone }}</td>\n'
                                 '            <td>{{ m.tenant.identity_number }}</td>\n'
                                 '            <td>{{ m.joined_date|date:"d/m/Y" }}</td>\n'
                                 '            <td>{% if m.left_date %}{{ m.left_date|date:"d/m/Y" }}{% else %}Đang ở{% '
                                 'endif %}</td>\n'
                                 '            <td>\n'
                                 '              <form method="post" action="{% url \'contract-member-remove\' '
                                 'contract.id m.id %}" onsubmit="return confirm(\'Xóa {{ m.tenant.full_name }} khỏi '
                                 'danh sách người ở cùng?\');" style="display:inline;">\n'
                                 '                {% csrf_token %}\n'
                                 '                <button class="btn compact" type="submit" '
                                 'style="color:var(--red);">Xóa</button>\n'
                                 '              </form>\n'
                                 '            </td>\n'
                                 '          </tr>\n'
                                 '          {% empty %}\n'
                                 '          <tr><td colspan="6">Chưa có người ở cùng nào được đăng ký.</td></tr>\n'
                                 '          {% endfor %}\n'
                                 '        </tbody>\n'
                                 '      </table>\n'
                                 '    </div>\n'
                                 '  </article>\n'
                                 '\n'
                                 '  <article class="panel">\n'
                                 '    <h2>Thêm người ở cùng</h2>\n'
                                 '    <form method="post" action="{% url \'contract-member-add\' contract.id %}">\n'
                                 '      {% csrf_token %}\n'
                                 '      {{ member_form.as_p }}\n'
                                 '      <div class="actions">\n'
                                 '        <button class="btn primary" type="submit">Thêm vào hợp đồng</button>\n'
                                 '      </div>\n'
                                 '    </form>\n'
                                 '  </article>\n'
                                 '</section>\n'
                                 '\n'
                                 '<section class="two-columns" style="margin-bottom:20px;">\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Dịch vụ áp dụng trong hợp đồng ({{ contract_services|length }})</h2>\n'
                                 '      <a class="btn compact" href="{% url \'services\' %}">Danh mục dịch vụ</a>\n'
                                 '    </div>\n'
                                 '    <div class="table-wrap">\n'
                                 '      <table>\n'
                                 '        <thead>\n'
                                 '          <tr>\n'
                                 '            <th>Dịch vụ</th>\n'
                                 '            <th>Đơn vị tính</th>\n'
                                 '            <th>Đơn giá áp dụng</th>\n'
                                 '            <th>Số lượng</th>\n'
                                 '            <th>Trạng thái</th>\n'
                                 '            <th>Thao tác</th>\n'
                                 '          </tr>\n'
                                 '        </thead>\n'
                                 '        <tbody>\n'
                                 '          {% for cs in contract_services %}\n'
                                 '          <tr>\n'
                                 '            <td><strong>{{ cs.service.name }}</strong></td>\n'
                                 '            <td>{{ cs.service.get_unit_display }}</td>\n'
                                 '            <td>{{ cs.unit_price|vnd }} đ</td>\n'
                                 '            <td>{{ cs.quantity }}</td>\n'
                                 '            <td>{{ cs.is_active|yesno:"Đang áp dụng,Tạm ngưng" }}</td>\n'
                                 '            <td>\n'
                                 '              <form method="post" action="{% url \'contract-service-remove\' '
                                 'contract.id cs.id %}" onsubmit="return confirm(\'Gỡ dịch vụ {{ cs.service.name }} '
                                 'khỏi hợp đồng?\');" style="display:inline;">\n'
                                 '                {% csrf_token %}\n'
                                 '                <button class="btn compact" type="submit" '
                                 'style="color:var(--red);">Gỡ</button>\n'
                                 '              </form>\n'
                                 '            </td>\n'
                                 '          </tr>\n'
                                 '          {% empty %}\n'
                                 '          <tr><td colspan="6">Chưa gắn dịch vụ riêng. Điện/nước sẽ tự lấy theo bảng '
                                 'giá chung nếu có chỉ số.</td></tr>\n'
                                 '          {% endfor %}\n'
                                 '        </tbody>\n'
                                 '      </table>\n'
                                 '    </div>\n'
                                 '  </article>\n'
                                 '\n'
                                 '  <article class="panel">\n'
                                 '    <h2>Gắn / Cập nhật dịch vụ hợp đồng</h2>\n'
                                 '    <form method="post" action="{% url \'contract-service-add\' contract.id %}">\n'
                                 '      {% csrf_token %}\n'
                                 '      {{ service_form.as_p }}\n'
                                 '      <div class="actions">\n'
                                 '        <button class="btn primary" type="submit">Lưu dịch vụ hợp đồng</button>\n'
                                 '      </div>\n'
                                 '    </form>\n'
                                 '  </article>\n'
                                 '</section>\n'
                                 '\n'
                                 '<section class="panel">\n'
                                 '  <div class="panel-heading">\n'
                                 '    <h2>Danh sách hóa đơn của hợp đồng ({{ invoices|length }})</h2>\n'
                                 "    {% if contract.status == 'active' %}\n"
                                 '    <a class="btn primary compact" href="{% url \'invoice-create\' %}?contract={{ '
                                 'contract.id }}">+ Tạo hóa đơn</a>\n'
                                 '    {% endif %}\n'
                                 '  </div>\n'
                                 '  <div class="table-wrap">\n'
                                 '    <table>\n'
                                 '      <thead>\n'
                                 '        <tr>\n'
                                 '          <th>Mã hóa đơn</th>\n'
                                 '          <th>Kỳ</th>\n'
                                 '          <th>Tổng tiền</th>\n'
                                 '          <th>Đã thanh toán</th>\n'
                                 '          <th>Còn nợ</th>\n'
                                 '          <th>Hạn thanh toán</th>\n'
                                 '          <th>Trạng thái</th>\n'
                                 '          <th>Thao tác</th>\n'
                                 '        </tr>\n'
                                 '      </thead>\n'
                                 '      <tbody>\n'
                                 '        {% for inv in invoices %}\n'
                                 '        <tr>\n'
                                 '          <td><a href="{% url \'invoice-detail\' inv.id %}" '
                                 'style="color:var(--primary);font-weight:600;text-decoration:none;">{{ inv.code '
                                 '}}</a></td>\n'
                                 '          <td>{{ inv.period|date:"m/Y" }}</td>\n'
                                 '          <td>{{ inv.total_amount|vnd }} đ</td>\n'
                                 '          <td>{{ inv.paid_amount|vnd }} đ</td>\n'
                                 '          <td>{{ inv.balance|vnd }} đ</td>\n'
                                 '          <td>{{ inv.due_date|date:"d/m/Y" }}</td>\n'
                                 '          <td><span class="badge">{{ inv.get_status_display }}</span></td>\n'
                                 '          <td><a class="btn compact" href="{% url \'invoice-detail\' inv.id %}">Chi '
                                 'tiết</a></td>\n'
                                 '        </tr>\n'
                                 '        {% empty %}\n'
                                 '        <tr><td colspan="8">Chưa có hóa đơn nào cho hợp đồng này.</td></tr>\n'
                                 '        {% endfor %}\n'
                                 '      </tbody>\n'
                                 '    </table>\n'
                                 '  </div>\n'
                                 '</section>\n'
                                 '{% endblock %}\n',
 'rentals/contract_list.html': '{% extends "base.html" %}\n'
                               '{% block page_title %}Hợp đồng{% endblock %}\n'
                               '{% block content %}\n'
                               '<div class="page-actions room-toolbar">\n'
                               '  <form method="get" class="room-filters">\n'
                               '    <input name="q" value="{{ q }}" placeholder="Tìm mã hợp đồng, tên khách thuê...">\n'
                               '    <select name="building">\n'
                               '      <option value="">Tất cả tòa nhà</option>\n'
                               '      {% for building in buildings %}<option value="{{ building.id }}" {% if '
                               "selected_building == building.id|stringformat:'s' %}selected{% endif %}>{{ "
                               'building.name }}</option>{% endfor %}\n'
                               '    </select>\n'
                               '    <select name="status">\n'
                               '      <option value="">Tất cả trạng thái</option>\n'
                               '      {% for code, label in status_choices %}<option value="{{ code }}" {% if status '
                               '== code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                               '    </select>\n'
                               '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                               '    {% if q or status or selected_building %}<a class="btn" href="{% url \'contracts\' '
                               '%}">Xóa lọc</a>{% endif %}\n'
                               '  </form>\n'
                               '  <a class="btn primary" href="{% url \'contract-create\' %}">Thêm hợp đồng</a>\n'
                               '</div>\n'
                               '<section class="panel">\n'
                               '  <div class="list-summary"><span>Danh sách hợp đồng</span><span>Tổng số: <strong>{{ '
                               'paginator.count }}</strong></span></div>\n'
                               '  <div class="table-wrap">\n'
                               '    <table>\n'
                               '      <thead>\n'
                               '        <tr>\n'
                               '          <th class="row-number">STT</th>\n'
                               '          <th>Mã</th>\n'
                               '          <th>Phòng</th>\n'
                               '          <th>Đại diện</th>\n'
                               '          <th>Thời hạn</th>\n'
                               '          <th>Giá thuê</th>\n'
                               '          <th>Trạng thái</th>\n'
                               '          <th>Thao tác</th>\n'
                               '        </tr>\n'
                               '      </thead>\n'
                               '      <tbody>\n'
                               '        {% for x in objects %}\n'
                               '        <tr>\n'
                               '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                               '          <td><a href="{% url \'contract-detail\' x.id %}" '
                               'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ x.code '
                               '}}</a></td>\n'
                               '          <td>{{ x.room }}</td>\n'
                               '          <td><a href="{% url \'tenant-detail\' x.representative.id %}" '
                               'style="color:inherit;text-decoration:none;">{{ x.representative }}</a></td>\n'
                               '          <td>{{ x.start_date|date:"d/m/Y" }} – {{ x.end_date|date:"d/m/Y" }}</td>\n'
                               '          <td>{{ x.monthly_rent|vnd }} đ</td>\n'
                               '          <td><span class="badge">{{ x.get_status_display }}</span></td>\n'
                               '          <td>\n'
                               '            <div style="display:flex;gap:6px;">\n'
                               '              <a class="btn compact" href="{% url \'contract-detail\' x.id %}">Chi '
                               'tiết</a>\n'
                               "              {% if x.status == 'draft' %}\n"
                               '              <a class="btn compact" href="{% url \'contract-update\' x.id '
                               '%}">Sửa</a>\n'
                               '              {% endif %}\n'
                               '            </div>\n'
                               '          </td>\n'
                               '        </tr>\n'
                               '        {% empty %}\n'
                               '        <tr><td colspan="8">Chưa có dữ liệu hợp đồng phù hợp.</td></tr>\n'
                               '        {% endfor %}\n'
                               '      </tbody>\n'
                               '    </table>\n'
                               '  </div>\n'
                               '</section>\n'
                               '{% if page_obj.has_other_pages %}\n'
                               '<nav class="pagination" aria-label="Phân trang hợp đồng">\n'
                               '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number '
                               '}}&q={{ q|urlencode }}&building={{ selected_building }}&status={{ status }}">← '
                               'Trước</a>{% else %}<span class="disabled">← Trước</span>{% endif %}\n'
                               '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                               '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                               "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                               'href="?page={{ page_number }}&q={{ q|urlencode }}&building={{ selected_building '
                               '}}&status={{ status }}">{{ page_number }}</a>{% endif %}{% endfor %}\n'
                               '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                               'q|urlencode }}&building={{ selected_building }}&status={{ status }}">Sau →</a>{% else '
                               '%}<span class="disabled">Sau →</span>{% endif %}\n'
                               '</nav>\n'
                               '{% endif %}\n'
                               '{% endblock %}\n',
 'rentals/dashboard.html': '{% extends "base.html" %}\n'
                           '{% load l10n %}\n'
                           '{% block title %}Tổng quan{% endblock %}\n'
                           '{% block page_title %}Tổng quan{% endblock %}\n'
                           '{% block content %}\n'
                           '<div class="admin-dashboard">\n'
                           '<section class="stats-grid dashboard-stats-grid" aria-label="Tình hình phòng cho thuê">\n'
                           '  <article class="stat"><span>Tổng số phòng</span><strong>{{ room_count '
                           '}}</strong></article>\n'
                           '  <article class="stat"><span>Phòng trống</span><strong>{{ available_count '
                           '}}</strong></article>\n'
                           '  <article class="stat"><span>Đang thuê</span><strong>{{ occupied_count '
                           '}}</strong></article>\n'
                           '  <article class="stat"><span>Hợp đồng hiệu lực</span><strong>{{ active_contract_count '
                           '}}</strong></article>\n'
                           '  <article class="stat stat-money"><span>Tổng công nợ</span><strong>{{ unpaid_total|vnd }} '
                           'đ</strong></article>\n'
                           '  <article class="stat"><span>Sự cố cần xử lý</span><strong>{{ open_incident_count '
                           '}}</strong></article>\n'
                           '</section>\n'
                           '<section class="monthly-chart-panel panel" aria-labelledby="monthly-chart-title">\n'
                           '  <div class="panel-heading">\n'
                           '    <div>\n'
                           '      <h2 id="monthly-chart-title">Tình hình theo tháng</h2>\n'
                           '      <p class="chart-description">Hóa đơn phát hành và tiền đã thu trong 6 tháng gần '
                           'nhất</p>\n'
                           '    </div>\n'
                           '    <div class="chart-legend" aria-label="Chú thích biểu đồ">\n'
                           '      <span><i class="chart-dot billed" aria-hidden="true"></i>Hóa đơn</span>\n'
                           '      <span><i class="chart-dot collected" aria-hidden="true"></i>Đã thu</span>\n'
                           '    </div>\n'
                           '  </div>\n'
                           '  <div class="monthly-chart-scroll" tabindex="0" role="region" aria-label="Biểu đồ và số '
                           'liệu sáu tháng gần nhất">\n'
                           '  <div class="monthly-chart">\n'
                           '    {% for month in monthly_data %}\n'
                           '    <article class="chart-month" aria-labelledby="chart-month-{{ forloop.counter }}">\n'
                           '      <div class="chart-values" aria-hidden="true">\n'
                           '        <div class="chart-series">\n'
                           '          <span class="chart-bar billed" data-percent="{{ month.invoice_percent|unlocalize '
                           '}}" style="height: {{ month.invoice_percent|unlocalize }}%" title="{{ month.label }}: Hóa '
                           'đơn {{ month.invoice_total|vnd }} đ"></span>\n'
                           '          <span class="chart-bar collected" data-percent="{{ '
                           'month.payment_percent|unlocalize }}" style="height: {{ month.payment_percent|unlocalize '
                           '}}%" title="{{ month.label }}: Đã thu {{ month.payment_total|vnd }} đ"></span>\n'
                           '        </div>\n'
                           '      </div>\n'
                           '      <h3 class="chart-label" id="chart-month-{{ forloop.counter }}">{{ month.label '
                           '}}</h3>\n'
                           '      <dl class="chart-summary">\n'
                           '        <div><dt>Hóa đơn</dt><dd>{{ month.invoice_total|vnd }} đ</dd></div>\n'
                           '        <div class="chart-collected-value"><dt>Đã thu</dt><dd>{{ month.payment_total|vnd '
                           '}} đ</dd></div>\n'
                           '      </dl>\n'
                           '    </article>\n'
                           '    {% endfor %}\n'
                           '  </div>\n'
                           '  </div>\n'
                           '</section>\n'
                           '<section class="two-columns dashboard-panels">\n'
                           '  <article class="panel">\n'
                           '    <div class="panel-heading">\n'
                           '      <h2>Hóa đơn gần đây</h2>\n'
                           '      <a href="{% url \'invoices\' %}" class="panel-more-link">Xem tất cả <i '
                           'data-lucide="chevron-right"></i></a>\n'
                           '    </div>\n'
                           '    <div class="table-wrap" tabindex="0" role="region" aria-label="Danh sách hóa đơn gần '
                           'đây">\n'
                           '      <table class="dashboard-table">\n'
                           '        <thead>\n'
                           '          <tr>\n'
                           '            <th scope="col">Mã</th>\n'
                           '            <th scope="col">Phòng</th>\n'
                           '            <th scope="col" class="table-align-end">Tổng tiền</th>\n'
                           '            <th scope="col" class="table-align-end">Trạng thái</th>\n'
                           '          </tr>\n'
                           '        </thead>\n'
                           '        <tbody>\n'
                           '          {% for item in recent_invoices %}\n'
                           '          <tr>\n'
                           '            <td>\n'
                           '              <a href="{% url \'invoice-detail\' item.id %}" class="table-code-link" '
                           'title="Xem chi tiết {{ item.code }}">{{ item.code }}</a>\n'
                           '            </td>\n'
                           '            <td>\n'
                           '              <div class="table-room-cell">\n'
                           '                <strong>Phòng {{ item.contract.room.number }}</strong>\n'
                           '                <small>{{ item.contract.room.building.name }}</small>\n'
                           '              </div>\n'
                           '            </td>\n'
                           '            <td class="table-align-end">\n'
                           '              <strong class="table-price-val">{{ item.total_amount|vnd }} đ</strong>\n'
                           '            </td>\n'
                           '            <td class="table-align-end">\n'
                           '              <span class="badge badge-status-{{ item.status }}">{{ '
                           'item.get_status_display }}</span>\n'
                           '            </td>\n'
                           '          </tr>\n'
                           '          {% empty %}\n'
                           '          <tr><td colspan="4" class="table-empty">Chưa có hóa đơn nào</td></tr>\n'
                           '          {% endfor %}\n'
                           '        </tbody>\n'
                           '      </table>\n'
                           '    </div>\n'
                           '  </article>\n'
                           '\n'
                           '  <article class="panel">\n'
                           '    <div class="panel-heading">\n'
                           '      <h2>Hợp đồng sắp hết hạn</h2>\n'
                           '      <a href="{% url \'contracts\' %}" class="panel-more-link">Xem tất cả <i '
                           'data-lucide="chevron-right"></i></a>\n'
                           '    </div>\n'
                           '    <div class="table-wrap" tabindex="0" role="region" aria-label="Danh sách hợp đồng sắp '
                           'hết hạn">\n'
                           '      <table class="dashboard-table">\n'
                           '        <thead>\n'
                           '          <tr>\n'
                           '            <th scope="col">Mã</th>\n'
                           '            <th scope="col">Khách thuê</th>\n'
                           '            <th scope="col" class="table-align-end">Ngày hết hạn</th>\n'
                           '          </tr>\n'
                           '        </thead>\n'
                           '        <tbody>\n'
                           '          {% for item in expiring_contracts %}\n'
                           '          <tr>\n'
                           '            <td>\n'
                           '              <a href="{% url \'contract-detail\' item.id %}" class="table-code-link" '
                           'title="Xem chi tiết {{ item.code }}">{{ item.code }}</a>\n'
                           '            </td>\n'
                           '            <td>\n'
                           '              <div class="table-room-cell">\n'
                           '                <strong>{{ item.representative.full_name }}</strong>\n'
                           '                <small>{{ item.room.building.name }} &bull; P.{{ item.room.number '
                           '}}</small>\n'
                           '              </div>\n'
                           '            </td>\n'
                           '            <td class="table-align-end">\n'
                           '              <span class="table-date-val">{{ item.end_date|date:"d/m/Y" }}</span>\n'
                           '            </td>\n'
                           '          </tr>\n'
                           '          {% empty %}\n'
                           '          <tr><td colspan="3" class="table-empty">Không có hợp đồng sắp hết hạn</td></tr>\n'
                           '          {% endfor %}\n'
                           '        </tbody>\n'
                           '      </table>\n'
                           '    </div>\n'
                           '  </article>\n'
                           '</section>\n'
                           '</div>\n'
                           '{% endblock %}\n',
 'rentals/form.html': '{% extends "base.html" %}\n'
                      '{% block page_title %}{{ title }}{% endblock %}\n'
                      '{% block content %}\n'
                      '<section class="panel form-panel">\n'
                      '  <h1>{{ title }}</h1>\n'
                      '  <form method="post">\n'
                      '    {% csrf_token %}\n'
                      '    {{ form.as_p }}\n'
                      '    <div class="actions">\n'
                      '      <button class="btn primary" type="submit">Lưu dữ liệu</button>\n'
                      '      <button class="btn" type="button" onclick="history.back()">Quay lại</button>\n'
                      '    </div>\n'
                      '  </form>\n'
                      '</section>\n'
                      '<script>\n'
                      '(function(){\n'
                      '  const roomEl = document.getElementById("id_room");\n'
                      '  const typeEl = document.getElementById("id_meter_type");\n'
                      '  const periodEl = document.getElementById("id_period");\n'
                      '  const prevEl = document.getElementById("id_previous_value");\n'
                      '  if (roomEl && typeEl && periodEl && prevEl) {\n'
                      '    const syncPrev = () => {\n'
                      '      if (!roomEl.value || !typeEl.value || !periodEl.value) return;\n'
                      '      '
                      'fetch(`/api/v1/meters/previous/?room=${encodeURIComponent(roomEl.value)}&meter_type=${encodeURIComponent(typeEl.value)}&period=${encodeURIComponent(periodEl.value)}`)\n'
                      '        .then(r => r.ok ? r.json() : null)\n'
                      '        .then(data => { if (data && data.previous_value !== undefined) prevEl.value = '
                      'data.previous_value; })\n'
                      '        .catch(() => {});\n'
                      '    };\n'
                      '    roomEl.addEventListener("change", syncPrev);\n'
                      '    typeEl.addEventListener("change", syncPrev);\n'
                      '    periodEl.addEventListener("change", syncPrev);\n'
                      '  }\n'
                      '})();\n'
                      '</script>\n'
                      '{% endblock %}\n',
 'rentals/incident_detail.html': '{% extends "base.html" %}\n'
                                 '{% block page_title %}Chi tiết sự cố: {{ incident.title }}{% endblock %}\n'
                                 '{% block content %}\n'
                                 '<div class="page-actions">\n'
                                 '  <a class="btn" href="{% url \'incidents\' %}">← Danh sách sự cố</a>\n'
                                 '</div>\n'
                                 '\n'
                                 '<section class="two-columns">\n'
                                 '  <article class="panel">\n'
                                 '    <div class="panel-heading">\n'
                                 '      <h2>Thông tin báo cáo sự cố</h2>\n'
                                 '      <span class="badge">{{ incident.get_status_display }}</span>\n'
                                 '    </div>\n'
                                 '    <div class="detail-grid">\n'
                                 '      <div><span>Tiêu đề</span><strong>{{ incident.title }}</strong></div>\n'
                                 '      <div><span>Phòng / Tòa nhà</span><strong>{{ incident.room }}</strong></div>\n'
                                 '      <div><span>Người báo cáo</span><strong><a href="{% url \'tenant-detail\' '
                                 'incident.reported_by.id %}" style="color:var(--primary);text-decoration:none;">{{ '
                                 'incident.reported_by.full_name }}</a> ({{ incident.reported_by.phone '
                                 '}})</strong></div>\n'
                                 '      <div><span>Mức độ ưu tiên</span><strong>{{ incident.get_priority_display '
                                 '}}</strong></div>\n'
                                 '      <div><span>Người phụ trách</span><strong>{% if incident.assigned_to %}{{ '
                                 'incident.assigned_to.get_full_name|default:incident.assigned_to.username }}{% else '
                                 '%}Chưa phân công{% endif %}</strong></div>\n'
                                 '      <div><span>Thời gian báo</span><strong>{{ incident.created_at|date:"d/m/Y H:i" '
                                 '}}</strong></div>\n'
                                 '      <div><span>Thời gian hoàn thành</span><strong>{% if incident.resolved_at %}{{ '
                                 'incident.resolved_at|date:"d/m/Y H:i" }}{% else %}Chưa hoàn thành{% endif '
                                 '%}</strong></div>\n'
                                 '    </div>\n'
                                 '    <hr style="border:0;border-top:1px solid var(--line);margin:16px 0;">\n'
                                 '    <div>\n'
                                 '      <span class="muted">Mô tả chi tiết từ khách thuê:</span>\n'
                                 '      <p style="margin:6px 0 0;white-space:pre-line;">{{ incident.description '
                                 '}}</p>\n'
                                 '    </div>\n'
                                 '    {% if incident.resolution_notes %}\n'
                                 '    <hr style="border:0;border-top:1px solid var(--line);margin:16px 0;">\n'
                                 '    <div>\n'
                                 '      <span class="muted">Ghi chú quá trình xử lý:</span>\n'
                                 '      <p style="margin:6px 0 0;white-space:pre-line;">{{ incident.resolution_notes '
                                 '}}</p>\n'
                                 '    </div>\n'
                                 '    {% endif %}\n'
                                 '  </article>\n'
                                 '\n'
                                 '  <article class="panel">\n'
                                 '    <h2>Cập nhật xử lý & Phân công</h2>\n'
                                 '    <p class="muted" style="margin-top:0;">Khi chuyển trạng thái sự cố, hệ thống sẽ '
                                 'tự động gửi thông báo cho khách thuê và ghi nhận thời gian hoàn thành.</p>\n'
                                 '    <form method="post">\n'
                                 '      {% csrf_token %}\n'
                                 '      {{ form.as_p }}\n'
                                 '      <div class="actions">\n'
                                 '        <button class="btn primary" type="submit">Lưu cập nhật xử lý</button>\n'
                                 '      </div>\n'
                                 '    </form>\n'
                                 '  </article>\n'
                                 '</section>\n'
                                 '{% endblock %}\n',
 'rentals/incident_list.html': '{% extends "base.html" %}\n'
                               '{% block page_title %}Sự cố{% endblock %}\n'
                               '{% block content %}\n'
                               '<div class="page-actions room-toolbar">\n'
                               '  <form method="get" class="room-filters">\n'
                               '    <input name="q" value="{{ q }}" placeholder="Tìm tiêu đề, phòng, người báo...">\n'
                               '    <select name="building">\n'
                               '      <option value="">Tất cả tòa nhà</option>\n'
                               '      {% for building in buildings %}<option value="{{ building.id }}" {% if '
                               "selected_building == building.id|stringformat:'s' %}selected{% endif %}>{{ "
                               'building.name }}</option>{% endfor %}\n'
                               '    </select>\n'
                               '    <select name="priority">\n'
                               '      <option value="">Mọi mức ưu tiên</option>\n'
                               '      {% for code, label in priority_choices %}<option value="{{ code }}" {% if '
                               'priority == code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                               '    </select>\n'
                               '    <select name="status">\n'
                               '      <option value="">Tất cả trạng thái</option>\n'
                               '      {% for code, label in status_choices %}<option value="{{ code }}" {% if status '
                               '== code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                               '    </select>\n'
                               '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                               '    {% if q or selected_building or priority or status %}<a class="btn" href="{% url '
                               '\'incidents\' %}">Xóa lọc</a>{% endif %}\n'
                               '  </form>\n'
                               '</div>\n'
                               '<section class="panel">\n'
                               '  <div class="list-summary"><span>Danh sách sự cố</span><span>Tổng số: <strong>{{ '
                               'paginator.count }}</strong></span></div>\n'
                               '  <div class="table-wrap">\n'
                               '    <table>\n'
                               '      <thead>\n'
                               '        <tr>\n'
                               '          <th class="row-number">STT</th>\n'
                               '          <th>Tiêu đề</th>\n'
                               '          <th>Phòng</th>\n'
                               '          <th>Người báo</th>\n'
                               '          <th>Ưu tiên</th>\n'
                               '          <th>Người xử lý</th>\n'
                               '          <th>Trạng thái</th>\n'
                               '          <th>Ngày báo</th>\n'
                               '          <th>Thao tác</th>\n'
                               '        </tr>\n'
                               '      </thead>\n'
                               '      <tbody>\n'
                               '        {% for x in objects %}\n'
                               '        <tr>\n'
                               '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                               '          <td><a href="{% url \'incident-detail\' x.id %}" '
                               'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ x.title '
                               '}}</a></td>\n'
                               '          <td>{{ x.room }}</td>\n'
                               '          <td><a href="{% url \'tenant-detail\' x.reported_by.id %}" '
                               'style="color:inherit;text-decoration:none;">{{ x.reported_by }}</a></td>\n'
                               '          <td><span class="badge">{{ x.get_priority_display }}</span></td>\n'
                               '          <td>{% if x.assigned_to %}{{ '
                               'x.assigned_to.get_full_name|default:x.assigned_to.username }}{% else %}<span '
                               'class="muted">Chưa phân công</span>{% endif %}</td>\n'
                               '          <td><span class="badge">{{ x.get_status_display }}</span></td>\n'
                               '          <td>{{ x.created_at|date:"d/m/Y H:i" }}</td>\n'
                               '          <td><a class="btn compact" href="{% url \'incident-detail\' x.id %}">Xử lý / '
                               'Chi tiết</a></td>\n'
                               '        </tr>\n'
                               '        {% empty %}\n'
                               '        <tr><td colspan="9">Chưa có sự cố nào.</td></tr>\n'
                               '        {% endfor %}\n'
                               '      </tbody>\n'
                               '    </table>\n'
                               '  </div>\n'
                               '</section>\n'
                               '{% if page_obj.has_other_pages %}\n'
                               '<nav class="pagination" aria-label="Phân trang sự cố">\n'
                               '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number '
                               '}}&q={{ q|urlencode }}&building={{ selected_building }}&priority={{ priority '
                               '}}&status={{ status }}">← Trước</a>{% else %}<span class="disabled">← Trước</span>{% '
                               'endif %}\n'
                               '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                               '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                               "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                               'href="?page={{ page_number }}&q={{ q|urlencode }}&building={{ selected_building '
                               '}}&priority={{ priority }}&status={{ status }}">{{ page_number }}</a>{% endif %}{% '
                               'endfor %}\n'
                               '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                               'q|urlencode }}&building={{ selected_building }}&priority={{ priority }}&status={{ '
                               'status }}">Sau →</a>{% else %}<span class="disabled">Sau →</span>{% endif %}\n'
                               '</nav>\n'
                               '{% endif %}\n'
                               '{% endblock %}\n',
 'rentals/includes/building_tour_controls.html': '<section id="tour-route" class="tour-route" aria-label="Chỉ đường '
                                                 'tới phòng" hidden>\n'
                                                 '  <div><i data-lucide="navigation"></i><strong '
                                                 'id="route-destination"></strong><button id="route-clear" '
                                                 'type="button" aria-label="Dừng chỉ đường"><i '
                                                 'data-lucide="x"></i></button></div>\n'
                                                 '  <p id="route-instruction" aria-live="polite"></p>\n'
                                                 '</section>\n'
                                                 '<button id="tour-elevator" type="button" class="elevator-action" '
                                                 'hidden><i data-lucide="arrow-up-down"></i><span>Thang máy · Chọn '
                                                 'tầng</span><kbd>F</kbd></button>\n'
                                                 '<div id="tour-transfer" class="tour-transfer" role="status" '
                                                 'aria-live="polite" hidden><i data-lucide="arrow-up-down"></i><strong '
                                                 'id="transfer-label">Đang chuyển tầng</strong><span>Vui lòng chờ '
                                                 'thang máy</span></div>\n'
                                                 '<dialog id="tour-building-dialog" '
                                                 'aria-labelledby="building-map-title" class="tour-dialog '
                                                 'building-dialog">\n'
                                                 '  <div class="dialog-heading"><div><span class="eyebrow">{{ '
                                                 'room.building.name }}</span><h2 id="building-map-title">Sơ đồ di '
                                                 'chuyển trong tòa nhà</h2><p>{{ tour_config.floors|length }} tầng · '
                                                 '{{ tour_rooms|length }} phòng · Bố trí mô phỏng</p></div><button '
                                                 'type="button" data-close-dialog aria-label="Đóng sơ đồ"><i '
                                                 'data-lucide="x"></i></button></div>\n'
                                                 '  <div class="building-map-layout">\n'
                                                 '    <section class="building-section" aria-label="Các tầng và phòng '
                                                 'trong tòa nhà"><div class="building-roof"><i '
                                                 'data-lucide="building-2"></i>{{ room.building.name }}</div><div '
                                                 'id="building-elevation"></div><div class="building-entrance"><i '
                                                 'data-lucide="door-open"></i>Sảnh và thang máy<span '
                                                 'id="building-location"></span></div></section>\n'
                                                 '    <section class="building-selection" aria-label="Phòng đang '
                                                 'chọn"><span class="selection-caption">Chọn phòng để xem đường '
                                                 'đi</span><h3 id="selected-room-title"></h3><span '
                                                 'id="selected-room-status" class="room-availability"></span><div '
                                                 'id="selected-floor-plan" class="selected-floor-plan"></div><p '
                                                 'id="selected-room-model"></p><ol id="selected-room-steps" '
                                                 'class="route-steps"></ol><button id="building-route-start" '
                                                 'type="button" class="route-start">Chỉ đường tới '
                                                 'phòng</button></section>\n'
                                                 '  </div>\n'
                                                 '  <div class="building-legend"><span><i '
                                                 'class="legend-available"></i>Còn trống</span><span><i '
                                                 'class="legend-occupied"></i>Đang thuê / giữ chỗ</span><span><i '
                                                 'class="legend-other"></i>Trạng thái khác</span><span><i '
                                                 'class="legend-route"></i>Phòng đích / hướng đi</span></div>\n'
                                                 '  <p class="building-map-note">Sơ đồ dùng để tham quan. Vị trí, nội '
                                                 'thất và kích thước là mô phỏng; trạng thái phòng lấy từ hệ '
                                                 'thống.</p>\n'
                                                 '</dialog>\n'
                                                 '<dialog id="tour-elevator-dialog" aria-labelledby="elevator-title" '
                                                 'class="tour-dialog elevator-dialog">\n'
                                                 '  <div class="dialog-heading"><div><span class="eyebrow">Thang '
                                                 'máy</span><h2 id="elevator-title">Chọn tầng</h2></div><button '
                                                 'type="button" data-close-dialog aria-label="Đóng thang máy"><i '
                                                 'data-lucide="x"></i></button></div>\n'
                                                 '  <p id="elevator-current"></p><div id="elevator-floors" '
                                                 'class="elevator-floors"></div><p class="elevator-hint">Chọn tầng, ra '
                                                 'khỏi thang máy rồi đi dọc hành lang để vào phòng.</p>\n'
                                                 '</dialog>\n',
 'rentals/indoor_map.html': '{% extends "base.html" %}\n'
                            '{% load static %}\n'
                            '{% block title %}Bản đồ trong nhà{% endblock %}\n'
                            '{% block extra_head %}<link rel="stylesheet" href="{% static \'css/indoor-map.css\' '
                            '%}?v=3">{% endblock %}\n'
                            '{% block page_title %}Bản đồ trong nhà{% endblock %}\n'
                            '{% block page_subtitle %}Khám phá không gian · tìm phòng · chỉ đường trong tầng{% '
                            'endblock %}\n'
                            '{% block content %}\n'
                            '<section class="indoor-workspace">\n'
                            '  <div class="indoor-heading"><a href="{% url \'indoor-map-list\' %}">← Tất cả mặt '
                            'bằng</a><span>{% if scene_data.map.is_demo %}MẶT BẰNG MẪU{% else %}BẢN ĐỒ TƯƠNG TÁC{% '
                            'endif %} · TẦNG {{ indoor_map.floor }}</span></div>\n'
                            '  <div class="indoor-layout">\n'
                            '    <aside class="indoor-directory-panel" aria-label="Tìm kiếm và chỉ đường">\n'
                            '      <div class="indoor-panel-section indoor-location-heading"><i '
                            'data-lucide="building-2"></i><div><h2>{{ indoor_map.building.name }}</h2><p>Tầng {{ '
                            'indoor_map.floor }} · Không gian trong nhà</p></div></div>\n'
                            '      <div class="indoor-panel-section indoor-search-section"><label '
                            'class="indoor-search"><i data-lucide="search"></i><input id="map-search" type="search" '
                            'placeholder="Tìm phòng, lối thoát…" aria-label="Tìm địa điểm" '
                            'autocomplete="off"></label></div>\n'
                            '      <section class="indoor-panel-section indoor-route-section">\n'
                            '        <div class="indoor-section-heading"><h3><i data-lucide="route"></i> Chỉ '
                            'đường</h3><span>Trong tầng</span></div>\n'
                            '        <form method="get" id="map-route-form">\n'
                            '          <label for="start">Điểm bắt đầu</label>\n'
                            '          <select id="start" name="start" required><option value="">Chọn phòng hoặc vị '
                            "trí</option>{% for node in nodes %}{% if node.kind == 'room' or node.kind == 'exit' or "
                            'node.kind == \'stairs\' %}<option value="{{ node.id }}" {% if start_id == '
                            "node.id|stringformat:'s' %}selected{% endif %}>{{ node.label }}</option>{% endif %}{% "
                            'endfor %}</select>\n'
                            '          <label for="end">Điểm đến</label>\n'
                            '          <select id="end" name="end"><option value="">Lối thoát gần nhất</option>{% for '
                            "node in nodes %}{% if node.kind == 'room' or node.kind == 'exit' or node.kind == 'stairs' "
                            '%}<option value="{{ node.id }}" {% if end_id == node.id|stringformat:\'s\' %}selected{% '
                            'endif %}>{{ node.label }}</option>{% endif %}{% endfor %}</select>\n'
                            '          <button type="submit" class="indoor-primary-button"><i '
                            'data-lucide="navigation"></i> Tìm đường</button>\n'
                            '        </form>\n'
                            '        <div id="route-summary" class="indoor-route-summary" hidden '
                            'aria-live="polite"><strong id="route-destination"></strong><span '
                            'id="route-distance"></span><ol id="route-steps"></ol></div>\n'
                            '      </section>\n'
                            '      <section class="indoor-panel-section indoor-rooms-section"><div '
                            'class="indoor-section-heading"><h3>Địa điểm trong tầng</h3><span '
                            'id="map-directory-count"></span></div><div id="map-directory" '
                            'class="indoor-directory"></div><p id="map-directory-empty" hidden>Không tìm thấy địa '
                            'điểm.</p></section>\n'
                            '      <section id="map-selection" class="indoor-panel-section indoor-selection" hidden '
                            'aria-live="polite"></section>\n'
                            '      <details class="indoor-simulation"><summary><i data-lucide="flame"></i> Mô phỏng & '
                            'lớp bản đồ</summary><div class="indoor-simulation-content">\n'
                            '        <p>Chặn một vùng để kiểm tra đường đi thay thế. Đây không phải cảnh báo thực '
                            'tế.</p>\n'
                            '        {% if can_simulate %}{% for zone in zones %}<form method="post" action="{% url '
                            '\'indoor-map-toggle-hazard\' indoor_map.id zone.id %}" data-hazard-form data-zone-id="{{ '
                            'zone.id }}">{% csrf_token %}<input type="hidden" name="start" value="{{ start_id '
                            '}}"><input type="hidden" name="end" value="{{ end_id }}"><span>{{ zone.name '
                            '}}</span><button type="submit">{% if zone.has_simulation %}Bỏ chặn{% else %}Chặn thử{% '
                            'endif %}</button></form>{% endfor %}{% endif %}\n'
                            '        <label class="indoor-graph-toggle"><input id="map-show-graph" type="checkbox"> '
                            'Hiện mạng lưới định tuyến</label>\n'
                            '        <h4>Camera</h4>{% for camera in cameras %}<p>{{ camera.name }}{% if camera.zone '
                            '%} · {{ camera.zone.name }}{% endif %}</p>{% empty %}<p>Chưa gắn camera.</p>{% endfor %}\n'
                            '      </div></details>\n'
                            '      <footer class="indoor-panel-footer">{% if scene_data.map.is_demo %}Mặt bằng và nội '
                            'thất giả định, chưa khảo sát thực tế.{% else %}Kích thước cần được hiệu chuẩn từ mặt bằng '
                            'thực tế.{% endif %}</footer>\n'
                            '    </aside>\n'
                            '    <div class="indoor-map-panel">\n'
                            '      <section class="indoor-map-stage" aria-label="Mặt bằng tương tác">\n'
                            '        <div id="map-canvas-host"><canvas id="indoor-map-3d" aria-label="Mặt bằng 3D. Kéo '
                            'để xoay, cuộn để thu phóng."></canvas><div id="map-labels"></div><div id="map-fallback" '
                            'hidden></div></div>\n'
                            '        <div class="indoor-map-topbar"><nav class="indoor-floor-switcher" '
                            'aria-label="Chọn tầng"><i data-lucide="layers"></i>{% for floor in floor_maps %}<a '
                            'href="{% url \'indoor-map\' floor.id %}" {% if floor.id == indoor_map.id '
                            '%}aria-current="page" class="is-active"{% endif %}>Tầng {{ floor.floor }}</a>{% endfor '
                            '%}</nav><div class="indoor-view-switcher" role="group" aria-label="Chế độ xem"><button '
                            'type="button" data-map-view="3d" class="is-active" aria-pressed="true"><i '
                            'data-lucide="box"></i> 3D</button><button type="button" data-map-view="2d" '
                            'aria-pressed="false"><i data-lucide="map"></i> 2D</button></div></div>\n'
                            '        <div class="indoor-map-navigation" role="group" aria-label="Điều khiển bản đồ">\n'
                            '          <button type="button" data-map-action="reset" title="Góc nhìn ban đầu" '
                            'aria-label="Góc nhìn ban đầu"><i data-lucide="scan"></i></button>\n'
                            '          <button type="button" data-map-action="zoom-in" title="Phóng to" '
                            'aria-label="Phóng to"><i data-lucide="plus"></i></button>\n'
                            '          <button type="button" data-map-action="zoom-out" title="Thu nhỏ" '
                            'aria-label="Thu nhỏ"><i data-lucide="minus"></i></button>\n'
                            '          <button type="button" data-map-action="rotate" title="Xoay góc nhìn" '
                            'aria-label="Xoay góc nhìn"><i data-lucide="rotate-cw"></i></button>\n'
                            '          <button type="button" data-map-action="fullscreen" title="Toàn màn hình" '
                            'aria-label="Toàn màn hình"><i data-lucide="maximize"></i></button>\n'
                            '        </div>\n'
                            '        <div class="indoor-map-legend"><span><i '
                            'class="legend-room"></i>Phòng</span><span><i class="legend-exit"></i>Lối '
                            'thoát</span><span><i class="legend-route"></i>Đường đi</span><span><i '
                            'class="legend-hazard"></i>Vùng chặn</span></div>\n'
                            '        <div class="indoor-map-gesture-hint">Kéo để xoay · Cuộn để thu phóng · Chuột phải '
                            'để di chuyển</div>\n'
                            '      </section>\n'
                            '      <footer class="indoor-map-statusbar"><div id="map-status" role="status" '
                            'aria-live="polite">Đang dựng mặt bằng…</div><span>INDOOR EXPLORER</span></footer>\n'
                            '    </div>\n'
                            '  </div>\n'
                            '  <p class="indoor-disclaimer">Bản đồ phục vụ mô phỏng đồ án; không thay thế mặt bằng '
                            'khảo sát hoặc phương án thoát nạn được phê duyệt. Chỉ đường hiện hỗ trợ trong cùng một '
                            'tầng.</p>\n'
                            '  <noscript>Hãy bật JavaScript để sử dụng bản đồ tương tác.</noscript>\n'
                            '</section>\n'
                            "{{ scene_data|json_script:'indoor-scene-data' }}\n"
                            '<script type="importmap">{"imports":{"three":"{% static \'vendor/three/three.module.js\' '
                            '%}"}}</script>\n'
                            '<script type="module" src="{% static \'js/indoor-map-3d.js\' %}?v=3"></script>\n'
                            '{% endblock %}\n',
 'rentals/indoor_map_list.html': '{% extends "base.html" %}\n'
                                 '{% block title %}Bản đồ trong nhà{% endblock %}\n'
                                 '{% block page_title %}Bản đồ trong nhà{% endblock %}\n'
                                 '{% block page_subtitle %}Chọn tòa nhà và tầng để xem sơ đồ, lối đi và tuyến thoát mô '
                                 'phỏng{% endblock %}\n'
                                 '{% block content %}\n'
                                 '<div class="panel" style="padding:24px">\n'
                                 '  {% for indoor in maps %}\n'
                                 '    <a href="{% url \'indoor-map\' indoor.id %}" '
                                 'style="display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px '
                                 '4px;border-bottom:1px solid #e2e8f0;text-decoration:none;color:inherit">\n'
                                 '      <span><strong>{{ indoor.building.name }}</strong><br><small>Tầng {{ '
                                 'indoor.floor }} · {{ indoor.name }}</small></span>\n'
                                 '      <span>Xem bản đồ →</span>\n'
                                 '    </a>\n'
                                 '  {% empty %}\n'
                                 '    <p>Chưa có bản đồ tầng. Quản trị viên có thể tạo Indoor Map, Map Node và Map '
                                 'Edge trong Django Admin.</p>\n'
                                 '  {% endfor %}\n'
                                 '</div>\n'
                                 '{% endblock %}\n',
 'rentals/invoice_detail.html': '{% extends "base.html" %}\n'
                                '{% block page_title %}Hóa đơn {{ invoice.code }}{% endblock %}\n'
                                '{% block content %}\n'
                                '<div class="page-actions" style="flex-wrap:wrap;gap:10px;">\n'
                                '  <div style="display:flex;gap:8px;align-items:center;">\n'
                                '    <a class="btn" href="{% url \'invoices\' %}">← Danh sách hóa đơn</a>\n'
                                "    {% if invoice.status == 'draft' %}\n"
                                '    <a class="btn" href="{% url \'invoice-update\' invoice.id %}">Sửa hóa đơn '
                                'nháp</a>\n'
                                '    {% endif %}\n'
                                '  </div>\n'
                                '  <div style="display:flex;gap:8px;flex-wrap:wrap;">\n'
                                "    {% if invoice.status == 'draft' %}\n"
                                '    <form method="post" action="{% url \'invoice-issue\' invoice.id %}" '
                                'onsubmit="return confirm(\'Xác nhận phát hành hóa đơn {{ invoice.code }} và gửi thông '
                                'báo cho khách thuê?\');">\n'
                                '      {% csrf_token %}\n'
                                '      <button class="btn primary" type="submit">Phát hành hóa đơn</button>\n'
                                '    </form>\n'
                                '    {% endif %}\n'
                                "    {% if invoice.status != 'draft' and invoice.status != 'cancelled' and "
                                "invoice.status != 'paid' %}\n"
                                '    <a class="btn primary" href="{% url \'payment-create\' %}?invoice={{ invoice.id '
                                '}}">Ghi nhận thanh toán</a>\n'
                                '    {% endif %}\n'
                                '  </div>\n'
                                '</div>\n'
                                '\n'
                                '<section class="two-columns" style="margin-bottom:20px;">\n'
                                '  <article class="panel">\n'
                                '    <div class="panel-heading">\n'
                                '      <h2>Thông tin hóa đơn</h2>\n'
                                '      <span class="badge">{{ invoice.get_status_display }}</span>\n'
                                '    </div>\n'
                                '    <div class="detail-grid">\n'
                                '      <div><span>Mã hóa đơn</span><strong>{{ invoice.code }}</strong></div>\n'
                                '      <div><span>Hợp đồng</span><strong><a href="{% url \'contract-detail\' '
                                'invoice.contract.id %}" style="color:var(--primary);text-decoration:none;">{{ '
                                'invoice.contract.code }}</a></strong></div>\n'
                                '      <div><span>Phòng / Tòa nhà</span><strong>{{ invoice.contract.room '
                                '}}</strong></div>\n'
                                '      <div><span>Khách đại diện</span><strong><a href="{% url \'tenant-detail\' '
                                'invoice.contract.representative.id %}" '
                                'style="color:var(--primary);text-decoration:none;">{{ '
                                'invoice.contract.representative.full_name }}</a></strong></div>\n'
                                '      <div><span>Kỳ hóa đơn</span><strong>{{ invoice.period|date:"m/Y" '
                                '}}</strong></div>\n'
                                '      <div><span>Ngày phát hành</span><strong>{{ invoice.issued_date|date:"d/m/Y" '
                                '}}</strong></div>\n'
                                '      <div><span>Hạn thanh toán</span><strong>{{ invoice.due_date|date:"d/m/Y" '
                                '}}</strong></div>\n'
                                '      <div><span>Tiền trước giảm trừ</span><strong>{{ invoice.subtotal|vnd }} '
                                'đ</strong></div>\n'
                                '      <div><span>Giảm trừ</span><strong>{{ invoice.discount|vnd }} đ</strong></div>\n'
                                '      <div><span>Tổng cộng</span><strong style="color:var(--primary);">{{ '
                                'invoice.total_amount|vnd }} đ</strong></div>\n'
                                '      <div><span>Đã thanh toán</span><strong style="color:var(--green);">{{ '
                                'invoice.paid_amount|vnd }} đ</strong></div>\n'
                                '      <div><span>Số còn nợ</span><strong style="color:var(--red);">{{ '
                                'invoice.balance|vnd }} đ</strong></div>\n'
                                '    </div>\n'
                                '    {% if invoice.notes %}\n'
                                '    <hr style="border:0;border-top:1px solid var(--line);margin:16px 0;">\n'
                                '    <div>\n'
                                '      <span class="muted">Ghi chú / Lý do:</span>\n'
                                '      <p style="margin:6px 0 0;white-space:pre-line;">{{ invoice.notes }}</p>\n'
                                '    </div>\n'
                                '    {% endif %}\n'
                                '  </article>\n'
                                '\n'
                                '  <article class="panel">\n'
                                "    {% if invoice.status == 'draft' %}\n"
                                '    <h2>Chỉnh sửa nhanh hóa đơn nháp</h2>\n'
                                '    <form method="post" action="{% url \'invoice-update\' invoice.id %}">\n'
                                '      {% csrf_token %}\n'
                                '      {{ draft_form.as_p }}\n'
                                '      <div class="actions">\n'
                                '        <button class="btn primary" type="submit">Cập nhật bản nháp</button>\n'
                                '      </div>\n'
                                '    </form>\n'
                                '    <hr style="border:0;border-top:1px solid var(--line);margin:18px 0;">\n'
                                '    {% endif %}\n'
                                "    {% if invoice.status != 'cancelled' and invoice.paid_amount == 0 %}\n"
                                '    <h2>Hủy hóa đơn</h2>\n'
                                '    <p class="muted" style="margin-top:0;">Chỉ hủy được hóa đơn chưa phát sinh giao '
                                'dịch thanh toán hợp lệ. Vui lòng nhập rõ lý do hủy.</p>\n'
                                '    <form method="post" action="{% url \'invoice-cancel\' invoice.id %}" '
                                'onsubmit="return confirm(\'Bạn có chắc chắn muốn hủy hóa đơn {{ invoice.code '
                                '}}?\');">\n'
                                '      {% csrf_token %}\n'
                                '      {{ cancel_form.as_p }}\n'
                                '      <div class="actions">\n'
                                '        <button class="btn" type="submit" '
                                'style="color:var(--red);border-color:var(--red);">Xác nhận hủy hóa đơn</button>\n'
                                '      </div>\n'
                                '    </form>\n'
                                '    {% else %}\n'
                                '    <h2>Trạng thái hóa đơn</h2>\n'
                                '    <p class="muted">Hóa đơn hiện đang ở trạng thái <strong>{{ '
                                'invoice.get_status_display }}</strong>.</p>\n'
                                '    {% endif %}\n'
                                '  </article>\n'
                                '</section>\n'
                                '\n'
                                '<section class="panel" style="margin-bottom:20px;">\n'
                                '  <div class="panel-heading">\n'
                                '    <h2>Chi tiết các khoản thu ({{ invoice.items.count }})</h2>\n'
                                '  </div>\n'
                                '  <div class="table-wrap">\n'
                                '    <table>\n'
                                '      <thead>\n'
                                '        <tr>\n'
                                '          <th>Nội dung</th>\n'
                                '          <th>Dịch vụ</th>\n'
                                '          <th>Số lượng</th>\n'
                                '          <th>Đơn giá chốt</th>\n'
                                '          <th>Thành tiền</th>\n'
                                "          {% if invoice.status == 'draft' %}<th>Thao tác</th>{% endif %}\n"
                                '        </tr>\n'
                                '      </thead>\n'
                                '      <tbody>\n'
                                '        {% for item in invoice.items.all %}\n'
                                '        <tr>\n'
                                '          <td>{{ item.description }}</td>\n'
                                '          <td>{% if item.service %}{{ item.service.name }}{% else %}—{% endif '
                                '%}</td>\n'
                                '          <td>{{ item.quantity }}</td>\n'
                                '          <td>{{ item.unit_price|vnd }} đ</td>\n'
                                '          <td><strong>{{ item.amount|vnd }} đ</strong></td>\n'
                                "          {% if invoice.status == 'draft' %}\n"
                                '          <td>\n'
                                '            <form method="post" action="{% url \'invoice-item-remove\' invoice.id '
                                'item.id %}" onsubmit="return confirm(\'Xóa khoản thu {{ item.description }}?\');" '
                                'style="display:inline;">\n'
                                '              {% csrf_token %}\n'
                                '              <button class="btn compact" type="submit" '
                                'style="color:var(--red);">Xóa</button>\n'
                                '            </form>\n'
                                '          </td>\n'
                                '          {% endif %}\n'
                                '        </tr>\n'
                                '        {% empty %}\n'
                                '        <tr><td colspan="6">Chưa có dòng chi tiết nào.</td></tr>\n'
                                '        {% endfor %}\n'
                                '      </tbody>\n'
                                '      <tfoot>\n'
                                '        <tr><th colspan="4">Tiền trước điều chỉnh (Subtotal)</th><th colspan="2">{{ '
                                'invoice.subtotal|vnd }} đ</th></tr>\n'
                                '        <tr><th colspan="4">Giảm trừ (Discount)</th><th colspan="2">- {{ '
                                'invoice.discount|vnd }} đ</th></tr>\n'
                                '        <tr><th colspan="4">Tổng cộng phải thu</th><th colspan="2">{{ '
                                'invoice.total_amount|vnd }} đ</th></tr>\n'
                                '      </tfoot>\n'
                                '    </table>\n'
                                '  </div>\n'
                                '\n'
                                "  {% if invoice.status == 'draft' %}\n"
                                '  <hr style="border:0;border-top:1px solid var(--line);margin:18px 0;">\n'
                                '  <h2>Thêm khoản thu / phụ thu vào hóa đơn nháp</h2>\n'
                                '  <form method="post" action="{% url \'invoice-item-add\' invoice.id %}">\n'
                                '    {% csrf_token %}\n'
                                '    <div '
                                'style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;align-items:end;">\n'
                                '      <div><label>Dịch vụ</label>{{ item_form.service }}</div>\n'
                                '      <div><label>Nội dung khoản thu</label>{{ item_form.description }}</div>\n'
                                '      <div><label>Số lượng</label>{{ item_form.quantity }}</div>\n'
                                '      <div><label>Đơn giá</label>{{ item_form.unit_price }}</div>\n'
                                '      <div><button class="btn primary" type="submit">Thêm khoản thu</button></div>\n'
                                '    </div>\n'
                                '  </form>\n'
                                '  {% endif %}\n'
                                '</section>\n'
                                '\n'
                                '<section class="panel">\n'
                                '  <div class="panel-heading">\n'
                                '    <h2>Lịch sử giao dịch thanh toán ({{ invoice.payments.count }})</h2>\n'
                                "    {% if invoice.status != 'draft' and invoice.status != 'cancelled' and "
                                "invoice.status != 'paid' %}\n"
                                '    <a class="btn primary compact" href="{% url \'payment-create\' %}?invoice={{ '
                                'invoice.id }}">+ Ghi nhận thanh toán</a>\n'
                                '    {% endif %}\n'
                                '  </div>\n'
                                '  <div class="table-wrap">\n'
                                '    <table>\n'
                                '      <thead>\n'
                                '        <tr>\n'
                                '          <th>Thời gian</th>\n'
                                '          <th>Số tiền</th>\n'
                                '          <th>Phương thức</th>\n'
                                '          <th>Mã tham chiếu</th>\n'
                                '          <th>Người thu</th>\n'
                                '          <th>Ghi chú</th>\n'
                                '          <th>Trạng thái</th>\n'
                                '          <th>Thao tác</th>\n'
                                '        </tr>\n'
                                '      </thead>\n'
                                '      <tbody>\n'
                                '        {% for p in invoice.payments.all %}\n'
                                '        <tr>\n'
                                '          <td>{{ p.paid_at|date:"d/m/Y H:i" }}</td>\n'
                                '          <td><strong>{{ p.amount|vnd }} đ</strong></td>\n'
                                '          <td>{{ p.get_method_display }}</td>\n'
                                '          <td>{{ p.reference|default:"—" }}</td>\n'
                                '          <td>{{ p.received_by.username }}</td>\n'
                                '          <td>{{ p.notes|default:"—" }}</td>\n'
                                '          <td>\n'
                                '            {% if p.is_void %}\n'
                                '            <span class="badge" style="background:#ffebed;color:#ca3944;">Đã '
                                'hủy</span>\n'
                                '            {% else %}\n'
                                '            <span class="badge">Hợp lệ</span>\n'
                                '            {% endif %}\n'
                                '          </td>\n'
                                '          <td>\n'
                                '            {% if not p.is_void %}\n'
                                '            <form method="post" action="{% url \'payment-void\' p.id %}" '
                                'onsubmit="return confirm(\'Xác nhận hủy giao dịch thanh toán {{ p.amount|vnd }} đ? Hệ '
                                'thống sẽ tính lại công nợ hóa đơn.\');" style="display:inline;">\n'
                                '              {% csrf_token %}\n'
                                '              <input type="hidden" name="reason" value="Hủy giao dịch sai sót">\n'
                                '              <button class="btn compact" type="submit" style="color:var(--red);">Hủy '
                                'giao dịch</button>\n'
                                '            </form>\n'
                                '            {% else %}\n'
                                '            <span class="muted">—</span>\n'
                                '            {% endif %}\n'
                                '          </td>\n'
                                '        </tr>\n'
                                '        {% empty %}\n'
                                '        <tr><td colspan="8">Chưa có giao dịch thanh toán nào.</td></tr>\n'
                                '        {% endfor %}\n'
                                '      </tbody>\n'
                                '    </table>\n'
                                '  </div>\n'
                                '</section>\n'
                                '{% endblock %}\n',
 'rentals/invoice_form.html': '{% extends "base.html" %}\n'
                              '{% block page_title %}{{ title }}{% endblock %}\n'
                              '{% block content %}\n'
                              '<section class="panel form-panel">\n'
                              '  <h1>{{ title }}</h1>\n'
                              '  <p class="muted" style="margin-top:0;">Hệ thống tự động tính tiền phòng, tiền điện '
                              '(kWh), tiền nước (m³), dịch vụ theo người/phòng/cố định, phụ thu và giảm trừ. Đơn giá '
                              'dịch vụ được chốt cố định tại thời điểm tạo hóa đơn.</p>\n'
                              '  <form method="post">\n'
                              '    {% csrf_token %}\n'
                              '    {{ form.as_p }}\n'
                              '    <div class="actions">\n'
                              '      <button class="btn primary" type="submit">Xác nhận lập hóa đơn</button>\n'
                              '      <a class="btn" href="{% url \'invoices\' %}">Quay lại</a>\n'
                              '    </div>\n'
                              '  </form>\n'
                              '</section>\n'
                              '{% endblock %}\n',
 'rentals/invoice_list.html': '{% extends "base.html" %}\n'
                              '{% block page_title %}Hóa đơn{% endblock %}\n'
                              '{% block content %}\n'
                              '<div class="page-actions room-toolbar">\n'
                              '  <form method="get" class="room-filters">\n'
                              '    <input name="q" value="{{ q }}" placeholder="Tìm mã HĐơn, mã hợp đồng, khách '
                              'thuê...">\n'
                              '    <select name="building">\n'
                              '      <option value="">Tất cả tòa nhà</option>\n'
                              '      {% for building in buildings %}<option value="{{ building.id }}" {% if '
                              "selected_building == building.id|stringformat:'s' %}selected{% endif %}>{{ "
                              'building.name }}</option>{% endfor %}\n'
                              '    </select>\n'
                              '    <select name="status">\n'
                              '      <option value="">Tất cả trạng thái</option>\n'
                              '      {% for code, label in status_choices %}<option value="{{ code }}" {% if status == '
                              'code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                              '    </select>\n'
                              '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                              '    {% if q or selected_building or status %}<a class="btn" href="{% url \'invoices\' '
                              '%}">Xóa lọc</a>{% endif %}\n'
                              '  </form>\n'
                              '  <div style="display:flex;gap:8px;flex-wrap:wrap;">\n'
                              '    <a class="btn primary" href="{% url \'invoice-create\' %}">+ Tạo hóa đơn</a>\n'
                              '    <a class="btn" href="{% url \'invoice-bulk-create\' %}">Lập hóa đơn hàng loạt</a>\n'
                              '  </div>\n'
                              '</div>\n'
                              '<section class="panel">\n'
                              '  <div class="list-summary"><span>Danh sách hóa đơn</span><span>Tổng số: <strong>{{ '
                              'paginator.count }}</strong></span></div>\n'
                              '  <div class="table-wrap">\n'
                              '    <table>\n'
                              '      <thead>\n'
                              '        <tr>\n'
                              '          <th class="row-number">STT</th>\n'
                              '          <th>Mã hóa đơn</th>\n'
                              '          <th>Hợp đồng / Phòng</th>\n'
                              '          <th>Kỳ</th>\n'
                              '          <th>Tổng tiền</th>\n'
                              '          <th>Đã trả</th>\n'
                              '          <th>Còn nợ</th>\n'
                              '          <th>Hạn trả</th>\n'
                              '          <th>Trạng thái</th>\n'
                              '          <th>Thao tác</th>\n'
                              '        </tr>\n'
                              '      </thead>\n'
                              '      <tbody>\n'
                              '        {% for x in objects %}\n'
                              '        <tr>\n'
                              '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                              '          <td><a href="{% url \'invoice-detail\' x.id %}" '
                              'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ x.code '
                              '}}</a></td>\n'
                              '          <td>\n'
                              '            <a href="{% url \'contract-detail\' x.contract.id %}" '
                              'style="color:inherit;text-decoration:none;">{{ x.contract.code }}</a>\n'
                              '            <small class="muted" style="display:block;">{{ x.contract.room }} · {{ '
                              'x.contract.representative.full_name }}</small>\n'
                              '          </td>\n'
                              '          <td>{{ x.period|date:"m/Y" }}</td>\n'
                              '          <td>{{ x.total_amount|vnd }} đ</td>\n'
                              '          <td>{{ x.paid_amount|vnd }} đ</td>\n'
                              '          <td><strong>{{ x.balance|vnd }} đ</strong></td>\n'
                              '          <td>{{ x.due_date|date:"d/m/Y" }}</td>\n'
                              '          <td><span class="badge">{{ x.get_status_display }}</span></td>\n'
                              '          <td>\n'
                              '            <div style="display:flex;gap:6px;">\n'
                              '              <a class="btn compact" href="{% url \'invoice-detail\' x.id %}">Chi '
                              'tiết</a>\n'
                              "              {% if x.status != 'draft' and x.status != 'cancelled' and x.status != "
                              "'paid' %}\n"
                              '              <a class="btn primary compact" href="{% url \'payment-create\' '
                              '%}?invoice={{ x.id }}">Thu tiền</a>\n'
                              '              {% endif %}\n'
                              '            </div>\n'
                              '          </td>\n'
                              '        </tr>\n'
                              '        {% empty %}\n'
                              '        <tr><td colspan="10">Chưa có dữ liệu hóa đơn.</td></tr>\n'
                              '        {% endfor %}\n'
                              '      </tbody>\n'
                              '    </table>\n'
                              '  </div>\n'
                              '</section>\n'
                              '{% if page_obj.has_other_pages %}\n'
                              '<nav class="pagination" aria-label="Phân trang hóa đơn">\n'
                              '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}&q={{ '
                              'q|urlencode }}&building={{ selected_building }}&status={{ status }}">← Trước</a>{% else '
                              '%}<span class="disabled">← Trước</span>{% endif %}\n'
                              '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                              '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                              "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                              'href="?page={{ page_number }}&q={{ q|urlencode }}&building={{ selected_building '
                              '}}&status={{ status }}">{{ page_number }}</a>{% endif %}{% endfor %}\n'
                              '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                              'q|urlencode }}&building={{ selected_building }}&status={{ status }}">Sau →</a>{% else '
                              '%}<span class="disabled">Sau →</span>{% endif %}\n'
                              '</nav>\n'
                              '{% endif %}\n'
                              '{% endblock %}\n',
 'rentals/meter_list.html': '{% extends "base.html" %}\n'
                            '{% block page_title %}Chỉ số điện nước{% endblock %}\n'
                            '{% block content %}\n'
                            '<div class="page-actions room-toolbar">\n'
                            '  <form method="get" class="room-filters">\n'
                            '    <input name="q" value="{{ q }}" placeholder="Tìm phòng hoặc tòa nhà...">\n'
                            '    <select name="building">\n'
                            '      <option value="">Tất cả tòa nhà</option>\n'
                            '      {% for building in buildings %}<option value="{{ building.id }}" {% if '
                            "selected_building == building.id|stringformat:'s' %}selected{% endif %}>{{ building.name "
                            '}}</option>{% endfor %}\n'
                            '    </select>\n'
                            '    <select name="meter_type">\n'
                            '      <option value="">Tất cả đồng hồ</option>\n'
                            '      {% for code, label in meter_type_choices %}<option value="{{ code }}" {% if '
                            'meter_type == code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                            '    </select>\n'
                            '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                            '    {% if q or selected_building or meter_type %}<a class="btn" href="{% url \'meters\' '
                            '%}">Xóa lọc</a>{% endif %}\n'
                            '  </form>\n'
                            '  <a class="btn primary" href="{% url \'meter-create\' %}">Ghi chỉ số mới</a>\n'
                            '</div>\n'
                            '<section class="panel">\n'
                            '  <div class="list-summary"><span>Danh sách chỉ số điện nước</span><span>Tổng số: '
                            '<strong>{{ paginator.count }}</strong></span></div>\n'
                            '  <div class="table-wrap">\n'
                            '    <table>\n'
                            '      <thead>\n'
                            '        <tr>\n'
                            '          <th class="row-number">STT</th>\n'
                            '          <th>Phòng</th>\n'
                            '          <th>Loại đồng hồ</th>\n'
                            '          <th>Kỳ</th>\n'
                            '          <th>Chỉ số đầu</th>\n'
                            '          <th>Chỉ số cuối</th>\n'
                            '          <th>Tiêu thụ</th>\n'
                            '          <th>Thao tác</th>\n'
                            '        </tr>\n'
                            '      </thead>\n'
                            '      <tbody>\n'
                            '        {% for x in objects %}\n'
                            '        <tr>\n'
                            '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                            '          <td>{{ x.room }}</td>\n'
                            '          <td><span class="badge">{{ x.get_meter_type_display }}</span></td>\n'
                            '          <td>{{ x.period|date:"m/Y" }}</td>\n'
                            '          <td>{{ x.previous_value }}</td>\n'
                            '          <td>{{ x.current_value }}</td>\n'
                            '          <td><strong>{{ x.consumption }}</strong></td>\n'
                            '          <td><a class="btn compact" href="{% url \'meter-update\' x.id %}">Sửa</a></td>\n'
                            '        </tr>\n'
                            '        {% empty %}\n'
                            '        <tr><td colspan="8">Chưa có dữ liệu chỉ số điện nước.</td></tr>\n'
                            '        {% endfor %}\n'
                            '      </tbody>\n'
                            '    </table>\n'
                            '  </div>\n'
                            '</section>\n'
                            '{% if page_obj.has_other_pages %}\n'
                            '<nav class="pagination" aria-label="Phân trang chỉ số">\n'
                            '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}&q={{ '
                            'q|urlencode }}&building={{ selected_building }}&meter_type={{ meter_type }}">← '
                            'Trước</a>{% else %}<span class="disabled">← Trước</span>{% endif %}\n'
                            '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                            '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                            "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                            'href="?page={{ page_number }}&q={{ q|urlencode }}&building={{ selected_building '
                            '}}&meter_type={{ meter_type }}">{{ page_number }}</a>{% endif %}{% endfor %}\n'
                            '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                            'q|urlencode }}&building={{ selected_building }}&meter_type={{ meter_type }}">Sau →</a>{% '
                            'else %}<span class="disabled">Sau →</span>{% endif %}\n'
                            '</nav>\n'
                            '{% endif %}\n'
                            '{% endblock %}\n',
 'rentals/notification_list.html': '{% extends "base.html" %}\n'
                                   '{% block page_title %}Thông báo{% endblock %}\n'
                                   '{% block content %}\n'
                                   '<div class="page-actions room-toolbar">\n'
                                   '  <form method="get" class="room-filters">\n'
                                   '    <input name="q" value="{{ q }}" placeholder="Tìm tiêu đề, nội dung, người '
                                   'nhận...">\n'
                                   '    <select name="building">\n'
                                   '      <option value="">Tất cả tòa nhà</option>\n'
                                   '      {% for building in buildings %}<option value="{{ building.id }}" {% if '
                                   "selected_building == building.id|stringformat:'s' %}selected{% endif %}>{{ "
                                   'building.name }}</option>{% endfor %}\n'
                                   '    </select>\n'
                                   '    <select name="read">\n'
                                   '      <option value="">Tất cả trạng thái</option>\n'
                                   '      <option value="unread" {% if read_filter == \'unread\' %}selected{% endif '
                                   '%}>Chưa đọc</option>\n'
                                   '      <option value="read" {% if read_filter == \'read\' %}selected{% endif %}>Đã '
                                   'đọc</option>\n'
                                   '    </select>\n'
                                   '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                                   '    {% if q or selected_building or read_filter %}<a class="btn" href="{% url '
                                   '\'notifications\' %}">Xóa lọc</a>{% endif %}\n'
                                   '  </form>\n'
                                   '  <div style="display:flex;gap:8px;flex-wrap:wrap;">\n'
                                   '    <a class="btn primary" href="{% url \'notification-create\' %}">+ Gửi thông '
                                   'báo</a>\n'
                                   '    <form method="post" action="{% url \'notification-expiring-contracts\' %}" '
                                   'onsubmit="return confirm(\'Gửi thông báo nhắc nhở cho các hợp đồng sắp hết hạn '
                                   'trong 30 ngày tới?\');" style="display:inline;">\n'
                                   '      {% csrf_token %}\n'
                                   '      <button class="btn" type="submit">Nhắc HĐ sắp hết hạn</button>\n'
                                   '    </form>\n'
                                   '  </div>\n'
                                   '</div>\n'
                                   '<section class="panel">\n'
                                   '  <div class="list-summary"><span>Danh sách thông báo</span><span>Tổng số: '
                                   '<strong>{{ paginator.count }}</strong></span></div>\n'
                                   '  <div class="table-wrap">\n'
                                   '    <table>\n'
                                   '      <thead>\n'
                                   '        <tr>\n'
                                   '          <th class="row-number">STT</th>\n'
                                   '          <th>Tiêu đề & Nội dung</th>\n'
                                   '          <th>Người nhận</th>\n'
                                   '          <th>Tòa nhà</th>\n'
                                   '          <th>Thời gian gửi</th>\n'
                                   '          <th>Trạng thái</th>\n'
                                   '          <th>Thao tác</th>\n'
                                   '        </tr>\n'
                                   '      </thead>\n'
                                   '      <tbody>\n'
                                   '        {% for x in objects %}\n'
                                   '        <tr>\n'
                                   '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 '
                                   '}}</td>\n'
                                   '          <td style="white-space:normal;max-width:420px;">\n'
                                   '            <strong>{{ x.title }}</strong>\n'
                                   '            <div class="muted" style="font-size:13px;margin-top:3px;">{{ x.content '
                                   '}}</div>\n'
                                   '          </td>\n'
                                   '          <td>{{ x.recipient.get_full_name|default:x.recipient.username }}</td>\n'
                                   '          <td>{{ x.building|default:"—" }}</td>\n'
                                   '          <td>{{ x.created_at|date:"d/m/Y H:i" }}</td>\n'
                                   '          <td>\n'
                                   '            {% if x.is_read %}\n'
                                   '            <span class="badge">Đã đọc</span>\n'
                                   '            {% else %}\n'
                                   '            <span class="badge" style="background:#fff2d8;color:#b27400;">Chưa '
                                   'đọc</span>\n'
                                   '            {% endif %}\n'
                                   '          </td>\n'
                                   '          <td>\n'
                                   '            {% if not x.is_read and x.recipient_id == user.id %}\n'
                                   '            <form method="post" action="{% url \'notification-mark-read\' x.id %}" '
                                   'style="display:inline;">\n'
                                   '              {% csrf_token %}\n'
                                   '              <button class="btn compact" type="submit">Đánh dấu đã đọc</button>\n'
                                   '            </form>\n'
                                   '            {% else %}\n'
                                   '            <span class="muted">—</span>\n'
                                   '            {% endif %}\n'
                                   '          </td>\n'
                                   '        </tr>\n'
                                   '        {% empty %}\n'
                                   '        <tr><td colspan="7">Chưa có thông báo nào.</td></tr>\n'
                                   '        {% endfor %}\n'
                                   '      </tbody>\n'
                                   '    </table>\n'
                                   '  </div>\n'
                                   '</section>\n'
                                   '{% if page_obj.has_other_pages %}\n'
                                   '<nav class="pagination" aria-label="Phân trang thông báo">\n'
                                   '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number '
                                   '}}&q={{ q|urlencode }}&building={{ selected_building }}&read={{ read_filter }}">← '
                                   'Trước</a>{% else %}<span class="disabled">← Trước</span>{% endif %}\n'
                                   '  {% for page_number in paginator.page_range %}{% if page_number == '
                                   'page_obj.number %}<span class="current">{{ page_number }}</span>{% elif '
                                   "page_number >= page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' "
                                   '%}<a href="?page={{ page_number }}&q={{ q|urlencode }}&building={{ '
                                   'selected_building }}&read={{ read_filter }}">{{ page_number }}</a>{% endif %}{% '
                                   'endfor %}\n'
                                   '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                                   'q|urlencode }}&building={{ selected_building }}&read={{ read_filter }}">Sau '
                                   '→</a>{% else %}<span class="disabled">Sau →</span>{% endif %}\n'
                                   '</nav>\n'
                                   '{% endif %}\n'
                                   '{% endblock %}\n',
 'rentals/payment_list.html': '{% extends "base.html" %}\n'
                              '{% block page_title %}Thanh toán{% endblock %}\n'
                              '{% block content %}\n'
                              '<div class="page-actions room-toolbar">\n'
                              '  <form method="get" class="room-filters">\n'
                              '    <input name="q" value="{{ q }}" placeholder="Tìm mã hóa đơn, mã tham chiếu...">\n'
                              '    <select name="method">\n'
                              '      <option value="">Tất cả phương thức</option>\n'
                              '      {% for code, label in method_choices %}<option value="{{ code }}" {% if method == '
                              'code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                              '    </select>\n'
                              '    <select name="void">\n'
                              '      <option value="">Tất cả giao dịch</option>\n'
                              '      <option value="valid" {% if void_filter == \'valid\' %}selected{% endif %}>Hợp '
                              'lệ</option>\n'
                              '      <option value="void" {% if void_filter == \'void\' %}selected{% endif %}>Đã '
                              'hủy</option>\n'
                              '    </select>\n'
                              '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                              '    {% if q or method or void_filter %}<a class="btn" href="{% url \'payments\' %}">Xóa '
                              'lọc</a>{% endif %}\n'
                              '  </form>\n'
                              '  <a class="btn primary" href="{% url \'payment-create\' %}">+ Ghi nhận thanh toán</a>\n'
                              '</div>\n'
                              '<section class="panel">\n'
                              '  <div class="list-summary"><span>Danh sách thanh toán</span><span>Tổng số: <strong>{{ '
                              'paginator.count }}</strong></span></div>\n'
                              '  <div class="table-wrap">\n'
                              '    <table>\n'
                              '      <thead>\n'
                              '        <tr>\n'
                              '          <th class="row-number">STT</th>\n'
                              '          <th>Hóa đơn</th>\n'
                              '          <th>Phòng / Tòa nhà</th>\n'
                              '          <th>Số tiền</th>\n'
                              '          <th>Thời gian</th>\n'
                              '          <th>Phương thức</th>\n'
                              '          <th>Tham chiếu</th>\n'
                              '          <th>Trạng thái</th>\n'
                              '          <th>Thao tác</th>\n'
                              '        </tr>\n'
                              '      </thead>\n'
                              '      <tbody>\n'
                              '        {% for x in objects %}\n'
                              '        <tr>\n'
                              '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                              '          <td><a href="{% url \'invoice-detail\' x.invoice.id %}" '
                              'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ x.invoice.code '
                              '}}</a></td>\n'
                              '          <td>{{ x.invoice.contract.room }}</td>\n'
                              '          <td><strong>{{ x.amount|vnd }} đ</strong></td>\n'
                              '          <td>{{ x.paid_at|date:"d/m/Y H:i" }}</td>\n'
                              '          <td>{{ x.get_method_display }}</td>\n'
                              '          <td>{{ x.reference|default:"—" }}</td>\n'
                              '          <td>\n'
                              '            {% if x.is_void %}\n'
                              '            <span class="badge" style="background:#ffebed;color:#ca3944;">Đã '
                              'hủy</span>\n'
                              '            {% else %}\n'
                              '            <span class="badge">Hợp lệ</span>\n'
                              '            {% endif %}\n'
                              '          </td>\n'
                              '          <td>\n'
                              '            <div style="display:flex;gap:6px;">\n'
                              '              <a class="btn compact" href="{% url \'invoice-detail\' x.invoice.id '
                              '%}">Xem HĐơn</a>\n'
                              '              {% if not x.is_void %}\n'
                              '              <form method="post" action="{% url \'payment-void\' x.id %}" '
                              'onsubmit="return confirm(\'Xác nhận hủy giao dịch thanh toán {{ x.amount|vnd }} đ?\');" '
                              'style="display:inline;">\n'
                              '                {% csrf_token %}\n'
                              '                <input type="hidden" name="next" value="payments">\n'
                              '                <input type="hidden" name="reason" value="Hủy giao dịch sai sót">\n'
                              '                <button class="btn compact" type="submit" '
                              'style="color:var(--red);">Hủy</button>\n'
                              '              </form>\n'
                              '              {% endif %}\n'
                              '            </div>\n'
                              '          </td>\n'
                              '        </tr>\n'
                              '        {% empty %}\n'
                              '        <tr><td colspan="9">Chưa có giao dịch thanh toán.</td></tr>\n'
                              '        {% endfor %}\n'
                              '      </tbody>\n'
                              '    </table>\n'
                              '  </div>\n'
                              '</section>\n'
                              '{% if page_obj.has_other_pages %}\n'
                              '<nav class="pagination" aria-label="Phân trang thanh toán">\n'
                              '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}&q={{ '
                              'q|urlencode }}&method={{ method }}&void={{ void_filter }}">← Trước</a>{% else %}<span '
                              'class="disabled">← Trước</span>{% endif %}\n'
                              '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                              '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                              "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                              'href="?page={{ page_number }}&q={{ q|urlencode }}&method={{ method }}&void={{ '
                              'void_filter }}">{{ page_number }}</a>{% endif %}{% endfor %}\n'
                              '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                              'q|urlencode }}&method={{ method }}&void={{ void_filter }}">Sau →</a>{% else %}<span '
                              'class="disabled">Sau →</span>{% endif %}\n'
                              '</nav>\n'
                              '{% endif %}\n'
                              '{% endblock %}\n',
 'rentals/price_suggestion.html': '{% extends "base.html" %}\n'
                                  '{% load static %}\n'
                                  '\n'
                                  '{% block title %}Gợi ý giá thuê thông minh · Phòng {{ room.number }}{% endblock %}\n'
                                  '\n'
                                  '{% block extra_head %}\n'
                                  '<link rel="stylesheet" href="{% static \'css/price-suggestion.css\' %}">\n'
                                  '{% endblock %}\n'
                                  '\n'
                                  '{% block page_title %}Gợi ý giá thuê thông minh{% endblock %}\n'
                                  '{% block page_subtitle %}Hệ thống AI đề xuất giá phòng theo diện tích, tiện nghi & '
                                  'thị trường nội bộ{% endblock %}\n'
                                  '\n'
                                  '{% block content %}\n'
                                  '<div class="price-page">\n'
                                  '\n'
                                  '  <!-- 1. HERO SHOWCASE: THÔNG TIN PHÒNG & DANH MỤC TIỆN NGHI -->\n'
                                  '  <section class="warm-panel price-hero">\n'
                                  '    <div class="price-hero-header">\n'
                                  '      <div class="price-hero-left">\n'
                                  '        <div class="price-ai-badge-icon" title="AI Smart Pricing">\n'
                                  '          <i data-lucide="sparkles"></i>\n'
                                  '        </div>\n'
                                  '        <div class="price-hero-titles">\n'
                                  '          <h1>\n'
                                  '            Phòng {{ room.number }}\n'
                                  '            <span class="price-hero-tag"><i data-lucide="sparkles"></i> AI Định Giá '
                                  'v2.0</span>\n'
                                  '          </h1>\n'
                                  '          <p>{{ room.building.name }} &bull; {{ room.building.address }}</p>\n'
                                  '        </div>\n'
                                  '      </div>\n'
                                  '      <div class="price-hero-actions">\n'
                                  '        <a class="btn-warm-outline" href="{% url \'rooms\' %}" title="Về danh sách '
                                  'phòng">\n'
                                  '          <i data-lucide="arrow-left"></i> Danh sách phòng\n'
                                  '        </a>\n'
                                  '        <a class="btn-warm-outline" href="{% url \'room-update\' room.id %}" '
                                  'title="Chỉnh sửa thông số phòng">\n'
                                  '          <i data-lucide="pencil"></i> Chỉnh sửa phòng\n'
                                  '        </a>\n'
                                  '      </div>\n'
                                  '    </div>\n'
                                  '\n'
                                  '    <!-- Room Specification Chips -->\n'
                                  '    <div class="room-spec-bar">\n'
                                  '      <span class="spec-chip" title="Diện tích phòng">\n'
                                  '        <i data-lucide="maximize-2"></i> {{ room.area|default:"—" }} m²\n'
                                  '      </span>\n'
                                  '      <span class="spec-chip" title="Vị trí tầng">\n'
                                  '        <i data-lucide="layers"></i> Tầng {{ room.floor }}\n'
                                  '      </span>\n'
                                  '      <span class="spec-chip" title="Sức chứa">\n'
                                  '        <i data-lucide="users"></i> Tối đa {{ room.max_occupants }} người\n'
                                  '      </span>\n'
                                  '      <span class="spec-chip status-avail" title="Trạng thái">\n'
                                  '        <i data-lucide="check-circle-2"></i> {{ room.get_status_display }}\n'
                                  '      </span>\n'
                                  '      {% for amenity in room.amenities.all %}\n'
                                  '      <span class="amenity-chip"><i data-lucide="check"></i> {{ amenity.name '
                                  '}}</span>\n'
                                  '      {% empty %}\n'
                                  '      <span class="amenity-chip" '
                                  'style="opacity:0.75;background:#f5f5f4;border-color:#e7e5e4;color:#78716c;">Chưa '
                                  'gán tiện nghi</span>\n'
                                  '      {% endfor %}\n'
                                  '    </div>\n'
                                  '  </section>\n'
                                  '\n'
                                  '  <!-- 2. BỘ ĐÔI ĐỐI SÁNH GIÁ TRỰC QUAN -->\n'
                                  '  <section class="price-showcase-grid">\n'
                                  '\n'
                                  '    <!-- Card 1: Giá niêm yết hiện tại -->\n'
                                  '    <div class="price-card price-card-current">\n'
                                  '      <div>\n'
                                  '        <div class="price-card-header">\n'
                                  '          <div class="card-title-group">\n'
                                  '            <span class="card-icon-pill current"><i data-lucide="home"></i></span>\n'
                                  '            <h2>Giá niêm yết hiện tại</h2>\n'
                                  '          </div>\n'
                                  '          <span class="card-status-badge badge-active">Đang áp dụng</span>\n'
                                  '        </div>\n'
                                  '        <div class="price-amount-box">\n'
                                  '          <span class="price-number">{{ room.monthly_rent|vnd }} đ</span>\n'
                                  '          <span class="price-unit">/ tháng</span>\n'
                                  '        </div>\n'
                                  '      </div>\n'
                                  '      <div>\n'
                                  '        <p class="price-meta-note">\n'
                                  '          <strong>Tiền cọc quy định:</strong> {{ room.deposit_amount|vnd }} đ<br>\n'
                                  '          <span style="color:#a8a29e;font-size:12px;">Mức giá đang hiển thị công '
                                  'khai trên hệ thống & ứng dụng khách thuê.</span>\n'
                                  '        </p>\n'
                                  '      </div>\n'
                                  '    </div>\n'
                                  '\n'
                                  '    <!-- Trung tâm: Bộ chuyển tiếp & So sánh chênh lệch -->\n'
                                  '    <div class="price-comparator-wrap">\n'
                                  '      <div class="price-diff-card">\n'
                                  '        {% if latest_suggestion %}\n'
                                  "          {% if price_diff_direction == 'up' %}\n"
                                  '            <span class="diff-badge up">\n'
                                  '              <i data-lucide="trending-up"></i> +{{ price_diff_abs|vnd }} đ\n'
                                  '            </span>\n'
                                  '            <span '
                                  'style="font-size:12px;font-weight:700;color:#15803d;margin-bottom:4px;">(+{{ '
                                  'price_diff_percent_abs }}%)</span>\n'
                                  '            <p class="diff-text-summary">AI khuyến nghị tăng nhẹ để tối ưu doanh '
                                  'thu</p>\n'
                                  "          {% elif price_diff_direction == 'down' %}\n"
                                  '            <span class="diff-badge down">\n'
                                  '              <i data-lucide="trending-down"></i> -{{ price_diff_abs|vnd }} đ\n'
                                  '            </span>\n'
                                  '            <span '
                                  'style="font-size:12px;font-weight:700;color:#c2410c;margin-bottom:4px;">(-{{ '
                                  'price_diff_percent_abs }}%)</span>\n'
                                  '            <p class="diff-text-summary">AI gợi ý điều chỉnh để tăng tỷ lệ lấp '
                                  'đầy</p>\n'
                                  '          {% else %}\n'
                                  '            <span class="diff-badge equal">\n'
                                  '              <i data-lucide="equal"></i> 0 đ\n'
                                  '            </span>\n'
                                  '            <span '
                                  'style="font-size:12px;font-weight:700;color:#1d4ed8;margin-bottom:4px;">(0%)</span>\n'
                                  '            <p class="diff-text-summary">Giá hiện tại đã rất cân bằng</p>\n'
                                  '          {% endif %}\n'
                                  '        {% else %}\n'
                                  '          <div '
                                  'style="width:36px;height:36px;border-radius:50%;background:#ffedd5;display:grid;place-items:center;color:#ea580c;margin-bottom:6px;">\n'
                                  '            <i data-lucide="sparkles"></i>\n'
                                  '          </div>\n'
                                  '          <p class="diff-text-summary">Sẵn sàng phân tích định giá</p>\n'
                                  '        {% endif %}\n'
                                  '      </div>\n'
                                  '    </div>\n'
                                  '\n'
                                  '    <!-- Card 2: Giá AI gợi ý tối ưu -->\n'
                                  '    <div class="price-card price-card-recommended">\n'
                                  '      <div>\n'
                                  '        <div class="price-card-header">\n'
                                  '          <div class="card-title-group">\n'
                                  '            <span class="card-icon-pill ai"><i data-lucide="sparkles"></i></span>\n'
                                  '            <h2>Gợi ý thông minh từ AI</h2>\n'
                                  '          </div>\n'
                                  '          <span class="card-status-badge" '
                                  'style="background:#fef3c7;color:#92400e;border:1px solid #fde68a;">\n'
                                  '            Random Forest\n'
                                  '          </span>\n'
                                  '        </div>\n'
                                  '        <div class="price-amount-box">\n'
                                  '          {% if latest_suggestion %}\n'
                                  '            <span class="price-number">{{ latest_suggestion.suggested_price|vnd }} '
                                  'đ</span>\n'
                                  '            <span class="price-unit">/ tháng &bull; Đề xuất lúc {{ '
                                  'latest_suggestion.created_at|date:"H:i - d/m/Y" }}</span>\n'
                                  '          {% else %}\n'
                                  '            <span class="price-number" '
                                  'style="font-size:22px;color:#a8a29e;font-weight:700;">Chưa tạo gợi ý</span>\n'
                                  '            <span class="price-unit">Nhấn "Chạy phân tích AI" để nhận mức giá tối '
                                  'ưu</span>\n'
                                  '          {% endif %}\n'
                                  '        </div>\n'
                                  '      </div>\n'
                                  '      <div>\n'
                                  '        {% if latest_suggestion %}\n'
                                  '          {% if latest_suggestion.applied_at %}\n'
                                  '            <div class="applied-badge-block">\n'
                                  '              <i data-lucide="check-check"></i> Đã áp dụng mức giá này\n'
                                  '            </div>\n'
                                  '          {% elif latest_suggestion.current_price == room.monthly_rent %}\n'
                                  '            <form method="post" action="{% url \'price-suggestion-apply\' room.id '
                                  'latest_suggestion.id %}" onsubmit="return confirm(\'Bạn có chắc muốn cập nhật giá '
                                  'niêm yết của phòng {{ room.number }} thành {{ latest_suggestion.suggested_price|vnd '
                                  '}} đ?\');">\n'
                                  '              {% csrf_token %}\n'
                                  '              <button class="btn-warm-apply" type="submit">\n'
                                  '                <i data-lucide="badge-check"></i> Áp dụng giá này ngay\n'
                                  '              </button>\n'
                                  '            </form>\n'
                                  '          {% else %}\n'
                                  '            <div class="applied-badge-block" '
                                  'style="background:#fffbeb;color:#92400e;border-color:#fde68a;">\n'
                                  '              <i data-lucide="alert-circle"></i> Giá phòng đã thay đổi từ lần gợi ý '
                                  'này\n'
                                  '            </div>\n'
                                  '          {% endif %}\n'
                                  '        {% else %}\n'
                                  '          <form method="post">\n'
                                  '            {% csrf_token %}\n'
                                  '            <button class="btn-warm-apply" type="submit">\n'
                                  '              <i data-lucide="sparkles"></i> Phân tích giá ngay\n'
                                  '            </button>\n'
                                  '          </form>\n'
                                  '        {% endif %}\n'
                                  '      </div>\n'
                                  '    </div>\n'
                                  '\n'
                                  '  </section>\n'
                                  '\n'
                                  '  <!-- 3. BANNER HÀNH ĐỘNG: CHẠY PHÂN TÍCH AI MỚI -->\n'
                                  '  <section class="price-action-banner">\n'
                                  '    <div class="price-action-left">\n'
                                  '      <h3><i data-lucide="zap"></i> Cập nhật gợi ý giá thuê mới</h3>\n'
                                  '      <p>\n'
                                  '        Mô hình Machine Learning sẽ tự động đối chiếu các phòng cùng chủ sở hữu dựa '
                                  'trên diện tích, tầng lầu, sức chứa và tiện nghi để tối ưu hóa giá thuê mới nhất.\n'
                                  '      </p>\n'
                                  '      {% if peer_count < 8 %}\n'
                                  '      <p '
                                  'style="margin-top:8px;color:#c2410c;font-weight:600;display:flex;align-items:center;gap:6px;">\n'
                                  '        <i data-lucide="info"></i> Cần ít nhất 8 phòng khác có diện tích và giá '
                                  'thuê (Hiện có {{ peer_count }}/8 phòng).\n'
                                  '      </p>\n'
                                  '      {% endif %}\n'
                                  '    </div>\n'
                                  '    <div>\n'
                                  '      <form method="post">\n'
                                  '        {% csrf_token %}\n'
                                  '        <button class="btn-warm-generate" type="submit">\n'
                                  '          <i data-lucide="sparkles"></i> Chạy phân tích AI ngay\n'
                                  '        </button>\n'
                                  '      </form>\n'
                                  '    </div>\n'
                                  '  </section>\n'
                                  '\n'
                                  '  <!-- 4. THƯỚC ĐO CHẤT LƯỢNG & ĐỘ TIN CẬY MÔ HÌNH -->\n'
                                  '  <section class="price-metrics-grid">\n'
                                  '    <div class="metric-card">\n'
                                  '      <div class="metric-card-top">\n'
                                  '        <span class="metric-card-label"><i data-lucide="gauge"></i> Độ giải thích '
                                  '(R²)</span>\n'
                                  '        {% if latest_suggestion.validation_r2 != None %}\n'
                                  '          <span class="card-status-badge badge-active">Tin cậy</span>\n'
                                  '        {% else %}\n'
                                  '          <span class="card-status-badge" '
                                  'style="background:#fef3c7;color:#92400e;">Đang tích lũy</span>\n'
                                  '        {% endif %}\n'
                                  '      </div>\n'
                                  '      <div class="metric-card-val">\n'
                                  '        {% if latest_suggestion.validation_r2 != None %}\n'
                                  '          {{ latest_suggestion.validation_r2|floatformat:3 }}\n'
                                  '        {% else %}\n'
                                  '          —\n'
                                  '        {% endif %}\n'
                                  '      </div>\n'
                                  '      <p class="metric-card-desc">\n'
                                  '        Khả năng giải thích sự khác biệt giá giữa các phòng từ đặc trưng thực tế '
                                  '(Cần &ge; 20 phòng mẫu để kiểm tra chéo).\n'
                                  '      </p>\n'
                                  '    </div>\n'
                                  '\n'
                                  '    <div class="metric-card">\n'
                                  '      <div class="metric-card-top">\n'
                                  '        <span class="metric-card-label"><i data-lucide="activity"></i> Sai số bình '
                                  'quân (MAE)</span>\n'
                                  '      </div>\n'
                                  '      <div class="metric-card-val">\n'
                                  '        {% if latest_suggestion.validation_mae != None %}\n'
                                  '          &plusmn;{{ latest_suggestion.validation_mae|vnd }} đ\n'
                                  '        {% else %}\n'
                                  '          —\n'
                                  '        {% endif %}\n'
                                  '      </div>\n'
                                  '      <p class="metric-card-desc">\n'
                                  '        Độ lệch tuyệt đối trung bình giữa giá dự báo và giá thực tế khi kiểm nghiệm '
                                  'mô hình.\n'
                                  '      </p>\n'
                                  '    </div>\n'
                                  '\n'
                                  '    <div class="metric-card">\n'
                                  '      <div class="metric-card-top">\n'
                                  '        <span class="metric-card-label"><i data-lucide="database"></i> Dữ liệu tham '
                                  'chiếu</span>\n'
                                  '      </div>\n'
                                  '      <div class="metric-card-val">\n'
                                  '        {% if latest_suggestion %}\n'
                                  '          {{ latest_suggestion.sample_count }} phòng\n'
                                  '        {% else %}\n'
                                  '          {{ peer_count }} phòng\n'
                                  '        {% endif %}\n'
                                  '      </div>\n'
                                  '      <p class="metric-card-desc">\n'
                                  '        Số lượng phòng thực tế của cùng chủ nhà có diện tích và giá hợp lệ được đưa '
                                  'vào huấn luyện.\n'
                                  '      </p>\n'
                                  '    </div>\n'
                                  '  </section>\n'
                                  '\n'
                                  '  <!-- 5. HƯỚNG DẪN CƠ CHẾ HOẠT ĐỘNG THÂN THIỆN -->\n'
                                  '  <section class="warm-panel">\n'
                                  '    <h3 style="font-size:16px;font-weight:800;color:#431407;margin:0 0 '
                                  '10px;display:flex;align-items:center;gap:8px;">\n'
                                  '      <i data-lucide="info" style="color:#ea580c;width:18px;height:18px;"></i> Cơ '
                                  'chế AI gợi ý giá thuê hoạt động như thế nào?\n'
                                  '    </h3>\n'
                                  '    <div class="price-steps-wrap">\n'
                                  '      <div class="step-card">\n'
                                  '        <div class="step-num-pill">1</div>\n'
                                  '        <h4>Trích xuất đặc trưng</h4>\n'
                                  '        <p>AI trích xuất tự động diện tích, tầng, số người tối đa, tòa nhà và hệ '
                                  'thống tiện nghi đi kèm của phòng.</p>\n'
                                  '      </div>\n'
                                  '      <div class="step-card">\n'
                                  '        <div class="step-num-pill">2</div>\n'
                                  '        <h4>Học máy Random Forest</h4>\n'
                                  '        <p>Mô hình xây dựng tập hợp nhiều cây quyết định để tìm ra mức giá tham '
                                  'khảo công bằng, cân bằng thị trường nội bộ.</p>\n'
                                  '      </div>\n'
                                  '      <div class="step-card">\n'
                                  '        <div class="step-num-pill">3</div>\n'
                                  '        <h4>Chủ nhà toàn quyền</h4>\n'
                                  '        <p>Mức giá được làm tròn đến hàng chục nghìn. Bạn hoàn toàn chủ động quyết '
                                  'định áp dụng hoặc điều chỉnh theo ý muốn.</p>\n'
                                  '      </div>\n'
                                  '    </div>\n'
                                  '    <div style="margin-top:14px;padding:10px '
                                  '14px;background:#fffaf0;border-left:3px solid '
                                  '#f97316;border-radius:6px;font-size:12px;color:#78350f;display:flex;align-items:center;gap:8px;">\n'
                                  '      <i data-lucide="shield-check" '
                                  'style="width:16px;height:16px;color:#ea580c;flex-shrink:0;"></i>\n'
                                  '      <span><strong>An tâm sử dụng:</strong> Thao tác áp dụng giá gợi ý chỉ cập '
                                  'nhật giá niêm yết công khai của phòng, hoàn toàn không sửa đổi hay ảnh hưởng đến '
                                  'các hợp đồng thuê đang có hiệu lực.</span>\n'
                                  '    </div>\n'
                                  '  </section>\n'
                                  '\n'
                                  '  <!-- 6. LỊCH SỬ CÁC LẦN GỢI Ý -->\n'
                                  '  <section class="warm-panel price-history-section">\n'
                                  '    <h3>\n'
                                  '      <i data-lucide="history" style="color:#ea580c;width:20px;height:20px;"></i>\n'
                                  '      Lịch sử phân tích & gợi ý giá\n'
                                  '    </h3>\n'
                                  '    <div class="warm-table-wrap">\n'
                                  '      <table class="warm-table">\n'
                                  '        <thead>\n'
                                  '          <tr>\n'
                                  '            <th>Thời gian tạo</th>\n'
                                  '            <th>Giá lúc gợi ý</th>\n'
                                  '            <th>Giá đề xuất AI</th>\n'
                                  '            <th>Quy mô mẫu</th>\n'
                                  '            <th>Sai số (MAE / R²)</th>\n'
                                  '            <th style="text-align:right;">Trạng thái & Thao tác</th>\n'
                                  '          </tr>\n'
                                  '        </thead>\n'
                                  '        <tbody>\n'
                                  '          {% for item in suggestions %}\n'
                                  '          <tr>\n'
                                  '            <td>\n'
                                  '              <strong>{{ item.created_at|date:"d/m/Y" }}</strong>\n'
                                  '              <div style="font-size:11px;color:#a8a29e;">{{ '
                                  'item.created_at|date:"H:i" }}</div>\n'
                                  '            </td>\n'
                                  '            <td>{{ item.current_price|vnd }} đ</td>\n'
                                  '            <td>\n'
                                  '              <strong style="color:#c2410c;font-size:14px;">{{ '
                                  'item.suggested_price|vnd }} đ</strong>\n'
                                  '            </td>\n'
                                  '            <td>{{ item.sample_count }} phòng</td>\n'
                                  '            <td>\n'
                                  '              <div style="font-size:12px;">\n'
                                  '                {% if item.validation_mae != None %}\n'
                                  '                  MAE: &plusmn;{{ item.validation_mae|vnd }} đ\n'
                                  '                {% else %}\n'
                                  '                  <span style="color:#a8a29e;">MAE: &mdash;</span>\n'
                                  '                {% endif %}\n'
                                  '              </div>\n'
                                  '              <div style="font-size:11px;color:#78716c;">\n'
                                  '                {% if item.validation_r2 != None %}\n'
                                  '                  R&sup2;: {{ item.validation_r2|floatformat:3 }}\n'
                                  '                {% else %}\n'
                                  '                  R&sup2;: &mdash;\n'
                                  '                {% endif %}\n'
                                  '              </div>\n'
                                  '            </td>\n'
                                  '            <td style="text-align:right;">\n'
                                  '              {% if item.applied_at %}\n'
                                  '                <span class="badge-history-status applied">\n'
                                  '                  <i data-lucide="check-check"></i> Đã áp dụng ({{ '
                                  'item.applied_at|date:"d/m" }})\n'
                                  '                </span>\n'
                                  '              {% elif item.current_price == room.monthly_rent %}\n'
                                  '                <form method="post" action="{% url \'price-suggestion-apply\' '
                                  'room.id item.id %}" style="display:inline;" onsubmit="return confirm(\'Bạn có chắc '
                                  'muốn áp dụng mức giá {{ item.suggested_price|vnd }} đ/tháng?\');">\n'
                                  '                  {% csrf_token %}\n'
                                  '                  <button class="btn-warm-mini" type="submit">\n'
                                  '                    <i data-lucide="badge-check"></i> Áp dụng\n'
                                  '                  </button>\n'
                                  '                </form>\n'
                                  '              {% else %}\n'
                                  '                <span class="badge-history-status stale" title="Giá phòng đã đổi so '
                                  'với lúc gợi ý">\n'
                                  '                  Giá đã đổi\n'
                                  '                </span>\n'
                                  '              {% endif %}\n'
                                  '            </td>\n'
                                  '          </tr>\n'
                                  '          {% empty %}\n'
                                  '          <tr>\n'
                                  '            <td colspan="6">\n'
                                  '              <div class="price-empty-state">\n'
                                  '                <div class="price-empty-state-icon">\n'
                                  '                  <i data-lucide="sparkles"></i>\n'
                                  '                </div>\n'
                                  '                <h4>Chưa có lịch sử gợi ý giá</h4>\n'
                                  '                <p>Nhấn vào nút "Chạy phân tích AI ngay" ở trên để tạo đề xuất giá '
                                  'đầu tiên cho phòng này.</p>\n'
                                  '              </div>\n'
                                  '            </td>\n'
                                  '          </tr>\n'
                                  '          {% endfor %}\n'
                                  '        </tbody>\n'
                                  '      </table>\n'
                                  '    </div>\n'
                                  '  </section>\n'
                                  '\n'
                                  '</div>\n'
                                  '{% endblock %}\n',
 'rentals/room_form.html': '{% extends "base.html" %}{% load static %}\n'
                           '{% block title %}{% if editing %}Sửa phòng {{ form.instance.number }}{% else %}Thêm phòng '
                           'mới{% endif %}{% endblock %}{% block page_title %}{% if editing %}Sửa phòng {{ '
                           'form.instance.number }}{% else %}Thêm phòng mới{% endif %}{% endblock %}{% block '
                           'page_subtitle %}{% endblock %}\n'
                           '{% block content %}\n'
                           '<link rel="stylesheet" href="{% static \'css/room-form.css\' %}">\n'
                           '{% if editing %}\n'
                           '<div class="page-actions"><a class="btn primary" href="{% url \'room-walkthrough\' '
                           'form.instance.id %}"><i data-lucide="person-standing"></i>Tham quan 3D phòng {{ '
                           'form.instance.number }}</a></div>\n'
                           '{% endif %}\n'
                           '<section class="room-form-panel">\n'
                           '  <div class="room-form-tabs"><button type="button" class="active" data-tab="info"><i '
                           'data-lucide="info"></i>Thông tin</button><button type="button" data-tab="images"><i '
                           'data-lucide="image"></i>Ảnh phòng</button><button type="button" data-tab="videos"><i '
                           'data-lucide="video"></i>Video phòng</button></div>\n'
                           '  <form id="room-create-form" method="post" data-upload-signature-url="{% url '
                           '\'cloudinary-upload-signature\' %}">{% csrf_token %}<input id="media-payload" '
                           'type="hidden" name="media_payload" value="[]"><input id="primary-image" type="hidden" '
                           'name="primary_image" value="">\n'
                           '    {% if form.non_field_errors %}<div class="auth-error">{{ form.non_field_errors '
                           '}}</div>{% endif %}\n'
                           '    <div class="room-tab-content active" data-panel="info">\n'
                           '      <div class="room-fields">\n'
                           '        <label><span>Mã phòng</span>{{ form.number }}{{ form.number.errors '
                           '}}</label><label><span>Tòa nhà</span>{{ form.building }}{{ form.building.errors '
                           '}}</label><label><span>Trạng thái</span>{{ form.status }}{{ form.status.errors }}</label>\n'
                           '        <label><span>Tầng</span>{{ form.floor }}{{ form.floor.errors '
                           '}}</label><label><span>Diện tích (m²)</span>{{ form.area }}{{ form.area.errors '
                           '}}</label><label><span>Số người tối đa</span>{{ form.max_occupants }}{{ '
                           'form.max_occupants.errors }}</label>\n'
                           '        <label class="wide"><span>Giá thuê (VNĐ)</span>{{ form.monthly_rent }}{{ '
                           'form.monthly_rent.errors }}</label><label class="wide"><span>Tiền cọc (VNĐ)</span>{{ '
                           'form.deposit_amount }}{{ form.deposit_amount.errors }}</label>\n'
                           '        <label class="full"><span>Mô tả</span>{{ form.description }}{{ '
                           'form.description.errors }}</label><label class="full amenities-field"><span>Tiện '
                           'nghi</span>{{ form.amenities }}{{ form.amenities.errors }}</label>\n'
                           '      </div>\n'
                           '    </div>\n'
                           '    <div class="room-tab-content" data-panel="images"><div class="upload-zone" '
                           'data-target="room-images"><i data-lucide="images"></i><h3>Thêm ảnh phòng</h3><p>Chọn nhiều '
                           'ảnh cùng lúc hoặc bấm chọn thêm nhiều lần</p><button type="button" class="btn">Chọn nhiều '
                           'ảnh</button><input id="room-images" type="file" accept="image/jpeg,image/png,image/webp" '
                           'multiple hidden></div>{% if existing_images %}<h3>Ảnh hiện có</h3><div '
                           'class="media-previews">{% for media in existing_images %}<label class="media-preview"><img '
                           'src="{{ media.url }}" alt="Ảnh phòng {{ form.instance.number }}"><span><input type="radio" '
                           'name="primary-choice" value="existing:{{ media.id }}" {% if media.is_primary %}checked{% '
                           'endif %}> Ảnh chính</span><span class="delete-media"><input type="checkbox" '
                           'name="delete_media" value="{{ media.id }}"> Xóa ảnh</span></label>{% endfor %}</div>{% '
                           'endif %}<h3>Ảnh mới chọn</h3><div id="image-previews" class="media-previews"></div></div>\n'
                           '    <div class="room-tab-content" data-panel="videos"><div class="upload-zone" '
                           'data-target="room-videos"><i data-lucide="video"></i><h3>Thêm video phòng</h3><p>Video '
                           'được tải trực tiếp và lưu trữ trên Cloudinary</p><button type="button" class="btn">Chọn '
                           'video</button><input id="room-videos" type="file" '
                           'accept="video/mp4,video/webm,video/quicktime" multiple hidden></div>{% if existing_videos '
                           '%}<h3>Video hiện có</h3><div class="media-previews">{% for media in existing_videos '
                           '%}<label class="media-preview"><video src="{{ media.url }}" controls></video><span '
                           'class="delete-media"><input type="checkbox" name="delete_media" value="{{ media.id }}"> '
                           'Xóa video</span></label>{% endfor %}</div>{% endif %}<div id="video-previews" '
                           'class="media-previews"></div></div>\n'
                           '    <div id="upload-status" class="upload-status" role="status" aria-live="polite" '
                           'hidden><span id="upload-message"></span><progress id="upload-progress" max="100" value="0" '
                           'aria-label="Tiến độ tải tệp" hidden></progress></div>\n'
                           '    <footer class="room-form-actions"><a class="btn" href="{% url \'rooms\' '
                           '%}">Hủy</a><button id="save-room" class="btn primary" type="submit"><i '
                           'data-lucide="save"></i>{% if editing %}Lưu thay đổi{% else %}Lưu phòng{% endif '
                           '%}</button></footer>\n'
                           '  </form>\n'
                           '</section>\n'
                           '<script src="{% static \'js/room-form.js\' %}" defer></script>\n'
                           '{% endblock %}\n',
 'rentals/room_list.html': '{% extends "base.html" %}\n'
                           '{% block page_title %}Phòng{% endblock %}\n'
                           '{% block content %}\n'
                           '<div class="page-actions room-toolbar">\n'
                           '  <form method="get" class="room-filters">\n'
                           '    <input name="q" value="{{ q }}" placeholder="Tìm số phòng hoặc tòa nhà...">\n'
                           '    <select name="building">\n'
                           '      <option value="">Tất cả tòa nhà</option>\n'
                           '      {% for building in buildings %}<option value="{{ building.id }}" {% if '
                           "selected_building == building.id|stringformat:'s' %}selected{% endif %}>{{ building.name "
                           '}}</option>{% endfor %}\n'
                           '    </select>\n'
                           '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                           '    {% if q or selected_building %}<a class="btn" href="{% url \'rooms\' %}">Xóa lọc</a>{% '
                           'endif %}\n'
                           '  </form>\n'
                           '  <a class="btn primary" href="{% url \'room-create\' %}">Thêm phòng</a>\n'
                           '</div>\n'
                           '<section class="panel">\n'
                           '  <div class="list-summary">Hiển thị {{ page_obj.start_index }}–{{ page_obj.end_index }} '
                           'trong tổng số <strong>{{ paginator.count }}</strong> phòng</div>\n'
                           '    <div class="table-wrap"><table><thead><tr><th '
                           'class="row-number">STT</th><th>Phòng</th><th>Tòa nhà</th><th>Tầng</th><th>Giá '
                           'thuê</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>{% for x in objects '
                           '%}<tr><td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td><td>{{ '
                           'x.number }}</td><td>{{ x.building }}</td><td>{{ x.floor }}</td><td>{{ x.monthly_rent|vnd '
                           '}} đ</td><td><span class="badge badge-room-{{ x.status }}">{{ x.get_status_display '
                           '}}</span></td><td><a class="btn" href="{% url \'room-update\' x.id %}">Sửa</a> <a '
                           'class="btn" href="{% url \'room-walkthrough\' x.id %}">Tham quan 3D</a> {% if user.role == '
                           '\'owner\' or user.role == \'admin\' or user.is_superuser %}<a class="btn" href="{% url '
                           '\'price-suggestion\' x.id %}">Gợi ý giá</a>{% endif %}</td></tr>{% empty %}<tr><td '
                           'colspan="7">Không tìm thấy phòng phù hợp.</td></tr>{% endfor %}</tbody></table></div>\n'
                           '</section>\n'
                           '{% if page_obj.has_other_pages %}<nav class="pagination" aria-label="Phân trang phòng">\n'
                           '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}&q={{ '
                           'q|urlencode }}&building={{ selected_building }}">← Trước</a>{% else %}<span '
                           'class="disabled">← Trước</span>{% endif %}\n'
                           '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                           '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                           "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                           'href="?page={{ page_number }}&q={{ q|urlencode }}&building={{ selected_building }}">{{ '
                           'page_number }}</a>{% endif %}{% endfor %}\n'
                           '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                           'q|urlencode }}&building={{ selected_building }}">Sau →</a>{% else %}<span '
                           'class="disabled">Sau →</span>{% endif %}\n'
                           '</nav>{% endif %}\n'
                           '{% endblock %}\n',
 'rentals/room_map.html': '{% extends "base.html" %}\n'
                          '{% block title %}Sơ đồ phòng{% endblock %}\n'
                          '{% block page_title %}Sơ đồ phòng{% endblock %}\n'
                          '{% block page_subtitle %}Tổng quan trạng thái phòng theo từng tòa nhà và tầng{% endblock '
                          '%}\n'
                          '{% block content %}\n'
                          '<div class="map-heading">\n'
                          '  <form method="get" class="map-filters">\n'
                          '    <a class="map-control" href="{% url \'room-map\' %}"><i data-lucide="refresh-cw"></i> '
                          'Tải mới</a>\n'
                          '    <label class="map-control"><i data-lucide="list-filter"></i><select name="status" '
                          'onchange="this.form.submit()"><option value="">Tất cả trạng thái</option>{% for value,label '
                          'in status_choices %}<option value="{{ value }}" {% if selected_status == value %}selected{% '
                          'endif %}>{{ label }}</option>{% endfor %}</select></label>\n'
                          '    <label class="map-control"><i data-lucide="building-2"></i><select name="building" '
                          'onchange="this.form.submit()"><option value="">Tất cả tòa nhà</option>{% for building in '
                          'all_buildings %}<option value="{{ building.id }}" {% if selected_building == '
                          "building.id|stringformat:'s' %}selected{% endif %}>{{ building.name }}</option>{% endfor "
                          '%}</select></label>\n'
                          '  </form>\n'
                          '</div>\n'
                          '\n'
                          '<section class="map-stats">\n'
                          '  <article class="map-stat available"><div><span>TRỐNG</span><strong>{{ stats.available '
                          '}}</strong><small>/ {{ stats.total }} phòng</small></div><i '
                          'data-lucide="circle-check"></i></article>\n'
                          '  <article class="map-stat occupied"><div><span>ĐANG THUÊ</span><strong>{{ stats.occupied '
                          '}}</strong><small>/ {{ stats.total }} phòng</small></div><i '
                          'data-lucide="house"></i></article>\n'
                          '  <article class="map-stat reserved"><div><span>ĐÃ ĐẶT</span><strong>{{ stats.reserved '
                          '}}</strong><small>/ {{ stats.total }} phòng</small></div><i '
                          'data-lucide="clock-3"></i></article>\n'
                          '  <article class="map-stat maintenance"><div><span>BẢO TRÌ</span><strong>{{ '
                          'stats.maintenance }}</strong><small>/ {{ stats.total }} phòng</small></div><i '
                          'data-lucide="wrench"></i></article>\n'
                          '</section>\n'
                          '<section class="amenity-summary"><span class="amenity-icon"><i '
                          'data-lucide="snowflake"></i></span><div><b>CÓ ĐIỀU HÒA</b><strong>{{ stats.air_conditioned '
                          '}}</strong><small>/ {{ stats.total }} phòng</small></div><div class="without-air"><b>KHÔNG '
                          'CÓ ĐIỀU HÒA</b><strong>{{ stats.without_air_conditioner }}</strong><small>/ {{ stats.total '
                          '}} phòng</small></div></section>\n'
                          '\n'
                          '<section class="building-maps">\n'
                          '{% for card in building_cards %}\n'
                          '  <article class="building-map">\n'
                          '    <div style="padding:12px '
                          '20px;display:flex;gap:10px;flex-wrap:wrap;align-items:center"><strong>Bản đồ trong '
                          'nhà:</strong>{% for indoor in card.indoor_maps %}<a class="btn" href="{% url \'indoor-map\' '
                          'indoor.id %}">Tầng {{ indoor.floor }}</a>{% empty %}<span>Chưa có bản đồ tầng. Quản trị '
                          'viên có thể tạo trong Django Admin.</span>{% endfor %}</div>\n'
                          '    <header><div class="building-name"><span><i '
                          'data-lucide="building-2"></i></span><div><h2>{{ card.building.name }}</h2><small>{{ '
                          'card.total }} phòng · 5 tầng</small></div></div><div class="building-badges"><b '
                          'class="available">Trống {{ card.counts.available }}</b><b class="occupied">Đang thuê {{ '
                          'card.counts.occupied }}</b><b class="reserved">Đã đặt {{ card.counts.reserved }}</b><b '
                          'class="maintenance">Bảo trì {{ card.counts.maintenance }}</b></div></header>\n'
                          '    <div class="floor-list">\n'
                          '      {% for floor in card.floors %}<div class="floor-row"><div '
                          'class="floor-label"><span>TẦNG</span><strong>{{ floor.number }}</strong></div><div '
                          'class="floor-rooms">{% for room in floor.rooms %}<a href="{% url \'api-room-detail\' '
                          'room.id %}" class="map-room {{ room.status }}" title="{{ room }} — {{ room.monthly_rent|vnd '
                          '}} đ/tháng"><i data-lucide="door-open"></i><strong>{{ room.number }}</strong><small>{{ '
                          'room.get_status_display }}</small>{% if room.has_air_conditioner %}<span class="air"><i '
                          'data-lucide="snowflake"></i></span>{% endif %}</a>{% endfor %}</div></div>{% empty %}<div '
                          'class="map-empty">Không có phòng phù hợp với bộ lọc.</div>{% endfor %}\n'
                          '    </div>\n'
                          '  </article>\n'
                          '{% empty %}<div class="panel map-empty">Không tìm thấy tòa nhà phù hợp.</div>{% endfor %}\n'
                          '</section>\n'
                          '<div class="map-legend"><span><i class="dot available"></i> Phòng trống</span><span><i '
                          'class="dot occupied"></i> Đang thuê</span><span><i class="dot reserved"></i> Đã '
                          'đặt</span><span><i class="dot maintenance"></i> Bảo trì</span></div>\n'
                          '{% endblock %}\n',
 'rentals/room_walkthrough.html': '{% load static %}\n'
                                  '<!doctype html>\n'
                                  '<html lang="vi">\n'
                                  '<head>\n'
                                  '  <meta charset="utf-8">\n'
                                  '  <meta name="viewport" content="width=device-width, initial-scale=1, '
                                  'viewport-fit=cover">\n'
                                  '  <meta name="theme-color" content="#242b28">\n'
                                  '  <title>Tham quan phòng {{ room.number }} · {{ room.building.name }}</title>\n'
                                  '  <link rel="icon" href="{% static \'images/favicon.png\' %}">\n'
                                  '  <link rel="stylesheet" href="{% static \'css/room-walkthrough.css\' '
                                  '%}?v=building-tour-1">\n'
                                  '  <link rel="stylesheet" href="{% static \'css/building-tour.css\' '
                                  '%}?v=building-tour-1">\n'
                                  '</head>\n'
                                  '<body>\n'
                                  '  {{ tour_config|json_script:"tour-config" }}\n'
                                  '  <main id="room-tour" class="room-tour" aria-label="Mô phỏng tham quan phòng {{ '
                                  'room.number }}">\n'
                                  '    {% include "rentals/includes/building_tour_controls.html" %}\n'
                                  '    <div id="tour-canvas" tabindex="0" role="application" aria-label="Không gian '
                                  '3D. W tiến, S lùi, A sang trái, D sang phải, Space nhảy. Tới chân cầu thang rồi giữ '
                                  'W để lên gác, S để xuống. Kéo chuột để xoay góc nhìn. V đổi góc nhìn thứ nhất và '
                                  'thứ ba."></div>\n'
                                  '    <header class="tour-header">\n'
                                  '      <div class="room-heading"><span class="eyebrow">{{ room.building.name }} · '
                                  '<span id="tour-floor-label">Tầng {{ room.floor }}</span></span><h1><span '
                                  'id="tour-room-name">Phòng {{ room.number }}</span> <span class="tour-badge">Tham '
                                  'quan 3D</span></h1><p><span class="live-dot"></span><span id="tour-position" '
                                  'aria-live="polite">Trước cửa phòng {{ room.number }}</span></p><div '
                                  'class="connected-rooms"></div></div>\n'
                                  '      <nav class="tour-actions" aria-label="Công cụ tham quan">\n'
                                  '        <button id="tour-map" class="map-button" type="button" aria-label="Sơ đồ '
                                  'tòa nhà" title="Sơ đồ tòa nhà (M)"><i data-lucide="building-2"></i><span>Sơ đồ tòa '
                                  'nhà</span></button>\n'
                                  '        <button id="tour-view" class="view-button" type="button" '
                                  'aria-pressed="false" title="Góc nhìn thứ nhất (V)"><i '
                                  'data-lucide="eye"></i><span>Góc nhìn thứ nhất</span></button>\n'
                                  '        <button id="tour-media" class="media-button" type="button"><i '
                                  'data-lucide="images"></i><span>Ảnh & video</span></button>\n'
                                  '        <button id="tour-reset" type="button" aria-label="Trở về trước cửa phòng" '
                                  'title="Trở về cửa (R)"><i data-lucide="rotate-ccw"></i></button>\n'
                                  '        <button id="tour-help" type="button" aria-label="Hướng dẫn điều khiển" '
                                  'title="Hướng dẫn"><i data-lucide="circle-help"></i></button>\n'
                                  '        <button id="tour-fullscreen" type="button" aria-label="Bật toàn màn hình" '
                                  'title="Toàn màn hình"><i data-lucide="maximize"></i></button>\n'
                                  '        <a href="{{ return_url }}" aria-label="Thoát tham quan" title="Thoát tham '
                                  'quan"><i data-lucide="x"></i></a>\n'
                                  '      </nav>\n'
                                  '    </header>\n'
                                  '    <div id="tour-cue" class="tour-cue"><i data-lucide="door-open"></i><span>Đi tới '
                                  'cửa để vào phòng</span></div>\n'
                                  '    <div id="tour-loading" class="tour-overlay">\n'
                                  '      <div class="intro-card"><span class="intro-icon"><i '
                                  'data-lucide="footprints"></i></span><span class="eyebrow">{{ room.building.name '
                                  '}}</span><h2>Khám phá tòa nhà</h2><p>{{ tour_config.floors|length }} tầng · {{ '
                                  'tour_rooms|length }} phòng có thể tham quan.<br>Đi dọc hành lang và khám phá các '
                                  'tầng.</p><div class="intro-keys" aria-label="Phím di '
                                  'chuyển"><kbd>W</kbd><div><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd></div><kbd '
                                  'class="space-key">Space · Nhảy</kbd></div><p class="intro-hint">WASD di chuyển · '
                                  'Kéo chuột để nhìn quanh<br>M mở sơ đồ · F chọn tầng tại thang máy<br>V đổi góc nhìn '
                                  '· W lên gác, S xuống</p><button id="tour-start" type="button" disabled>Đang chuẩn '
                                  'bị không gian…</button><small>Phòng đã có tư liệu giữ bố cục đã dựng. Các phòng còn '
                                  'lại dùng nội thất mô phỏng. Kích thước ước lượng.</small></div>\n'
                                  '    </div>\n'
                                  '    <div id="tour-fallback" class="tour-overlay" hidden><div class="intro-card"><i '
                                  'data-lucide="monitor"></i><h2>Chưa mở được không gian 3D</h2><p id="tour-error">Hãy '
                                  'thử tải lại trang hoặc bật tăng tốc đồ họa trong trình duyệt.</p><a href="{{ '
                                  'return_url }}" class="primary-link">Quay lại phòng</a><button type="button" '
                                  'id="tour-reload">Tải lại</button></div></div>\n'
                                  '    <footer class="tour-footer">\n'
                                  '      <div class="movement-guide"><div '
                                  'class="key-row"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd><span>Di '
                                  'chuyển</span><kbd class="space-key">Space</kbd><span>Nhảy</span></div><div><i '
                                  'data-lucide="mouse-pointer-2"></i> Kéo chuột để nhìn quanh <span '
                                  'class="guide-separator">·</span> <kbd>Q</kbd><kbd>E</kbd> Xoay <span '
                                  'class="guide-separator">·</span> <kbd>V</kbd> Đổi góc nhìn</div></div>\n'
                                  '      <div class="tour-note" id="tour-model-note">Bố trí mô phỏng · Kích thước ước '
                                  'lượng</div>\n'
                                  '      <aside class="mini-map" aria-label="Sơ đồ vị trí nhân vật"><div><i '
                                  'data-lucide="map"></i><span id="mini-floor-label">Tầng {{ room.floor '
                                  '}}</span></div><svg viewBox="0 0 220 215" role="img" aria-label="Chấm cam thể hiện '
                                  'vị trí của bạn trong phòng"><g id="map-geometry"></g><g id="map-player"><circle '
                                  'r="9" class="map-player-glow"/><circle r="4.5" class="map-player-dot"/><path d="M '
                                  '-4 -9 L 0 -15 L 4 -9" class="map-heading"/></g></svg><button id="mini-map-open" '
                                  'type="button">Xem tòa nhà <i data-lucide="expand"></i></button></aside>\n'
                                  '    </footer>\n'
                                  '    <div class="touch-controls" aria-label="Điều khiển di chuyển trên màn '
                                  'hình"><button type="button" data-move="KeyW" class="touch-up" aria-label="Tiến '
                                  'lên"><i data-lucide="chevron-up"></i></button><button type="button" '
                                  'data-move="KeyA" class="touch-left" aria-label="Sang trái"><i '
                                  'data-lucide="chevron-left"></i></button><button type="button" data-move="KeyS" '
                                  'class="touch-down" aria-label="Lùi lại"><i '
                                  'data-lucide="chevron-down"></i></button><button type="button" data-move="KeyD" '
                                  'class="touch-right" aria-label="Sang phải"><i '
                                  'data-lucide="chevron-right"></i></button></div>\n'
                                  '    <button type="button" id="tour-jump" class="touch-jump" aria-label="Nhảy"><i '
                                  'data-lucide="arrow-up-from-line"></i><span>Nhảy</span></button>\n'
                                  '    <dialog id="tour-media-dialog" aria-labelledby="media-title" '
                                  'class="tour-dialog"><div class="dialog-heading"><div><span class="eyebrow">TƯ LIỆU '
                                  'THỰC TẾ</span><h2 id="media-title">Ảnh & video phòng {{ room.number '
                                  '}}</h2></div><button type="button" data-close-dialog aria-label="Đóng ảnh và '
                                  'video"><i data-lucide="x"></i></button></div>{% for item in tour_rooms %}<div '
                                  'class="reference-gallery" data-room-media="{{ item.number }}" {% if item.number != '
                                  'room.number %}hidden{% endif %}>{% for media in item.images %}<a href="{{ media.url '
                                  '}}" target="_blank" rel="noopener"><img src="{{ media.url }}" alt="Ảnh {{ '
                                  'forloop.counter }} của phòng {{ item.number }}" loading="lazy"></a>{% endfor %}{% '
                                  'for media in item.videos %}<video src="{{ media.url }}" controls playsinline '
                                  'preload="none" aria-label="Video phòng {{ item.number }}"></video>{% endfor %}{% if '
                                  'not item.images and not item.videos %}<p>Phòng {{ item.number }} chưa có ảnh hoặc '
                                  'video được lưu trên hệ thống. Bạn vẫn có thể tham quan nội thất mô phỏng cơ '
                                  'bản.</p>{% endif %}</div>{% endfor %}</dialog>\n'
                                  '    <dialog id="tour-help-dialog" aria-labelledby="help-title" class="tour-dialog '
                                  'help-dialog"><div class="dialog-heading"><h2 id="help-title">Cùng khám phá các '
                                  'phòng</h2><button type="button" data-close-dialog aria-label="Đóng hướng dẫn"><i '
                                  'data-lucide="x"></i></button></div><dl><div><dt><kbd>W</kbd> / '
                                  '<kbd>S</kbd></dt><dd>Tiến về phía trước / lùi lại; trên cầu thang: lên / '
                                  'xuống</dd></div><div><dt><kbd>A</kbd> / <kbd>D</kbd></dt><dd>Di chuyển sang trái / '
                                  'phải</dd></div><div><dt><kbd class="space-key">Space</kbd></dt><dd>Nhảy lên; có thể '
                                  'vừa đi vừa nhảy</dd></div><div><dt>Kéo chuột</dt><dd>Xoay góc nhìn quanh nhân '
                                  'vật</dd></div><div><dt><kbd>Q</kbd> / <kbd>E</kbd></dt><dd>Xoay góc nhìn bằng bàn '
                                  'phím</dd></div><div><dt><kbd>V</kbd></dt><dd>Đổi góc nhìn thứ nhất / thứ '
                                  'ba</dd></div><div><dt><kbd>M</kbd></dt><dd>Sơ đồ tòa nhà và chỉ đường tới '
                                  'phòng</dd></div><div><dt><kbd>F</kbd></dt><dd>Chọn tầng khi đứng gần thang '
                                  'máy</dd></div><div><dt><kbd>R</kbd></dt><dd>Đưa nhân vật về trước '
                                  'cửa</dd></div></dl><p>Cửa tự mở khi bạn tới gần. Đi qua hành lang để vào phòng bên '
                                  'cạnh. Đến chân cầu thang rồi giữ W để lên gác. Khi ở trên thang, W luôn đi lên và S '
                                  'luôn đi xuống; A/D hoạt động lại khi ra khỏi thang. Trên gác, dùng WASD đi lại và '
                                  'Space để nhảy; đến đầu thang rồi giữ S để xuống. Tường, lan can và đồ đạc có va '
                                  'chạm.</p><p>Chọn phòng trên sơ đồ để xem đường đi. Đường xanh dẫn tới thang máy nếu '
                                  'phòng ở tầng khác. Tới cửa thang máy, nhấn F hoặc nút trên màn hình để chọn tầng '
                                  'rồi đi dọc hành lang tới phòng.</p><p class="help-note">Mô phỏng giúp hình dung bố '
                                  'cục, không thay thế bản vẽ đo đạc.</p></dialog>\n'
                                  '    <noscript><div class="no-script">Bạn cần bật JavaScript để mở mô phỏng. <a '
                                  'href="{{ return_url }}">Quay lại phòng</a></div></noscript>\n'
                                  '  </main>\n'
                                  '  <script src="{% static \'lucide.min.js\' %}"></script>\n'
                                  '  <script>lucide.createIcons();</script>\n'
                                  '  <script type="module" src="{% static \'js/room-walkthrough.js\' '
                                  '%}?v=landscape-1"></script>\n'
                                  '</body>\n'
                                  '</html>\n',
 'rentals/service_list.html': '{% extends "base.html" %}\n'
                              '{% block page_title %}Danh mục dịch vụ{% endblock %}\n'
                              '{% block content %}\n'
                              '<div class="page-actions room-toolbar">\n'
                              '  <form method="get" class="room-filters">\n'
                              '    <input name="q" value="{{ q }}" placeholder="Tìm tên dịch vụ...">\n'
                              '    <select name="unit">\n'
                              '      <option value="">Tất cả đơn vị tính</option>\n'
                              '      {% for code, label in unit_choices %}<option value="{{ code }}" {% if unit == '
                              'code %}selected{% endif %}>{{ label }}</option>{% endfor %}\n'
                              '    </select>\n'
                              '    <select name="status">\n'
                              '      <option value="">Tất cả trạng thái</option>\n'
                              '      <option value="active" {% if status == \'active\' %}selected{% endif %}>Đang áp '
                              'dụng</option>\n'
                              '      <option value="inactive" {% if status == \'inactive\' %}selected{% endif %}>Ngừng '
                              'áp dụng</option>\n'
                              '    </select>\n'
                              '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                              '    {% if q or unit or status %}<a class="btn" href="{% url \'services\' %}">Xóa '
                              'lọc</a>{% endif %}\n'
                              '  </form>\n'
                              '  <a class="btn primary" href="{% url \'service-create\' %}">Thêm dịch vụ</a>\n'
                              '</div>\n'
                              '<section class="panel">\n'
                              '  <div class="list-summary"><span>Danh mục dịch vụ</span><span>Tổng số: <strong>{{ '
                              'paginator.count }}</strong></span></div>\n'
                              '  <div class="table-wrap">\n'
                              '    <table>\n'
                              '      <thead>\n'
                              '        <tr>\n'
                              '          <th class="row-number">STT</th>\n'
                              '          <th>Tên dịch vụ</th>\n'
                              '          <th>Đơn vị tính</th>\n'
                              '          <th>Đơn giá mặc định</th>\n'
                              '          <th>Tính theo đồng hồ</th>\n'
                              '          <th>Trạng thái</th>\n'
                              '          <th>Thao tác</th>\n'
                              '        </tr>\n'
                              '      </thead>\n'
                              '      <tbody>\n'
                              '        {% for x in objects %}\n'
                              '        <tr>\n'
                              '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                              '          <td><strong>{{ x.name }}</strong></td>\n'
                              '          <td><span class="badge">{{ x.get_unit_display }}</span></td>\n'
                              '          <td>{{ x.unit_price|vnd }} đ</td>\n'
                              '          <td>{{ x.is_metered|yesno:"Có (Theo chỉ số),Không" }}</td>\n'
                              '          <td>\n'
                              '            <span class="status-pill {% if x.is_active %}active{% else %}inactive{% '
                              'endif %}">\n'
                              '              <b></b>{{ x.is_active|yesno:"Đang áp dụng,Ngừng" }}\n'
                              '            </span>\n'
                              '          </td>\n'
                              '          <td>\n'
                              '            <div style="display:flex;gap:6px;">\n'
                              '              <a class="btn compact" href="{% url \'service-update\' x.id %}">Sửa</a>\n'
                              '              <form method="post" action="{% url \'service-delete\' x.id %}" '
                              'onsubmit="return confirm(\'Bạn có chắc chắn muốn xóa/ngừng dịch vụ {{ x.name }}?\');" '
                              'style="display:inline;">\n'
                              '                {% csrf_token %}\n'
                              '                <button class="btn compact" type="submit" '
                              'style="color:var(--red);">Xóa</button>\n'
                              '              </form>\n'
                              '            </div>\n'
                              '          </td>\n'
                              '        </tr>\n'
                              '        {% empty %}\n'
                              '        <tr><td colspan="7">Chưa có dịch vụ nào.</td></tr>\n'
                              '        {% endfor %}\n'
                              '      </tbody>\n'
                              '    </table>\n'
                              '  </div>\n'
                              '</section>\n'
                              '{% if page_obj.has_other_pages %}\n'
                              '<nav class="pagination" aria-label="Phân trang dịch vụ">\n'
                              '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}&q={{ '
                              'q|urlencode }}&unit={{ unit }}&status={{ status }}">← Trước</a>{% else %}<span '
                              'class="disabled">← Trước</span>{% endif %}\n'
                              '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                              '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                              "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                              'href="?page={{ page_number }}&q={{ q|urlencode }}&unit={{ unit }}&status={{ status '
                              '}}">{{ page_number }}</a>{% endif %}{% endfor %}\n'
                              '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                              'q|urlencode }}&unit={{ unit }}&status={{ status }}">Sau →</a>{% else %}<span '
                              'class="disabled">Sau →</span>{% endif %}\n'
                              '</nav>\n'
                              '{% endif %}\n'
                              '{% endblock %}\n',
 'rentals/tenant_detail.html': '{% extends "base.html" %}\n'
                               '{% block page_title %}Chi tiết khách thuê: {{ tenant.full_name }}{% endblock %}\n'
                               '{% block content %}\n'
                               '<div class="page-actions" style="flex-wrap:wrap;gap:10px;">\n'
                               '  <div style="display:flex;gap:8px;align-items:center;">\n'
                               '    <a class="btn" href="{% url \'tenants\' %}">← Danh sách khách thuê</a>\n'
                               '    <a class="btn primary" href="{% url \'tenant-update\' tenant.id %}">Chỉnh sửa '
                               'thông tin</a>\n'
                               '  </div>\n'
                               '  <form method="post" action="{% url \'tenant-toggle-active\' tenant.id %}" '
                               'onsubmit="return confirm(\'Bạn có chắc chắn muốn {% if tenant.is_active %}ngừng kích '
                               'hoạt{% else %}kích hoạt lại{% endif %} khách thuê này?\');">\n'
                               '    {% csrf_token %}\n'
                               '    <button class="btn" type="submit" style="{% if tenant.is_active '
                               '%}color:var(--red);border-color:var(--red);{% else '
                               '%}color:var(--green);border-color:var(--green);{% endif %}">\n'
                               '      {% if tenant.is_active %}Ngừng kích hoạt{% else %}Kích hoạt lại{% endif %}\n'
                               '    </button>\n'
                               '  </form>\n'
                               '</div>\n'
                               '\n'
                               '<section class="two-columns" style="margin-bottom:20px;">\n'
                               '  <article class="panel">\n'
                               '    <div class="panel-heading">\n'
                               '      <h2>Thông tin cá nhân</h2>\n'
                               '      <span class="status-pill {% if tenant.is_active %}active{% else %}inactive{% '
                               'endif %}">\n'
                               '        <b></b>{{ tenant.is_active|yesno:"Đang hoạt động,Ngừng kích hoạt" }}\n'
                               '      </span>\n'
                               '    </div>\n'
                               '    <div class="detail-grid">\n'
                               '      <div><span>Họ và tên</span><strong>{{ tenant.full_name }}</strong></div>\n'
                               '      <div><span>Số điện thoại</span><strong>{{ tenant.phone|default:"—" '
                               '}}</strong></div>\n'
                               '      <div><span>Email</span><strong>{{ tenant.email|default:"—" }}</strong></div>\n'
                               '      <div><span>Ngày sinh</span><strong>{% if tenant.date_of_birth %}{{ '
                               'tenant.date_of_birth|date:"d/m/Y" }}{% else %}—{% endif %}</strong></div>\n'
                               '      <div><span>Giới tính</span><strong>{{ tenant.get_gender_display|default:"—" '
                               '}}</strong></div>\n'
                               '      <div><span>CCCD/Hộ chiếu</span><strong>{{ tenant.identity_number|default:"—" '
                               '}}</strong></div>\n'
                               '      <div><span>Nghề nghiệp</span><strong>{{ tenant.occupation|default:"—" '
                               '}}</strong></div>\n'
                               '      <div><span>Ngày cấp</span><strong>{% if tenant.identity_issued_date %}{{ '
                               'tenant.identity_issued_date|date:"d/m/Y" }}{% else %}—{% endif %}</strong></div>\n'
                               '      <div><span>Liên hệ khẩn cấp</span><strong>{{ '
                               'tenant.emergency_contact|default:"—" }}</strong></div>\n'
                               '      <div><span>Địa chỉ thường trú</span><strong>{{ '
                               'tenant.permanent_address|default:"—" }}</strong></div>\n'
                               '      <div><span>Phòng hiện tại</span><strong>{% if current_rooms %}{% for r in '
                               'current_rooms %}{{ r }}{% if not forloop.last %}, {% endif %}{% endfor %}{% else '
                               '%}Chưa có phòng đang thuê{% endif %}</strong></div>\n'
                               '    </div>\n'
                               '  </article>\n'
                               '\n'
                               '  <article class="panel">\n'
                               '    <div class="panel-heading">\n'
                               '      <h2>Liên kết tài khoản khách thuê</h2>\n'
                               '      {% if tenant.user %}<span class="badge">{{ tenant.user.username }}</span>{% else '
                               '%}<span class="muted">Chưa liên kết</span>{% endif %}\n'
                               '    </div>\n'
                               '    <p class="muted" style="margin-top:0;">Liên kết hồ sơ khách thuê với tài khoản '
                               'đăng nhập cổng người thuê (vai trò Khách thuê).</p>\n'
                               '    <form method="post" action="{% url \'tenant-link-user\' tenant.id %}">\n'
                               '      {% csrf_token %}\n'
                               '      <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">\n'
                               '        <div style="flex:1;min-width:220px;">{{ link_form.user }}</div>\n'
                               '        <button class="btn primary" type="submit">Lưu liên kết</button>\n'
                               '      </div>\n'
                               '    </form>\n'
                               '    {% if current_rooms %}\n'
                               '    <hr style="border:0;border-top:1px solid var(--line);margin:18px 0;">\n'
                               '    <h2>Phòng đang ở hiện tại</h2>\n'
                               '    <table>\n'
                               '      <thead><tr><th>Phòng</th><th>Tòa nhà</th><th>Tầng</th><th>Giá '
                               'thuê</th></tr></thead>\n'
                               '      <tbody>\n'
                               '        {% for room in current_rooms %}\n'
                               '        <tr>\n'
                               '          <td><strong>{{ room.number }}</strong></td>\n'
                               '          <td>{{ room.building.name }}</td>\n'
                               '          <td>{{ room.floor }}</td>\n'
                               '          <td>{{ room.monthly_rent|vnd }} đ</td>\n'
                               '        </tr>\n'
                               '        {% endfor %}\n'
                               '      </tbody>\n'
                               '    </table>\n'
                               '    {% endif %}\n'
                               '  </article>\n'
                               '</section>\n'
                               '\n'
                               '<section class="panel" style="margin-bottom:20px;">\n'
                               '  <div class="panel-heading"><h2>Ảnh CCCD</h2><a class="btn compact" href="{% url '
                               '\'tenant-update\' tenant.id %}">Cập nhật ảnh</a></div>\n'
                               '  <div style="display:flex;flex-wrap:wrap;gap:20px;">\n'
                               '    {% for image in tenant.identity_images.all %}\n'
                               '    <figure style="margin:0;flex:1;min-width:200px;max-width:380px;">\n'
                               '      <figcaption>{{ image.get_side_display }}</figcaption>\n'
                               '      <a href="{% url \'tenant-identity-image\' tenant.id image.side %}" '
                               'target="_blank" rel="noopener noreferrer"><img src="{% url \'tenant-identity-image\' '
                               'tenant.id image.side %}" alt="{{ image.get_side_display }}" loading="lazy" '
                               'referrerpolicy="no-referrer" '
                               'style="width:100%;height:220px;object-fit:contain;border:1px solid '
                               '#e5e7eb;border-radius:12px;margin-top:10px;"></a>\n'
                               '    </figure>\n'
                               '    {% empty %}<p class="muted">Chưa có ảnh CCCD. Có thể bổ sung sau.</p>{% endfor %}\n'
                               '  </div>\n'
                               '</section>\n'
                               '\n'
                               '<section class="panel" style="margin-bottom:20px;">\n'
                               '  <div class="panel-heading">\n'
                               '    <h2>Hợp đồng hiện tại và lịch sử hợp đồng ({{ contracts|length }})</h2>\n'
                               '    <a class="btn primary compact" href="{% url \'contract-create\' %}">+ Tạo hợp '
                               'đồng</a>\n'
                               '  </div>\n'
                               '  <div class="table-wrap">\n'
                               '    <table>\n'
                               '      <thead>\n'
                               '        <tr>\n'
                               '          <th>Mã HĐ</th>\n'
                               '          <th>Phòng</th>\n'
                               '          <th>Vai trò</th>\n'
                               '          <th>Thời hạn</th>\n'
                               '          <th>Giá thuê</th>\n'
                               '          <th>Tiền cọc</th>\n'
                               '          <th>Trạng thái</th>\n'
                               '          <th>Thao tác</th>\n'
                               '        </tr>\n'
                               '      </thead>\n'
                               '      <tbody>\n'
                               '        {% for c in contracts %}\n'
                               '        <tr>\n'
                               '          <td><a href="{% url \'contract-detail\' c.id %}" '
                               'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ c.code '
                               '}}</a></td>\n'
                               '          <td>{{ c.room }}</td>\n'
                               '          <td>{% if c.representative_id == tenant.id %}Đại diện{% else %}Người ở '
                               'cùng{% endif %}</td>\n'
                               '          <td>{{ c.start_date|date:"d/m/Y" }} – {{ c.end_date|date:"d/m/Y" }}</td>\n'
                               '          <td>{{ c.monthly_rent|vnd }} đ</td>\n'
                               '          <td>{{ c.deposit_amount|vnd }} đ</td>\n'
                               '          <td><span class="badge">{{ c.get_status_display }}</span></td>\n'
                               '          <td><a class="btn compact" href="{% url \'contract-detail\' c.id %}">Chi '
                               'tiết</a></td>\n'
                               '        </tr>\n'
                               '        {% empty %}\n'
                               '        <tr><td colspan="8">Chưa có hợp đồng nào.</td></tr>\n'
                               '        {% endfor %}\n'
                               '      </tbody>\n'
                               '    </table>\n'
                               '  </div>\n'
                               '</section>\n'
                               '\n'
                               '<section class="two-columns">\n'
                               '  <article class="panel">\n'
                               '    <div class="panel-heading"><h2>Hóa đơn ({{ invoices|length }})</h2></div>\n'
                               '    <div class="table-wrap">\n'
                               '      <table>\n'
                               '        <thead>\n'
                               '          <tr><th>Mã HĐơn</th><th>Kỳ</th><th>Tổng cộng</th><th>Đã trả</th><th>Còn '
                               'nợ</th><th>Trạng thái</th></tr>\n'
                               '        </thead>\n'
                               '        <tbody>\n'
                               '          {% for inv in invoices %}\n'
                               '          <tr>\n'
                               '            <td>{{ inv.code }}</td>\n'
                               '            <td>{{ inv.period|date:"m/Y" }}</td>\n'
                               '            <td>{{ inv.total_amount|vnd }} đ</td>\n'
                               '            <td>{{ inv.paid_amount|vnd }} đ</td>\n'
                               '            <td>{{ inv.balance|vnd }} đ</td>\n'
                               '            <td><span class="badge">{{ inv.get_status_display }}</span></td>\n'
                               '          </tr>\n'
                               '          {% empty %}\n'
                               '          <tr><td colspan="6">Chưa có hóa đơn nào.</td></tr>\n'
                               '          {% endfor %}\n'
                               '        </tbody>\n'
                               '      </table>\n'
                               '    </div>\n'
                               '  </article>\n'
                               '\n'
                               '  <article class="panel">\n'
                               '    <div class="panel-heading"><h2>Lịch sử thanh toán ({{ payments|length '
                               '}})</h2></div>\n'
                               '    <div class="table-wrap">\n'
                               '      <table>\n'
                               '        <thead>\n'
                               '          <tr><th>Thời gian</th><th>Hóa đơn</th><th>Số tiền</th><th>Phương '
                               'thức</th><th>Trạng thái</th></tr>\n'
                               '        </thead>\n'
                               '        <tbody>\n'
                               '          {% for p in payments %}\n'
                               '          <tr>\n'
                               '            <td>{{ p.paid_at|date:"d/m/Y H:i" }}</td>\n'
                               '            <td>{{ p.invoice.code }}</td>\n'
                               '            <td>{{ p.amount|vnd }} đ</td>\n'
                               '            <td>{{ p.get_method_display }}</td>\n'
                               '            <td>{% if p.is_void %}<span class="badge" '
                               'style="background:#ffebed;color:#ca3944;">Đã hủy</span>{% else %}<span '
                               'class="badge">Hợp lệ</span>{% endif %}</td>\n'
                               '          </tr>\n'
                               '          {% empty %}\n'
                               '          <tr><td colspan="5">Chưa có giao dịch thanh toán.</td></tr>\n'
                               '          {% endfor %}\n'
                               '        </tbody>\n'
                               '      </table>\n'
                               '    </div>\n'
                               '  </article>\n'
                               '</section>\n'
                               '{% endblock %}\n',
 'rentals/tenant_form.html': '{% extends "base.html" %}{% load static %}\n'
                             '{% block title %}{% if editing %}Sửa khách thuê{% else %}Thêm khách thuê mới{% endif '
                             '%}{% endblock %}\n'
                             '{% block page_title %}Khách thuê{% endblock %}\n'
                             '{% block extra_head %}<link rel="stylesheet" href="{% static \'css/tenant-form.css\' '
                             '%}">{% endblock %}\n'
                             '{% block content %}\n'
                             '<div class="tenant-backdrop">\n'
                             '  <section class="tenant-dialog" role="dialog" aria-modal="true" '
                             'aria-labelledby="tenant-form-title">\n'
                             '    <header class="tenant-dialog-heading">\n'
                             '      <h2 id="tenant-form-title">{% if editing %}Sửa thông tin khách thuê{% else %}Thêm '
                             'khách thuê mới{% endif %}</h2>\n'
                             '      <a class="tenant-close" href="{% url \'tenants\' %}" aria-label="Đóng">×</a>\n'
                             '      <p>{% if editing %}Cập nhật hồ sơ và ảnh CCCD của khách thuê{% else %}Nhập thông '
                             'tin khách thuê mới{% endif %}</p>\n'
                             '    </header>\n'
                             '    <form method="post" enctype="multipart/form-data" id="tenant-form">\n'
                             '      {% csrf_token %}\n'
                             '      <div class="tenant-tabs" role="tablist" aria-label="Hồ sơ khách thuê">\n'
                             '        <button type="button" id="tenant-info-tab" role="tab" '
                             'aria-controls="tenant-info" aria-selected="true" data-tenant-tab="tenant-info"><i '
                             'data-lucide="info"></i>Thông tin</button>\n'
                             '        <button type="button" id="tenant-images-tab" role="tab" '
                             'aria-controls="tenant-images" aria-selected="false" tabindex="-1" '
                             'data-tenant-tab="tenant-images"><i data-lucide="credit-card"></i>Ảnh CCCD</button>\n'
                             '      </div>\n'
                             '      {% if form.errors %}<div class="tenant-errors" role="alert">Chưa lưu được hồ sơ. '
                             'Vui lòng kiểm tra các mục bên dưới.{{ form.non_field_errors }}{% if '
                             'form.identity_front.errors or form.identity_back.errors %}<p>Kiểm tra tab Ảnh CCCD và '
                             'chọn lại ảnh cần tải lên.</p>{% endif %}</div>{% endif %}\n'
                             '      <div class="tenant-tab-panel" id="tenant-info" role="tabpanel" '
                             'aria-labelledby="tenant-info-tab">\n'
                             '        <div class="tenant-field-grid">\n'
                             '          <label for="{{ form.full_name.id_for_label }}">Họ tên <span '
                             'class="tenant-required">*</span>{{ form.full_name }}{{ form.full_name.errors }}</label>\n'
                             '          <label for="{{ form.phone.id_for_label }}">Số điện thoại{{ form.phone }}{{ '
                             'form.phone.errors }}</label>\n'
                             '          <label for="{{ form.email.id_for_label }}">Email{{ form.email }}{{ '
                             'form.email.errors }}</label>\n'
                             '          <label for="{{ form.identity_number.id_for_label }}">CCCD{{ '
                             'form.identity_number }}{{ form.identity_number.errors }}</label>\n'
                             '          <label for="{{ form.date_of_birth.id_for_label }}">Ngày sinh{{ '
                             'form.date_of_birth }}{{ form.date_of_birth.errors }}</label>\n'
                             '          <label for="{{ form.gender.id_for_label }}">Giới tính{{ form.gender }}{{ '
                             'form.gender.errors }}</label>\n'
                             '          <label class="tenant-full" for="{{ form.permanent_address.id_for_label }}">Quê '
                             'quán / địa chỉ thường trú{{ form.permanent_address }}{{ form.permanent_address.errors '
                             '}}</label>\n'
                             '          <label class="tenant-full" for="{{ form.occupation.id_for_label }}">Nghề '
                             'nghiệp{{ form.occupation }}{{ form.occupation.errors }}</label>\n'
                             '        </div>\n'
                             '        <p class="tenant-hint">Chỉ họ tên là bắt buộc. Có thể bổ sung thông tin liên hệ '
                             'và CCCD sau.</p>\n'
                             '        <details class="tenant-extra" {% if form.user.errors or '
                             'form.identity_issued_date.errors or form.emergency_contact.errors %}open{% endif %}>\n'
                             '          <summary>Thông tin bổ sung và tài khoản</summary>\n'
                             '          <div class="tenant-field-grid">\n'
                             '            <label for="{{ form.identity_issued_date.id_for_label }}">Ngày cấp CCCD{{ '
                             'form.identity_issued_date }}{{ form.identity_issued_date.errors }}</label>\n'
                             '            <label for="{{ form.emergency_contact.id_for_label }}">Liên hệ khẩn cấp{{ '
                             'form.emergency_contact }}{{ form.emergency_contact.errors }}</label>\n'
                             '            <label class="tenant-full" for="{{ form.user.id_for_label }}">Tài khoản đăng '
                             'nhập liên kết{{ form.user }}{{ form.user.errors }}</label>\n'
                             '          </div>\n'
                             '        </details>\n'
                             '        <label class="tenant-active">{{ form.is_active }} Đang hoạt động</label>\n'
                             '      </div>\n'
                             '      <div class="tenant-tab-panel" id="tenant-images" role="tabpanel" '
                             'aria-labelledby="tenant-images-tab">\n'
                             '        <h3><i data-lucide="credit-card"></i>Ảnh CCCD</h3>\n'
                             '        <div class="tenant-image-grid">\n'
                             '          <div class="tenant-image-card" data-side="front" data-existing="{% if '
                             'front_image %}true{% else %}false{% endif %}">\n'
                             '            <div class="tenant-upload-heading"><strong>Mặt trước CCCD</strong><label '
                             'class="tenant-upload-button" for="{{ form.identity_front.id_for_label }}"><i '
                             'data-lucide="upload"></i>Upload</label></div>\n'
                             '            {{ form.identity_front }}{{ form.identity_front.errors }}\n'
                             '            <div class="tenant-image-preview">\n'
                             '              <img {% if front_image %}src="{% url \'tenant-identity-image\' tenant.id '
                             '\'front\' %}"{% else %}hidden{% endif %} alt="Ảnh CCCD mặt trước" '
                             'referrerpolicy="no-referrer">\n'
                             '              <span {% if front_image %}hidden{% endif %}><i '
                             'data-lucide="image"></i>Chưa có ảnh CCCD mặt trước</span>\n'
                             '            </div>\n'
                             '            <button class="tenant-clear-selection" type="button" hidden>Bỏ ảnh vừa '
                             'chọn</button>\n'
                             '            {% if front_image %}<label class="tenant-remove">{{ '
                             'form.remove_identity_front }} Xóa ảnh mặt trước đã lưu</label>{% endif %}\n'
                             '          </div>\n'
                             '          <div class="tenant-image-card" data-side="back" data-existing="{% if '
                             'back_image %}true{% else %}false{% endif %}">\n'
                             '            <div class="tenant-upload-heading"><strong>Mặt sau CCCD</strong><label '
                             'class="tenant-upload-button" for="{{ form.identity_back.id_for_label }}"><i '
                             'data-lucide="upload"></i>Upload</label></div>\n'
                             '            {{ form.identity_back }}{{ form.identity_back.errors }}\n'
                             '            <div class="tenant-image-preview">\n'
                             '              <img {% if back_image %}src="{% url \'tenant-identity-image\' tenant.id '
                             '\'back\' %}"{% else %}hidden{% endif %} alt="Ảnh CCCD mặt sau" '
                             'referrerpolicy="no-referrer">\n'
                             '              <span {% if back_image %}hidden{% endif %}><i data-lucide="image"></i>Chưa '
                             'có ảnh CCCD mặt sau</span>\n'
                             '            </div>\n'
                             '            <button class="tenant-clear-selection" type="button" hidden>Bỏ ảnh vừa '
                             'chọn</button>\n'
                             '            {% if back_image %}<label class="tenant-remove">{{ form.remove_identity_back '
                             '}} Xóa ảnh mặt sau đã lưu</label>{% endif %}\n'
                             '          </div>\n'
                             '        </div>\n'
                             '        <p class="tenant-image-status" role="status">Ảnh CCCD không bắt buộc</p>\n'
                             '        <p class="tenant-hint">JPG, PNG hoặc WebP · Tối đa 5 MB mỗi ảnh. Ảnh được lưu '
                             'riêng tư và chỉ người quản lý có quyền mới xem được.</p>\n'
                             '      </div>\n'
                             '      <footer class="tenant-form-footer"><a class="tenant-cancel" href="{% url '
                             '\'tenants\' %}">Hủy</a><button class="tenant-submit" type="submit">{% if editing %}Lưu '
                             'thay đổi{% else %}Thêm mới{% endif %}</button></footer>\n'
                             '    </form>\n'
                             '  </section>\n'
                             '</div>\n'
                             '<script src="{% static \'js/tenant-form.js\' %}"></script>\n'
                             '{% endblock %}\n',
 'rentals/tenant_list.html': '{% extends "base.html" %}\n'
                             '{% block page_title %}Khách thuê{% endblock %}\n'
                             '{% block content %}\n'
                             '<div class="page-actions room-toolbar">\n'
                             '  <form method="get" class="room-filters">\n'
                             '    <input name="q" value="{{ q }}" placeholder="Tìm họ tên, điện thoại, CCCD...">\n'
                             '    <select name="status">\n'
                             '      <option value="">Tất cả trạng thái</option>\n'
                             '      <option value="active" {% if status == \'active\' %}selected{% endif %}>Đang hoạt '
                             'động</option>\n'
                             '      <option value="inactive" {% if status == \'inactive\' %}selected{% endif %}>Ngừng '
                             'kích hoạt</option>\n'
                             '    </select>\n'
                             '    <button class="btn" type="submit">Lọc dữ liệu</button>\n'
                             '    {% if q or status %}<a class="btn" href="{% url \'tenants\' %}">Xóa lọc</a>{% endif '
                             '%}\n'
                             '  </form>\n'
                             '  <a class="btn primary" href="{% url \'tenant-create\' %}">Thêm khách thuê</a>\n'
                             '</div>\n'
                             '<section class="panel">\n'
                             '  <div class="list-summary"><span>Danh sách khách thuê</span><span>Tổng số: <strong>{{ '
                             'paginator.count }}</strong></span></div>\n'
                             '  <div class="table-wrap">\n'
                             '    <table>\n'
                             '      <thead>\n'
                             '        <tr>\n'
                             '          <th class="row-number">STT</th>\n'
                             '          <th>Họ tên</th>\n'
                             '          <th>Điện thoại</th>\n'
                             '          <th>Email</th>\n'
                             '          <th>CCCD/Hộ chiếu</th>\n'
                             '          <th>Tài khoản</th>\n'
                             '          <th>Trạng thái</th>\n'
                             '          <th>Thao tác</th>\n'
                             '        </tr>\n'
                             '      </thead>\n'
                             '      <tbody>\n'
                             '        {% for x in objects %}\n'
                             '        <tr>\n'
                             '          <td class="row-number">{{ page_obj.start_index|add:forloop.counter0 }}</td>\n'
                             '          <td><a href="{% url \'tenant-detail\' x.id %}" '
                             'style="font-weight:600;color:var(--primary);text-decoration:none;">{{ x.full_name '
                             '}}</a></td>\n'
                             '          <td>{{ x.phone|default:"—" }}</td>\n'
                             '          <td>{{ x.email|default:"—" }}</td>\n'
                             '          <td>{{ x.identity_number|default:"—" }}</td>\n'
                             '          <td>{% if x.user %}<span class="badge">{{ x.user.username }}</span>{% else '
                             '%}<span class="muted">Chưa liên kết</span>{% endif %}</td>\n'
                             '          <td>\n'
                             '            <span class="status-pill {% if x.is_active %}active{% else %}inactive{% '
                             'endif %}">\n'
                             '              <b></b>{{ x.is_active|yesno:"Hoạt động,Ngừng" }}\n'
                             '            </span>\n'
                             '          </td>\n'
                             '          <td>\n'
                             '            <div style="display:flex;gap:6px;">\n'
                             '              <a class="btn compact" href="{% url \'tenant-detail\' x.id %}">Chi '
                             'tiết</a>\n'
                             '              <a class="btn compact" href="{% url \'tenant-update\' x.id %}">Sửa</a>\n'
                             '            </div>\n'
                             '          </td>\n'
                             '        </tr>\n'
                             '        {% empty %}\n'
                             '        <tr><td colspan="8">Chưa có dữ liệu khách thuê phù hợp.</td></tr>\n'
                             '        {% endfor %}\n'
                             '      </tbody>\n'
                             '    </table>\n'
                             '  </div>\n'
                             '</section>\n'
                             '{% if page_obj.has_other_pages %}\n'
                             '<nav class="pagination" aria-label="Phân trang khách thuê">\n'
                             '  {% if page_obj.has_previous %}<a href="?page={{ page_obj.previous_page_number }}&q={{ '
                             'q|urlencode }}&status={{ status }}">← Trước</a>{% else %}<span class="disabled">← '
                             'Trước</span>{% endif %}\n'
                             '  {% for page_number in paginator.page_range %}{% if page_number == page_obj.number '
                             '%}<span class="current">{{ page_number }}</span>{% elif page_number >= '
                             "page_obj.number|add:'-2' and page_number <= page_obj.number|add:'2' %}<a "
                             'href="?page={{ page_number }}&q={{ q|urlencode }}&status={{ status }}">{{ page_number '
                             '}}</a>{% endif %}{% endfor %}\n'
                             '  {% if page_obj.has_next %}<a href="?page={{ page_obj.next_page_number }}&q={{ '
                             'q|urlencode }}&status={{ status }}">Sau →</a>{% else %}<span class="disabled">Sau '
                             '→</span>{% endif %}\n'
                             '</nav>\n'
                             '{% endif %}\n'
                             '{% endblock %}\n',
 'tenant/contracts.html': '{% extends "base.html" %}{% block page_title %}Hợp đồng của tôi{% endblock %}{% block '
                          'content %}<section class="panel"><table><thead><tr><th>Mã</th><th>Phòng</th><th>Tòa '
                          'nhà</th><th>Thời hạn</th><th>Tiền thuê</th><th>Trạng thái</th></tr></thead><tbody>{% for x '
                          'in objects %}<tr><td>{{ x.code }}</td><td>{{ x.room.number }}</td><td>{{ '
                          'x.room.building.name }}</td><td>{{ x.start_date|date:"d/m/Y" }} – {{ '
                          'x.end_date|date:"d/m/Y" }}</td><td>{{ x.monthly_rent|vnd }} đ</td><td><span '
                          'class="badge">{{ x.get_status_display }}</span></td></tr>{% empty %}<tr><td colspan="6">Bạn '
                          'chưa có hợp đồng.</td></tr>{% endfor %}</tbody></table></section>{% endblock %}\n',
 'tenant/incident_form.html': '{% extends "base.html" %}{% block page_title %}Gửi yêu cầu hỗ trợ{% endblock %}{% block '
                              'content %}<section class="panel form-panel"><h1>Báo sự cố trong phòng</h1><p '
                              'class="muted">Mô tả rõ tình trạng để bộ phận quản lý xử lý nhanh hơn.</p><form '
                              'method="post">{% csrf_token %}{{ form.as_p }}<div class="actions"><button class="btn '
                              'primary" type="submit">Gửi yêu cầu</button><a class="btn" href="{% url '
                              '\'tenant-incidents\' %}">Hủy</a></div></form></section>{% endblock %}\n',
 'tenant/incidents.html': '{% extends "base.html" %}{% block page_title %}Yêu cầu hỗ trợ{% endblock %}{% block content '
                          '%}<div class="page-actions"><span></span><a class="btn primary" href="{% url '
                          '\'tenant-incident-create\' %}">Gửi yêu cầu mới</a></div><section '
                          'class="panel"><table><thead><tr><th>Ngày gửi</th><th>Phòng</th><th>Nội dung</th><th>Ưu '
                          'tiên</th><th>Trạng thái</th><th>Người xử lý</th></tr></thead><tbody>{% for x in objects '
                          '%}<tr><td>{{ x.created_at|date:"d/m/Y H:i" }}</td><td>{{ x.room.number '
                          '}}</td><td><strong>{{ x.title }}</strong><br><span class="muted">{{ '
                          'x.description|truncatechars:80 }}</span></td><td>{{ x.get_priority_display }}</td><td><span '
                          'class="badge">{{ x.get_status_display }}</span></td><td>{{ x.assigned_to|default:"Chưa phân '
                          'công" }}</td></tr>{% empty %}<tr><td colspan="6">Bạn chưa gửi yêu cầu nào.</td></tr>{% '
                          'endfor %}</tbody></table></section>{% endblock %}\n',
 'tenant/invoice_detail.html': '{% extends "base.html" %}{% block page_title %}Hóa đơn {{ invoice.code }}{% endblock '
                               '%}{% block content %}<section class="panel invoice-sheet"><div '
                               'class="detail-grid"><div><span>Kỳ hóa đơn</span><strong>{{ invoice.period|date:"m/Y" '
                               '}}</strong></div><div><span>Phòng</span><strong>{{ invoice.contract.room '
                               '}}</strong></div><div><span>Ngày phát hành</span><strong>{{ '
                               'invoice.issued_date|date:"d/m/Y" }}</strong></div><div><span>Hạn thanh '
                               'toán</span><strong>{{ invoice.due_date|date:"d/m/Y" }}</strong></div></div><h2>Chi '
                               'tiết</h2><table><thead><tr><th>Nội dung</th><th>Số lượng</th><th>Đơn giá</th><th>Thành '
                               'tiền</th></tr></thead><tbody>{% for x in invoice.items.all %}<tr><td>{{ x.description '
                               '}}</td><td>{{ x.quantity }}</td><td>{{ x.unit_price|vnd }} đ</td><td>{{ x.amount|vnd '
                               '}} đ</td></tr>{% endfor %}</tbody><tfoot><tr><th colspan="3">Tổng cộng</th><th>{{ '
                               'invoice.total_amount|vnd }} đ</th></tr><tr><th colspan="3">Đã thanh toán</th><th>{{ '
                               'invoice.paid_amount|vnd }} đ</th></tr><tr><th colspan="3">Còn nợ</th><th>{{ '
                               'invoice.balance|vnd }} đ</th></tr></tfoot></table><h2>Lịch sử thanh '
                               'toán</h2><table><thead><tr><th>Thời gian</th><th>Số tiền</th><th>Phương '
                               'thức</th><th>Tham chiếu</th></tr></thead><tbody>{% for x in invoice.payments.all %}{% '
                               'if not x.is_void %}<tr><td>{{ x.paid_at|date:"d/m/Y H:i" }}</td><td>{{ x.amount|vnd }} '
                               'đ</td><td>{{ x.get_method_display }}</td><td>{{ x.reference|default:"—" }}</td></tr>{% '
                               'endif %}{% empty %}<tr><td colspan="4">Chưa có thanh toán.</td></tr>{% endfor '
                               '%}</tbody></table></section>{% endblock %}\n',
 'tenant/invoices.html': '{% extends "base.html" %}{% block page_title %}Hóa đơn của tôi{% endblock %}{% block content '
                         '%}<section class="panel"><table><thead><tr><th>Mã hóa '
                         'đơn</th><th>Kỳ</th><th>Phòng</th><th>Tổng tiền</th><th>Đã trả</th><th>Còn nợ</th><th>Trạng '
                         'thái</th></tr></thead><tbody>{% for x in objects %}<tr><td><a href="{% url '
                         '\'tenant-invoice-detail\' x.id %}">{{ x.code }}</a></td><td>{{ x.period|date:"m/Y" '
                         '}}</td><td>{{ x.contract.room.number }}</td><td>{{ x.total_amount|vnd }} đ</td><td>{{ '
                         'x.paid_amount|vnd }} đ</td><td>{{ x.balance|vnd }} đ</td><td><span class="badge">{{ '
                         'x.get_status_display }}</span></td></tr>{% empty %}<tr><td colspan="7">Bạn chưa có hóa '
                         'đơn.</td></tr>{% endfor %}</tbody></table></section>{% endblock %}\n',
 'tenant/notifications.html': '{% extends "base.html" %}\n'
                              '{% block page_title %}Thông báo{% endblock %}\n'
                              '{% block content %}\n'
                              '<div class="page-actions" style="align-items:center;">\n'
                              '  <div>Bạn có <strong>{{ unread_count|default:0 }}</strong> thông báo chưa đọc.</div>\n'
                              '  {% if unread_count %}\n'
                              '  <form method="post" action="{% url \'tenant-notifications\' %}">\n'
                              '    {% csrf_token %}\n'
                              '    <input type="hidden" name="mark_all" value="1">\n'
                              '    <button class="btn" type="submit">Đánh dấu tất cả đã đọc</button>\n'
                              '  </form>\n'
                              '  {% endif %}\n'
                              '</div>\n'
                              '<section class="notification-list">\n'
                              '  {% for x in objects %}\n'
                              '  <article class="panel notification" style="{% if not x.is_read %}border-left:4px '
                              'solid var(--primary);{% endif %}">\n'
                              '    <div>\n'
                              '      <div style="display:flex;gap:8px;align-items:center;margin-bottom:4px;">\n'
                              '        <h2 style="margin:0;">{{ x.title }}</h2>\n'
                              '        {% if x.is_read %}\n'
                              '        <span class="badge">Đã đọc</span>\n'
                              '        {% else %}\n'
                              '        <span class="badge" style="background:#fff2d8;color:#b27400;">Mới</span>\n'
                              '        {% endif %}\n'
                              '      </div>\n'
                              '      <p>{{ x.content }}</p>\n'
                              '    </div>\n'
                              '    <div style="display:flex;flex-direction:column;align-items:flex-end;gap:8px;">\n'
                              '      <time>{{ x.created_at|date:"d/m/Y H:i" }}</time>\n'
                              '      {% if not x.is_read %}\n'
                              '      <form method="post" action="{% url \'tenant-notification-mark-read\' x.id %}">\n'
                              '        {% csrf_token %}\n'
                              '        <button class="btn compact primary" type="submit">Đánh dấu đã đọc</button>\n'
                              '      </form>\n'
                              '      {% endif %}\n'
                              '    </div>\n'
                              '  </article>\n'
                              '  {% empty %}\n'
                              '  <article class="panel">Bạn chưa có thông báo.</article>\n'
                              '  {% endfor %}\n'
                              '</section>\n'
                              '{% endblock %}\n',
 'tenant/payments.html': '{% extends "base.html" %}\n'
                         '{% block title %}Lịch sử thanh toán — QL Phòng Cho Thuê{% endblock %}\n'
                         '{% block page_title %}Lịch sử thanh toán{% endblock %}\n'
                         '{% block page_subtitle %}Danh sách các khoản thanh toán tiền phòng và dịch vụ của bạn{% '
                         'endblock %}\n'
                         '\n'
                         '{% block content %}\n'
                         '<section class="stats-grid" style="margin-bottom: 20px;">\n'
                         '  <article class="stat success">\n'
                         '    <span>Tổng tiền đã thanh toán</span>\n'
                         '    <strong>{{ total_paid|vnd }} đ</strong>\n'
                         '  </article>\n'
                         '  <article class="stat info">\n'
                         '    <span>Số giao dịch</span>\n'
                         '    <strong>{{ objects|length }}</strong>\n'
                         '  </article>\n'
                         '</section>\n'
                         '\n'
                         '<section class="panel">\n'
                         '  <div class="panel-heading" style="margin-bottom: 16px;">\n'
                         '    <h2>Giao dịch thanh toán</h2>\n'
                         '  </div>\n'
                         '  <table>\n'
                         '    <thead>\n'
                         '      <tr>\n'
                         '        <th>Thời gian</th>\n'
                         '        <th>Hóa đơn</th>\n'
                         '        <th>Phòng / Tòa nhà</th>\n'
                         '        <th>Số tiền</th>\n'
                         '        <th>Phương thức</th>\n'
                         '        <th>Mã tham chiếu</th>\n'
                         '        <th>Ghi chú</th>\n'
                         '      </tr>\n'
                         '    </thead>\n'
                         '    <tbody>\n'
                         '      {% for p in objects %}\n'
                         '        <tr>\n'
                         '          <td>{{ p.paid_at|date:"d/m/Y H:i" }}</td>\n'
                         '          <td>\n'
                         '            <a href="{% url \'tenant-invoice-detail\' p.invoice.id %}" style="font-weight: '
                         '600;">\n'
                         '              {{ p.invoice.code }} (Kỳ {{ p.invoice.period|date:"m/Y" }})\n'
                         '            </a>\n'
                         '          </td>\n'
                         '          <td>\n'
                         '            <strong>{{ p.invoice.contract.room.number }}</strong> \n'
                         '            <small style="color: var(--muted);">({{ p.invoice.contract.room.building.name '
                         '}})</small>\n'
                         '          </td>\n'
                         '          <td style="color: var(--green); font-weight: 700;">\n'
                         '            +{{ p.amount|vnd }} đ\n'
                         '          </td>\n'
                         '          <td>\n'
                         '            <span class="badge" style="background: #ffedd5; color: #9a3412; border: 1px '
                         'solid #fed7aa;">\n'
                         '              {{ p.get_method_display }}\n'
                         '            </span>\n'
                         '          </td>\n'
                         '          <td>{{ p.reference|default:"—" }}</td>\n'
                         '          <td>{{ p.notes|default:"—" }}</td>\n'
                         '        </tr>\n'
                         '      {% empty %}\n'
                         '        <tr>\n'
                         '          <td colspan="7" style="text-align: center; color: var(--muted); padding: 32px '
                         '16px;">\n'
                         '            Bạn chưa có lịch sử thanh toán nào.\n'
                         '          </td>\n'
                         '        </tr>\n'
                         '      {% endfor %}\n'
                         '    </tbody>\n'
                         '  </table>\n'
                         '</section>\n'
                         '{% endblock %}\n'
                         '\n',
 'tenant/portal.html': '{% extends "base.html" %}\n'
                       '{% block title %}Trang người thuê — QL Phòng Cho Thuê{% endblock %}\n'
                       '{% block page_title %}Xin chào, {{ tenant.full_name }}{% endblock %}\n'
                       '{% block page_subtitle %}Cổng thông tin dành cho khách thuê: theo dõi phòng, hợp đồng, hóa đơn '
                       'và yêu cầu hỗ trợ{% endblock %}\n'
                       '\n'
                       '{% block content %}\n'
                       '<section class="stats-grid tenant-stats-grid">\n'
                       '  <article class="stat">\n'
                       '    <span>Phòng đang thuê</span>\n'
                       '    <strong>{% if active_contract %}Phòng {{ active_contract.room.number }}{% else %}—{% endif '
                       '%}</strong>\n'
                       '  </article>\n'
                       '  <article class="stat">\n'
                       '    <span>Tòa nhà</span>\n'
                       '    <strong class="small-value">{% if active_contract %}{{ active_contract.room.building.name '
                       '}}{% else %}Chưa có{% endif %}</strong>\n'
                       '  </article>\n'
                       '  <article class="stat">\n'
                       '    <span>Tổng cần thanh toán</span>\n'
                       '    <strong style="color: {% if total_debt > 0 %}#c2410c{% else %}#15803d{% endif %};">{{ '
                       'total_debt|vnd }} đ</strong>\n'
                       '  </article>\n'
                       '  <article class="stat">\n'
                       '    <span>Thông báo chưa đọc</span>\n'
                       '    <strong style="color: {% if unread_count > 0 %}#ea580c{% else %}#78716c{% endif %};">{{ '
                       'unread_count }}</strong>\n'
                       '  </article>\n'
                       '</section>\n'
                       '\n'
                       '{% if active_contract %}\n'
                       '<section class="panel tenant-room-card">\n'
                       '  <div class="panel-heading">\n'
                       '    <div>\n'
                       '      <span class="tenant-badge-eyebrow">{{ active_contract.room.building.name }}</span>\n'
                       '      <h2>Thông tin phòng thuê hiện tại</h2>\n'
                       '    </div>\n'
                       '    <span class="badge" style="background:#ecfdf5;color:#047857;border:1px solid '
                       '#a7f3d0;font-size:13px;">{{ active_contract.get_status_display }}</span>\n'
                       '  </div>\n'
                       '  <div class="detail-grid">\n'
                       '    <div>\n'
                       '      <span>Mã hợp đồng</span>\n'
                       '      <strong style="color:#c2410c;font-family:monospace;font-size:15px;">{{ '
                       'active_contract.code }}</strong>\n'
                       '    </div>\n'
                       '    <div>\n'
                       '      <span>Thời hạn hợp đồng</span>\n'
                       '      <strong>{{ active_contract.start_date|date:"d/m/Y" }} – {{ '
                       'active_contract.end_date|date:"d/m/Y" }}</strong>\n'
                       '    </div>\n'
                       '    <div>\n'
                       '      <span>Giá thuê hàng tháng</span>\n'
                       '      <strong style="color:#c2410c;font-size:17px;">{{ active_contract.monthly_rent|vnd }} '
                       'đ/tháng</strong>\n'
                       '    </div>\n'
                       '    <div>\n'
                       '      <span>Tiền cọc giữ chỗ</span>\n'
                       '      <strong>{{ active_contract.deposit_amount|vnd }} đ</strong>\n'
                       '    </div>\n'
                       '    <div>\n'
                       '      <span>Địa chỉ tòa nhà</span>\n'
                       '      <strong>{{ active_contract.room.building.address }}</strong>\n'
                       '    </div>\n'
                       '    <div>\n'
                       '      <span>Tầng / Diện tích</span>\n'
                       '      <strong>Tầng {{ active_contract.room.floor }}{% if active_contract.room.area %} · {{ '
                       'active_contract.room.area }} m²{% endif %}</strong>\n'
                       '    </div>\n'
                       '  </div>\n'
                       '</section>\n'
                       '{% endif %}\n'
                       '\n'
                       '<section class="two-columns">\n'
                       '  <article class="panel">\n'
                       '    <div class="panel-heading">\n'
                       '      <h2>Hóa đơn cần thanh toán</h2>\n'
                       '      <a class="panel-more-link" href="{% url \'tenant-invoices\' %}">Xem tất cả <i '
                       'data-lucide="arrow-right"></i></a>\n'
                       '    </div>\n'
                       '    <table class="dashboard-table">\n'
                       '      <thead>\n'
                       '        <tr>\n'
                       '          <th>Kỳ hóa đơn</th>\n'
                       '          <th>Còn nợ</th>\n'
                       '          <th>Hạn thanh toán</th>\n'
                       '          <th></th>\n'
                       '        </tr>\n'
                       '      </thead>\n'
                       '      <tbody>\n'
                       '        {% for x in unpaid_invoices %}\n'
                       '        <tr>\n'
                       '          <td>\n'
                       '            <a class="table-code-link" href="{% url \'tenant-invoice-detail\' x.id %}">\n'
                       '              {{ x.code }} ({{ x.period|date:"m/Y" }})\n'
                       '            </a>\n'
                       '          </td>\n'
                       '          <td><strong style="color:#c2410c;font-weight:750;">{{ x.balance|vnd }} '
                       'đ</strong></td>\n'
                       '          <td><span class="table-date-val">{{ x.due_date|date:"d/m/Y" }}</span></td>\n'
                       '          <td style="text-align:right;">\n'
                       '            <a class="btn primary compact" href="{% url \'tenant-invoice-detail\' x.id %}">Chi '
                       'tiết</a>\n'
                       '          </td>\n'
                       '        </tr>\n'
                       '        {% empty %}\n'
                       '        <tr>\n'
                       '          <td colspan="4" class="table-empty">Bạn không có hóa đơn nào cần thanh toán.</td>\n'
                       '        </tr>\n'
                       '        {% endfor %}\n'
                       '      </tbody>\n'
                       '    </table>\n'
                       '  </article>\n'
                       '\n'
                       '  <article class="panel">\n'
                       '    <div class="panel-heading">\n'
                       '      <h2>Yêu cầu hỗ trợ gần đây</h2>\n'
                       '      <a class="btn primary compact" href="{% url \'tenant-incident-create\' %}"><i '
                       'data-lucide="plus"></i> Gửi yêu cầu</a>\n'
                       '    </div>\n'
                       '    <table class="dashboard-table">\n'
                       '      <thead>\n'
                       '        <tr>\n'
                       '          <th>Nội dung yêu cầu</th>\n'
                       '          <th>Ngày gửi</th>\n'
                       '          <th>Trạng thái</th>\n'
                       '        </tr>\n'
                       '      </thead>\n'
                       '      <tbody>\n'
                       '        {% for x in incidents %}\n'
                       '        <tr>\n'
                       '          <td>\n'
                       '            <strong style="color:#431407;font-size:13.5px;">{{ x.title }}</strong>\n'
                       '            {% if x.description %}<div style="font-size:12px;color:#78716c;margin-top:2px;">{{ '
                       'x.description|truncatechars:45 }}</div>{% endif %}\n'
                       '          </td>\n'
                       '          <td><span class="table-date-val">{{ x.created_at|date:"d/m/Y" }}</span></td>\n'
                       '          <td><span class="badge">{{ x.get_status_display }}</span></td>\n'
                       '        </tr>\n'
                       '        {% empty %}\n'
                       '        <tr>\n'
                       '          <td colspan="3" class="table-empty">Bạn chưa gửi yêu cầu hỗ trợ nào.</td>\n'
                       '        </tr>\n'
                       '        {% endfor %}\n'
                       '      </tbody>\n'
                       '    </table>\n'
                       '  </article>\n'
                       '</section>\n'
                       '{% endblock %}\n',
 'tenant/rooms.html': '{% extends "base.html" %}\n'
                      '{% block title %}Phòng của tôi — QL Phòng Cho Thuê{% endblock %}\n'
                      '{% block page_title %}Phòng của tôi{% endblock %}\n'
                      '{% block page_subtitle %}Thông tin chi tiết các phòng bạn đang thuê và đã thuê{% endblock %}\n'
                      '\n'
                      '{% block content %}\n'
                      '<div class="tenant-rooms-container" style="display: grid; gap: 24px;">\n'
                      '  {% for contract in contracts %}\n'
                      '    <section class="panel" style="padding: 24px;">\n'
                      '      <div style="display: flex; justify-content: space-between; align-items: start; '
                      'border-bottom: 1px solid var(--line); padding-bottom: 16px; margin-bottom: 20px; flex-wrap: '
                      'wrap; gap: 12px;">\n'
                      '        <div>\n'
                      '          <span style="font-size: 13px; color: var(--primary); font-weight: 700; '
                      'text-transform: uppercase;">\n'
                      '            {{ contract.room.building.name }}\n'
                      '          </span>\n'
                      '          <h2 style="margin: 4px 0 6px 0; font-size: 24px;">Phòng {{ contract.room.number '
                      '}}</h2>\n'
                      '          <p style="margin: 0; color: var(--muted); font-size: 14px;">\n'
                      '            <i data-lucide="map-pin" style="width: 14px; height: 14px; display: inline-block; '
                      'vertical-align: middle;"></i>\n'
                      '            {{ contract.room.building.address }}\n'
                      '          </p>\n'
                      '        </div>\n'
                      '        <div style="text-align: right;">\n'
                      '          <span class="badge" style="font-size: 13px;">{{ contract.get_status_display '
                      '}}</span>\n'
                      '          <div style="margin-top: 6px; font-size: 13px; color: var(--muted);">\n'
                      '            Hợp đồng: <strong>{{ contract.code }}</strong>\n'
                      '          </div>\n'
                      '        </div>\n'
                      '      </div>\n'
                      '\n'
                      '      <div class="detail-grid" style="margin-bottom: 24px;">\n'
                      '        <div>\n'
                      '          <span>Tầng</span>\n'
                      '          <strong>Tầng {{ contract.room.floor }}</strong>\n'
                      '        </div>\n'
                      '        <div>\n'
                      '          <span>Diện tích</span>\n'
                      '          <strong>{% if contract.room.area %}{{ contract.room.area }} m²{% else %}—{% endif '
                      '%}</strong>\n'
                      '        </div>\n'
                      '        <div>\n'
                      '          <span>Giá thuê hợp đồng</span>\n'
                      '          <strong style="color: var(--primary);">{{ contract.monthly_rent|vnd }} '
                      'đ/tháng</strong>\n'
                      '        </div>\n'
                      '        <div>\n'
                      '          <span>Tiền cọc</span>\n'
                      '          <strong>{{ contract.deposit_amount|vnd }} đ</strong>\n'
                      '        </div>\n'
                      '        <div>\n'
                      '          <span>Thời hạn thuê</span>\n'
                      '          <strong>{{ contract.start_date|date:"d/m/Y" }} – {{ contract.end_date|date:"d/m/Y" '
                      '}}</strong>\n'
                      '        </div>\n'
                      '        <div>\n'
                      '          <span>Người đại diện</span>\n'
                      '          <strong>{{ contract.representative.full_name }}</strong>\n'
                      '        </div>\n'
                      '      </div>\n'
                      '\n'
                      '      <!-- Tiện nghi phòng -->\n'
                      '      {% if contract.room.amenities.all %}\n'
                      '        <div style="margin-bottom: 20px;">\n'
                      '          <h3 style="font-size: 15px; margin-bottom: 10px; color: var(--ink);">Tiện nghi '
                      'phòng:</h3>\n'
                      '          <div style="display: flex; flex-wrap: wrap; gap: 8px;">\n'
                      '            {% for a in contract.room.amenities.all %}\n'
                      '              <span class="badge" style="background: var(--bg); color: var(--ink); border: 1px '
                      'solid var(--line); font-size: 12px; padding: 6px 12px;">\n'
                      '                {{ a.name }}\n'
                      '              </span>\n'
                      '            {% endfor %}\n'
                      '          </div>\n'
                      '        </div>\n'
                      '      {% endif %}\n'
                      '\n'
                      '      <!-- Thành viên cùng phòng -->\n'
                      '      {% if contract.members.all %}\n'
                      '        <div style="margin-bottom: 20px; border-top: 1px solid var(--line); padding-top: '
                      '16px;">\n'
                      '          <h3 style="font-size: 15px; margin-bottom: 10px; color: var(--ink);">Thành viên trong '
                      'phòng:</h3>\n'
                      '          <div style="display: flex; flex-wrap: wrap; gap: 12px;">\n'
                      '            {% for m in contract.members.all %}\n'
                      '              <div style="background: #fff7ed; border: 1px solid var(--line); border-radius: '
                      '8px; padding: 8px 14px; font-size: 13px;">\n'
                      '                <strong>{{ m.tenant.full_name }}</strong>\n'
                      '                {% if m.tenant.phone %}<span style="color: var(--muted); margin-left: 6px;">({{ '
                      'm.tenant.phone }})</span>{% endif %}\n'
                      '                <small style="display: block; color: var(--muted); margin-top: 2px;">Vào ở: {{ '
                      'm.joined_date|date:"d/m/Y" }}</small>\n'
                      '              </div>\n'
                      '            {% endfor %}\n'
                      '          </div>\n'
                      '        </div>\n'
                      '      {% endif %}\n'
                      '\n'
                      '      <!-- Thao tác nhanh -->\n'
                      '      <div style="display: flex; gap: 12px; border-top: 1px solid var(--line); padding-top: '
                      '16px; margin-top: 16px; flex-wrap: wrap;">\n'
                      '        <a class="btn compact" href="{% url \'room-walkthrough\' contract.room.id %}">\n'
                      '          <i data-lucide="person-standing" style="width: 14px; height: 14px; display: '
                      'inline-block; vertical-align: middle;"></i>\n'
                      '          Tham quan 3D\n'
                      '        </a>\n'
                      '        <a class="btn primary compact" href="{% url \'tenant-incident-create\' %}">\n'
                      '          <i data-lucide="triangle-alert" style="width: 14px; height: 14px; display: '
                      'inline-block; vertical-align: middle;"></i>\n'
                      '          Báo sự cố phòng này\n'
                      '        </a>\n'
                      '        <a class="btn compact" href="{% url \'tenant-invoices\' %}">\n'
                      '          <i data-lucide="receipt-text" style="width: 14px; height: 14px; display: '
                      'inline-block; vertical-align: middle;"></i>\n'
                      '          Xem hóa đơn\n'
                      '        </a>\n'
                      '      </div>\n'
                      '    </section>\n'
                      '  {% empty %}\n'
                      '    <section class="panel" style="text-align: center; padding: 48px 24px; color: '
                      'var(--muted);">\n'
                      '      <p style="font-size: 16px; margin-bottom: 12px;">Bạn hiện chưa có phòng thuê nào được ghi '
                      'nhận trong hệ thống.</p>\n'
                      '      <a href="{% url \'public-rooms\' %}" class="btn primary">Tìm phòng cho thuê</a>\n'
                      '    </section>\n'
                      '  {% endfor %}\n'
                      '</div>\n'
                      '{% endblock %}\n'
                      '\n'}

